  function sideItem(label,route,ico='chevron',indent=false,canonical=true){const related={
      'entra/home':['entra/unused-service'],'entra/users':['entra/user/'],'entra/groups':['entra/group/'],'entra/roles':['entra/role/'],'entra/aus':['entra/au/'],'entra/apps':['entra/app/'],
      'm365/users':['m365/user/'],'m365/groups':['m365/group/'],
      'entra/enterprise':['entra/service/']
    };const exactOnly=ui.route.startsWith('m365/')&&['m365/copilot','m365/agents'].includes(route);const selected=canonical&&(ui.route===route||!exactOnly&&ui.route.startsWith(route+'/')||(related[route]||[]).some(prefix=>ui.route.startsWith(prefix)))&&!(ui.route.startsWith('m365/')&&route==='m365/licenses'&&label==='Vos produits');return `<button type="button" class="side-item ${indent?'indent':''} ${selected?'selected':''}" data-route="${attr(route)}" title="${attr(label)}"${ui.route.startsWith('m365/')&&selected&&!(route==='m365/licenses'&&label==='Vos produits')?' aria-current="page"':''}>${route==='entra/home'&&ui.route.startsWith('entra/')?`<svg class="ico entra-home-icon" style="stroke:none" viewBox="0 0 16 16" aria-hidden="true"><path d="M1.1 7.25 8 1.25l6.9 6-1.05 1.2L8 3.34 2.15 8.45z" fill="#0078d4"/><path d="M3.05 7.35 8 3.03l4.95 4.32v6.9H9.65v-4.2h-3.3v4.2h-3.3z" fill="#29a6ed"/><path d="M3.05 7.35 8 3.03l4.95 4.32v.9L8 4 3.05 8.25z" fill="#005fb8"/><path d="M9.65 10.05h1.05v4.2H9.65z" fill="#0078d4"/></svg>`:ui.route.startsWith('entra/')?entraSideIcon(route,ico):m365AssetIcon(ico)}<span class="side-label">${esc(label)}</span></button>`;}
  const m365NavItems=[['users','Utilisateurs'],['copilot','Copilot'],['agents','Agents'],['apps','Applications'],['groups','Teams et groupes'],['roles','Rôles'],['resources','Ressources'],['marketplace','Marketplace'],['billing','Facturation'],['support','Support'],['settings','Paramètres'],['setup','Setup'],['reports','Rapports'],['health','État d’intégrité'],['security','Sécurité'],['purview','Microsoft Purview'],['identity','Identité'],['azure','Azure'],['exchange','Exchange'],['sharepoint','SharePoint'],['teams','Teams'],['power','Power Platform'],['allCenters','Tous les centres d’administration']];
