      s+=sideItem('Accueil','exchange/home','home');
      s+=section('Destinataires','recipients','user',[['Boîtes aux lettres','mailboxes'],['Groupes','groups'],['Ressources','resources'],['Contacts','contacts']]);
      s+=section('Flux de courrier','mailflow','mail',[['Suivi des messages','trace'],['Règles','rules'],['Domaines distants','remote'],['Domaines acceptés','domains'],['Connecteurs','connectors'],['E-mails à volume élevé','volume'],['Alertes','alerts'],['Stratégies d’alerte','alertpolicies']]);
