    const ownerOptions=db.users.filter(u=>u.userType==='Member').map(u=>[u.id,u.displayName]), sponsorOptions=[...ownerOptions,...db.groups.filter(g=>g.type==='Microsoft 365'||g.membership==='Dynamic').map(g=>['group:'+g.id,g.name])];
    const multi=(label,name,options,selected)=>`<div class="agent-picker-summary"><h3>${label}</h3><p>${selected.map(id=>esc(options.find(x=>x[0]===id)?.[1]||id)).join(', ')||'None selected'}</p>${selected.map(id=>`<input type="hidden" name="${name}" value="${attr(id)}">`).join('')}${actionBtn(name==='owners'?'Edit owner':'Edit sponsor','agent-principal-open',name)}</div>${d.principalPicker?.kind===name?`<section class="agent-principal-picker" role="dialog" aria-label="${name==='owners'?'Select owner':'Select sponsor'}"><header><h2>${name==='owners'?'Select owner':'Select sponsor'}</h2>${actionBtn('×','agent-principal-cancel','','drawer-close')}</header><p>${name==='owners'?'Select a user to be the owner of this agent identity':'Select a user, dynamic membership group, or M365 group to be a sponsor of this agent identity'}</p><label>Recherche<input class="form-control" type="search" data-agent-principal-search value="${attr(d.principalPicker.query)}"></label><div class="agent-principal-list">${options.filter(([id,title])=>normal(id+' '+title).includes(normal(d.principalPicker.query))).map(([id,title])=>`<label class="choose-item"><input type="checkbox" data-agent-principal-check="${attr(id)}" ${d.principalPicker.selected.includes(id)?'checked':''}> ${esc(title)} <span class="muted">${id.startsWith('group:')?'Groupe':'Utilisateur'}</span></label>`).join('')||'<p>Aucun résultat.</p>'}</div><p>(${d.principalPicker.selected.length}) sélectionné(s)</p>${actionBtn('Réinitialiser','agent-principal-reset')} ${actionBtn('Sélectionner','agent-principal-apply','','btn primary')} ${actionBtn('Annuler','agent-principal-cancel')}</section>`:''}`;
