  function renderTenantGovernance(){
    const view=ui.tenantGovernanceView||'overview',items=[['Vue d’ensemble','overview'],['Locataires associés','related'],['Locataires régis','governed'],['Locataires qui régissent','governing'],['Modèles','templates'],['Captures instantanées','snapshots'],['Moniteurs','monitors'],['Autorisations de gestion de la configuration','permissions'],['Paramètres de gouvernance de locataire','settings']],title=items.find(x=>x[1]===view)?.[0]||'Vue d’ensemble';
    const license=`<div class="account-recovery-empty"><h2>Licence obligatoire manquante</h2><div class="account-recovery-icon" aria-hidden="true">${icon('lock')}</div><p>${view==='related'?'Cette fonctionnalité nécessite un abonnement Gouvernance Microsoft Entra ID.':'L’utilisation de cette fonctionnalité nécessite une licence Microsoft Entra ID P1/P2.'} Pour continuer, mettez à niveau votre licence ou contactez l’administrateur.</p></div>`,notice='<div class="entra-info">Cette fonctionnalité nécessite une licence Entra ID P1/P2 pour activer toutes les fonctionnalités. Pour continuer, mettez à niveau votre licence ou contactez l’administrateur.</div>';
    let body='';
    if(view==='overview')body=`<h2>Vue d’ensemble</h2><p>Découvrez, obtenez un contrôle administratif et monitorez la dérive de configuration dans tous les locataires de votre organisation.</p><h3>Notifications</h3><p>Vos notifications de gouvernance apparaîtront ici après la configuration.</p><h3>La gouvernance des locataires est-elle adaptée à mes besoins ?</h3><div class="card-grid"><div class="card"><strong>Découvrir</strong><p>Affichez les locataires associés avec lesquels votre organisation interagit.</p>${actionBtn('Configurer les locataires associés','tenant-governance-view','related')}</div><div class="card"><strong>Gouverner</strong><p>Établissez des relations de gouvernance pour gérer plusieurs locataires.</p>${actionBtn('Configurer une relation de gouvernance','tenant-governance-view','governed')}</div><div class="card"><strong>Surveiller</strong><p>Surveillez la configuration du locataire par rapport à sa base de référence.</p>${actionBtn('Configurer la surveillance','tenant-governance-view','monitors')}</div></div><h3>Commencer</h3><p>Activer les locataires associés ; l’activation peut prendre jusqu’à 48 heures.</p>${actionBtn('Accéder aux locataires associés','tenant-governance-view','related')}`;
    if(view==='related'||view==='snapshots')body=license;
    if(view==='monitors'){const tab=ui.tenantGovernanceTab||'Moniteurs';body=`<p>Un moniteur compare périodiquement l’état réel des ressources de locataire à l’état souhaité et enregistre les variations détectées en tant que dérive de configuration.</p><nav class="sub-tabs">${['Moniteurs','Résultats du moniteur','Dérives de configuration'].map(x=>`<button class="tab ${tab===x?'active':''}" data-action="tenant-governance-tab" data-arg="${attr(x)}">${esc(x)}</button>`).join('')}</nav>${license}`;}
    if(view==='governed'||view==='governing'){const governed=view==='governed',tabs=governed?['Locataires gouvernés','Demandes envoyées','Invitations reçues']:['Locataires gouvernants','Requêtes reçues','Invitations envoyées'],tab=tabs.includes(ui.tenantGovernanceTab)?ui.tenantGovernanceTab:tabs[0],relation=tab===tabs[0],empty=relation?(governed?'Aucun locataire gouverné trouvé.':'Aucun locataire gouvernant trouvé.'):tab.toLowerCase().includes('invitation')?'Aucune invitation trouvée.':'Aucune demande de gouvernance trouvée.',headers=relation?['Nom','ID de locataire','ID de relation','État de la gouvernance','Actif le']:['Nom','ID de locataire','ID de la demande','État de la demande','Envoyée le'];body=`${notice}<nav class="sub-tabs">${tabs.map(x=>`<button class="tab ${tab===x?'active':''}" data-action="tenant-governance-tab" data-arg="${attr(x)}">${esc(x)}</button>`).join('')}</nav><p>Affichez et gérez les relations de gouvernance pour ${esc(db.tenant.name)}.</p><div class="toolbar entra-command"><button class="btn" disabled>${governed?'Demande de gouvernance':'Terminer la gouvernance'}</button>${actionBtn(icon('refresh')+' Actualiser','refresh')}</div>${listSearch('Rechercher par nom ou ID de locataire')}${table(headers,[],empty,'850px')}`;}
    if(view==='templates')body=`${notice}<div class="sub-tabs"><span class="tab active">Modèles de stratégie de gouvernance</span></div><div class="toolbar entra-command"><button class="btn" disabled>＋ Nouveau modèle</button>${actionBtn(icon('refresh')+' Actualiser','refresh')}</div>${listSearch('Rechercher par nom')}${table(['Nom','Description','Rôles','Applications','Version','Créé le'],['<tr data-filter-row="default"><td>default <span class="muted">Par défaut</span></td><td>Default policy template used in automatically created governance relationships for add on tenants</td><td>—</td><td>—</td><td>1</td><td>—</td></tr>'],'Aucun modèle','900px')}`;
    if(view==='permissions'){
      const role=ui.tenantGovernanceTab==='Rôles Entra',catalog=role?governanceRoles:governancePermissions,chosen=role?(db.tenantGovernanceRoles||[]):(db.tenantGovernancePermissions||[]),rows=chosen.map(name=>`<tr><td>${esc(name)}</td><td>${esc(catalog.find(x=>x[0]===name)?.[1]||'—')}</td><td>${actionBtn('Supprimer','tenant-permission-remove',name,'small')}</td></tr>`);
      body=`<p>${role?'Attribuez le service de gestion de la configuration du locataire au rôle Lecteur Teams pour lui permettre de surveiller les ressources Teams.':'Attribuez des autorisations d’application aux services de gestion de la configuration du locataire pour leur permettre de surveiller les ressources Intune ou Entra, ou d’accéder aux API Exchange.'}</p><nav class="sub-tabs">${['Autorisations d’application','Rôles Entra'].map(x=>`<button class="tab ${(ui.tenantGovernanceTab||'Autorisations d’application')===x?'active':''}" data-action="tenant-governance-tab" data-arg="${attr(x)}">${x}</button>`).join('')}</nav><div class="toolbar entra-command">${actionBtn(icon('plus')+(role?' Ajouter un rôle Entra':' Ajouter des autorisations'),'open-modal',role?'tenant-role-add':'tenant-permission-add')}<button class="btn" disabled>Supprimer</button>${actionBtn(icon('refresh')+' Actualiser','refresh')}</div>${table(role?['Nom du rôle','Description du rôle','']:['Nom','Description de l’autorisation',''],rows,role?'Aucun rôle Entra n’a été trouvé':'Aucune autorisation retrouvée','650px')}`;
    }

    if(view==='settings')body=`<div class="sub-tabs"><span class="tab active">Relations de gouvernance</span></div><h3>Paramètres d’invitation</h3><p>Les invitations de gouvernance permettent à votre locataire d’envoyer des demandes de gouvernance à d’autres locataires.</p><form id="form-tenant-governance">${selectField('Autoriser d’autres locataires à envoyer des invitations de gouvernance à ce locataire ('+db.tenant.name+')','invitations',[['disabled','Désactivées'],['enabled','Activées']],db.tenantGovernanceInvitations||'disabled')}<button class="btn primary" type="submit">Enregistrer</button><div class="form-error" id="form-error"></div></form>`;
    body=`<div class="entra-info">Simulation locale : données fictives, service de gouvernance des locataires non connecté. Les modifications restent dans ce laboratoire.</div>${body}`;
    return `${crumb([{text:'Accueil',route:'entra/home'},{text:'Gouvernance des locataires'}])}<div class="entra-blade-heading"><h1>Gouvernance des locataires | ${esc(title)}</h1></div><div class="entra-blade-layout"><nav class="entra-blade-nav"><strong>Locataires</strong>${items.slice(0,4).map(([label,key])=>`<button class="entra-blade-link ${view===key?'active':''}" data-action="tenant-governance-view" data-arg="${key}">${label}</button>`).join('')}<strong>Gestion des locataires</strong>${items.slice(4,8).map(([label,key])=>`<button class="entra-blade-link ${view===key?'active':''}" data-action="tenant-governance-view" data-arg="${key}">${label}</button>`).join('')}<strong>Paramètres</strong><button class="entra-blade-link ${view==='settings'?'active':''}" data-action="tenant-governance-view" data-arg="settings">Paramètres de gouvernance de locataire</button><strong>Synchronisation entre clients</strong>${link('Vue d’ensemble','entra/cross-sync')}<strong>Gestion inter-locataires</strong>${link('Partenaires d’administration délégués','entra/partners')}</nav><div class="entra-blade-content">${body}</div></div>`;
  }
