  function emailActivityRows(){const items=usageEvents('exchange'),all=usageEvents('exchange',false),concealed=db.usageReportsConcealNames!==false,active=db.users.filter(u=>u.license),deleted=(db.deletedUsers||[]).filter(u=>u.license&&items.some(e=>e.userId===u.id));return [...active.map(u=>({user:u,deleted:false})),...deleted.map(u=>({user:u,deleted:true}))].sort((a,b)=>String(a.user.id).localeCompare(String(b.user.id))).map(({user,deleted})=>{const events=items.filter(x=>x.userId===user.id),unknown=events.some(x=>!emailActivityTypes.some(([key])=>key===x.action)),counts={},latest=all.filter(x=>x.userId===user.id&&['send','read'].includes(x.action)).reduce((a,x)=>Date.parse(x.date)>Date.parse(a||'1970-01-01')?x.date:a,'');for(const [key] of emailActivityTypes)counts[key]=unknown?'—':events.filter(x=>x.action===key).reduce((n,x)=>n+Math.max(0,Number(x.count??1)||0),0);return {id:user.id,username:concealed?emailActivityAlias(user.id):user.upn,name:concealed?emailActivityAlias(user.id):user.displayName,lastActivity:latest,deleted:deleted?'Oui':'Non',deletedDate:deleted?(user._deletedAt||''):'',product:db.licenseCatalog.find(x=>x.id===user.license)?.name||'',counts};});}
  const emailActivityColumns=[['username','Nom d’utilisateur'],['name','Nom complet'],['lastActivity','Date de dernière activité'],...emailActivityTypes,['deleted','Supprimé'],['deletedDate','Date de suppression'],['product','Produit attribué']];
