  function renderEmailActivityChart(items,chart,label){const hidden=ui.emailActivityHidden?.[chart]||[],visible=items.filter(x=>!hidden.includes(x.action)).map(x=>({date:x.date,code:emailActivityTypes.find(([key])=>key===x.action)[1],count:x.count}));return renderNdrChart(visible,label,false,code=>['#0078d4','#00a6a6','#8764b8','#d83b01','#6b8e23'][emailActivityTypes.findIndex(([,name])=>name===code)])+`<div class="ndr-chart-legend email-chart-legend" aria-label="Séries de ${attr(label)}">${emailActivityTypes.map(([key,name],i)=>`<button type="button" class="email-series ${hidden.includes(key)?'muted':''}" data-action="email-chart-series" data-arg="${chart}|${key}" aria-pressed="${!hidden.includes(key)}"><i style="background:${['#0078d4','#00a6a6','#8764b8','#d83b01','#6b8e23'][i]}"></i>${esc(name)}</button>`).join('')}</div>`;}
  function renderEmailActivityDetail(events){const rows=emailActivityRows(),typed=events.filter(x=>emailActivityTypes.some(([key])=>key===x.action)),activity=typed.map(x=>({date:x.date,action:x.action,count:Math.max(0,Number(x.count??1)||0)})),users=new Map();for(const e of typed){if(!(Number(e.count??1)>0))continue;const day=String(e.date).slice(0,10),key=day+'|'+e.action;if(!users.has(key))users.set(key,new Set());users.get(key).add(e.userId);}const userChart=[...users].map(([key,ids])=>{const [date,action]=key.split('|');return {date,action,count:ids.size};});const columns=emailSelectedColumns();return `<div class="toolbar">${actionBtn('Retour aux rapports','m365-usage-view','reports')}${actionBtn(icon('download')+' Exporter','m365-usage-export')}${actionBtn('Choisir les colonnes','open-modal','email-activity-columns')}<span class="spacer"></span>${listSearch('Rechercher')}</div><h2>Activité de messagerie Exchange</h2><div class="entra-info">Les données de ce rapport proviennent uniquement du laboratoire local.</div><p>Pour gérer la confidentialité des noms dans les rapports, accédez aux ${link('paramètres de l’organisation','m365/org-settings')}.</p>${events.some(x=>!emailActivityTypes.some(([key])=>key===x.action))?'<p>Certains événements ne précisent pas leur type ; les totaux détaillés correspondants sont indisponibles.</p>':''}<h3>Activité</h3>${renderEmailActivityChart(activity,'activity','Activité de messagerie par jour')}<h3>Utilisateurs</h3>${renderEmailActivityChart(userChart,'users','Utilisateurs actifs par jour et type d’activité')}<h3>Détails des utilisateurs</h3>${table(columns.map(([,label])=>label),rows.map(x=>{const cells=columns.map(([key])=>key in x?(x[key]||'—'):x.counts[key]);return `<tr data-filter-row="${attr(normal(cells.join(' ')))}">${cells.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`;}),'Aucune donnée disponible pour cette période.','1100px')}`;}
  const mailboxUsageColumns=[['type','Type de destinataire'],['username','Nom d’utilisateur'],['name','Nom complet'],['deleted','Supprimé'],['deletedDate','Date de suppression'],['created','Date de création'],['lastActivity','Date de dernière activité'],['itemCount','Nombre d’éléments'],['storageBytes','Stockage utilisé (octets)'],['warningBytes','Quota d’avertissement (octets)'],['sendBytes','Quota d’interdiction d’envoi (octets)'],['sendReceiveBytes','Quota d’interdiction d’envoi et de réception (octets)'],['deletedItemCount','Éléments récupérables'],['deletedItemBytes','Taille des éléments récupérables (octets)'],['recoverableBytes','Quota des éléments récupérables (octets)'],['archive','Archive']];
  function mailboxSnapshots(period=true){const now=Date.now(),start=now-Number(ui.m365UsagePeriod||'30')*86400000;return (Array.isArray(db.m365MailboxUsageSnapshots)?db.m365MailboxUsageSnapshots:[]).filter(x=>{const date=Date.parse(x.date);return (x.userId||x.mailboxId)&&Number.isFinite(date)&&date<=now&&(!period||date>=start);});}
