  function mailboxSelectedColumns(){const selected=Array.isArray(db.mailboxUsageColumns)?db.mailboxUsageColumns:mailboxUsageColumns.map(([key])=>key),columns=mailboxUsageColumns.filter(([key])=>selected.includes(key));return columns.length?columns:mailboxUsageColumns;}
  function mailboxUsageCharts(){const kind=ui.mailboxUsageKind||'user',daily=new Map();for(const x of mailboxSnapshots()){if(kind==='user'?!x.userId:!x.mailboxId)continue;const exists=x.userId?[...db.users,...(db.deletedUsers||[])].some(u=>u.id===x.userId):(db.exchange.mailboxes||[]).some(m=>m.id===x.mailboxId);if(!exists)continue;const day=String(x.date).slice(0,10),id=x.userId||x.mailboxId,key=day+'|'+id,old=daily.get(key);if(!old||Date.parse(x.date)>Date.parse(old.date))daily.set(key,x);}const days=new Map();for(const [key,x] of daily){const day=key.slice(0,10);if(!days.has(day))days.set(day,[]);days.get(day).push(x);}const counts=[],storage=[];for(const [date,entries] of days){counts.push({date,code:'Boîtes relevées',count:entries.length});const values=entries.filter(x=>Number.isFinite(x.storageBytes)&&x.storageBytes>=0);if(values.length)storage.push({date,code:'Stockage relevé (Mo)',count:values.reduce((n,x)=>n+x.storageBytes,0)/1048576});}const categories=[['good','Correct'],['warning','Avertissement'],['send','Envoi impossible'],['both','Envoi et réception impossibles'],['unknown','Indéterminé']],totals=Object.fromEntries(categories.map(([k])=>[k,0]));for(const x of mailboxUsageRows().filter(x=>x.type===(kind==='user'?'Utilisateur':'Partagée'))){const values=[x.storageBytes,x.warningBytes,x.sendBytes,x.sendReceiveBytes];let status='unknown';if(values.every(v=>v!==''&&Number.isFinite(v))&&x.warningBytes<=x.sendBytes&&x.sendBytes<=x.sendReceiveBytes)status=x.storageBytes>=x.sendReceiveBytes?'both':x.storageBytes>=x.sendBytes?'send':x.storageBytes>=x.warningBytes?'warning':'good';totals[status]++;}const max=Math.max(1,...Object.values(totals));return `<div class="toolbar"><label>Type de boîte aux lettres <select data-mailbox-report-kind><option value="user" ${kind==='user'?'selected':''}>Utilisateur</option><option value="shared" ${kind==='shared'?'selected':''}>Partagée</option></select></label></div><p>Les graphiques représentent les relevés disponibles, qui peuvent ne pas couvrir toutes les boîtes.</p><h3>Boîtes aux lettres relevées</h3>${renderNdrChart(counts,'Boîtes aux lettres relevées par jour')}<h3>Stockage relevé (Mo)</h3>${renderNdrChart(storage,'Stockage relevé en Mo par jour')}<h3>État des quotas</h3><div class="mailbox-quota-chart" role="img" aria-label="Répartition des quotas des boîtes relevées">${categories.map(([key,label])=>`<div><span>${esc(label)}</span><i style="width:${(totals[key]/max*100).toFixed(1)}%"></i><strong>${totals[key]}</strong></div>`).join('')}</div>`;}
  function renderMailboxUsage(){const rows=mailboxUsageRows(),numeric=rows.filter(x=>x.storageBytes!==''),total=numeric.reduce((n,x)=>n+x.storageBytes,0),columns=mailboxSelectedColumns();return `<div class="toolbar">${actionBtn('Retour aux rapports','m365-usage-view','reports')}${actionBtn(icon('download')+' Exporter','m365-usage-export')}${actionBtn('Choisir les colonnes','open-modal','mailbox-usage-columns')}<span class="spacer"></span>${listSearch('Rechercher')}</div><h2>Utilisation des boîtes aux lettres</h2><div class="entra-info">Les valeurs proviennent uniquement des relevés locaux disponibles pour la période sélectionnée.</div><p>Pour gérer la confidentialité des noms, accédez aux ${link('paramètres de l’organisation','m365/org-settings')}.</p><p>Boîtes aux lettres dans les relevés : ${rows.length} · Stockage relevé : ${numeric.length?esc((total/1048576).toFixed(2))+' Mo':'non disponible'}</p>${mailboxUsageCharts()}<h3>Détails des boîtes aux lettres</h3>${table(columns.map(([,label])=>label),rows.map(x=>{const cells=columns.map(([key])=>x[key]=== ''?'—':x[key]);return `<tr data-filter-row="${attr(normal(cells.join(' ')))}">${cells.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`;}),'Aucun relevé disponible pour cette période.','1700px')}`;}
