  function emailAppEvents(period=true){const now=Date.now(),start=now-Number(ui.m365UsagePeriod||'30')*86400000;return (Array.isArray(db.m365EmailAppEvents)?db.m365EmailAppEvents:[]).filter(x=>x.userId&&emailAppTypes.some(([key])=>key===x.app)&&Number.isFinite(Date.parse(x.date))&&Date.parse(x.date)<=now&&(!period||Date.parse(x.date)>=start));}
