  function sharePointSiteSelectedColumns(){const chosen=Array.isArray(db.sharePointSiteColumns)?db.sharePointSiteColumns:sharePointSiteColumns.map(([key])=>key),columns=sharePointSiteColumns.filter(([key])=>chosen.includes(key));return columns.length?columns:sharePointSiteColumns;}
  function sharePointSiteCharts(){const days=new Map();for(const x of sharePointSiteSnapshots()){const key=String(x.date).slice(0,10)+'|'+x.siteId,old=days.get(key);if(!old||Date.parse(x.date)>Date.parse(old.date))days.set(key,x);}const totals=new Map();for(const [key,x] of days){const day=key.slice(0,10);if(!totals.has(day))totals.set(day,{sites:0,files:0,filesKnown:0,storage:0,storageKnown:0});const t=totals.get(day);t.sites++;if(Number.isFinite(x.files)&&x.files>=0){t.files+=x.files;t.filesKnown++;}if(Number.isFinite(x.storageBytes)&&x.storageBytes>=0){t.storage+=x.storageBytes;t.storageKnown++;}}const series=(key,label)=>[...totals].filter(([,x])=>key==='sites'||x[key+'Known']>0).map(([date,x])=>({date,code:label,count:key==='storage'?x.storage/1048576:x[key]}));return `<h3>Sites relevés</h3>${renderNdrChart(series('sites','Sites'),'Sites SharePoint relevés par jour')}<h3>Fichiers relevés</h3>${renderNdrChart(series('files','Fichiers'),'Fichiers SharePoint relevés par jour')}<h3>Stockage relevé (Mo)</h3>${renderNdrChart(series('storage','Stockage (Mo)'),'Stockage SharePoint relevé par jour')}`;}
  function renderSharePointSiteUsage(){const columns=sharePointSiteSelectedColumns(),rows=sharePointSiteRows();return `<div class="toolbar">${actionBtn('Retour aux rapports','m365-usage-view','reports')}${actionBtn(icon('download')+' Exporter','m365-usage-export')}${actionBtn('Choisir les colonnes','open-modal','sharepoint-site-columns')}<span class="spacer"></span>${listSearch('Rechercher')}</div><h2>Utilisation des sites SharePoint</h2><div class="entra-info">Les graphiques et le tableau utilisent les relevés locaux disponibles ; les données manquantes ne sont pas estimées.</div><p>Pour gérer la confidentialité, accédez aux ${link('paramètres de l’organisation','m365/org-settings')}.</p>${sharePointSiteCharts()}<h3>Détails des sites</h3>${table(columns.map(([,label])=>label),rows.map(row=>{const cells=columns.map(([key])=>row[key]===''?'—':row[key]);return `<tr data-filter-row="${attr(normal(cells.join(' ')))}">${cells.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`;}),'Aucun relevé disponible pour cette période.','1800px')}`;}
  function sharePointUsageTabs(){return `<nav class="sub-tabs"><button class="tab ${ui.sharePointUsageTab!=='sites'?'active':''}" data-action="sharepoint-usage-tab" data-arg="activity">Activité</button><button class="tab ${ui.sharePointUsageTab==='sites'?'active':''}" data-action="sharepoint-usage-tab" data-arg="sites">Utilisation des sites</button></nav>`;}
  const oneDriveUsageColumns=[['url','URL'],['owner','Propriétaire'],['upn','Nom d’utilisateur principal du propriétaire'],['deleted','Supprimé'],['lastActivity','Date de dernière activité (UTC)'],['files','Fichiers'],['activeFiles','Fichiers actifs'],['storageBytes','Stockage utilisé (octets)'],['allocatedBytes','Stockage alloué (octets)'],['siteId','ID de site']];
  function oneDriveSnapshots(period=true){const now=Date.now(),start=now-Number(ui.m365UsagePeriod||'30')*86400000;return (Array.isArray(db.m365OneDriveUsageSnapshots)?db.m365OneDriveUsageSnapshots:[]).filter(x=>x.userId&&Number.isFinite(Date.parse(x.date))&&Date.parse(x.date)<=now&&(!period||Date.parse(x.date)>=start));}
  function oneDriveRows(){const latest=new Map();for(const x of oneDriveSnapshots()){const old=latest.get(x.userId);if(!old||Date.parse(x.date)>Date.parse(old.date))latest.set(x.userId,x);}const users=[...db.users,...(db.deletedUsers||[])],concealed=db.usageReportsConcealNames!==false;return [...latest].sort(([a],[b])=>String(a).localeCompare(String(b))).map(([id,x])=>{const u=users.find(user=>user.id===id);if(!u)return null;const num=key=>Number.isFinite(x[key])&&x[key]>=0?x[key]:'',alias=emailActivityAlias(id),siteAlias=emailActivityAlias('onedrive:'+id);return {url:concealed?siteAlias:(x.url||''),owner:concealed?alias:u.displayName,upn:concealed?alias:u.upn,deleted:typeof x.deleted==='boolean'?(x.deleted?'Oui':'Non'):'',lastActivity:x.lastActivity||'',files:num('files'),activeFiles:num('activeFiles'),storageBytes:num('storageBytes'),allocatedBytes:num('allocatedBytes'),siteId:concealed?siteAlias:(x.siteId||'')};}).filter(Boolean);}
  function oneDriveSelectedColumns(){const chosen=Array.isArray(db.oneDriveUsageColumns)?db.oneDriveUsageColumns:oneDriveUsageColumns.map(([key])=>key),columns=oneDriveUsageColumns.filter(([key])=>chosen.includes(key));return columns.length?columns:oneDriveUsageColumns;}
  function oneDriveCharts(){const days=new Map(),known=new Set([...db.users,...(db.deletedUsers||[])].map(u=>u.id));for(const x of oneDriveSnapshots()){if(!known.has(x.userId))continue;const key=String(x.date).slice(0,10)+'|'+x.userId,old=days.get(key);if(!old||Date.parse(x.date)>Date.parse(old.date))days.set(key,x);}const totals=new Map();for(const [key,x] of days){const day=key.slice(0,10);if(!totals.has(day))totals.set(day,{accounts:0,files:0,filesKnown:0,storage:0,storageKnown:0});const t=totals.get(day);t.accounts++;if(Number.isFinite(x.files)&&x.files>=0){t.files+=x.files;t.filesKnown++;}if(Number.isFinite(x.storageBytes)&&x.storageBytes>=0){t.storage+=x.storageBytes;t.storageKnown++;}}const series=(key,label)=>[...totals].filter(([,x])=>key==='accounts'||x[key+'Known']>0).map(([date,x])=>({date,code:label,count:key==='storage'?x.storage/1048576:x[key]}));return `<h3>Comptes relevés</h3>${renderNdrChart(series('accounts','Comptes'),'Comptes OneDrive relevés par jour')}<h3>Fichiers relevés</h3>${renderNdrChart(series('files','Fichiers'),'Fichiers OneDrive relevés par jour')}<h3>Stockage relevé (Mo)</h3>${renderNdrChart(series('storage','Stockage (Mo)'),'Stockage OneDrive relevé par jour')}`;}
  function renderOneDriveUsage(){const columns=oneDriveSelectedColumns(),rows=oneDriveRows();return `<div class="toolbar">${actionBtn('Retour aux rapports','m365-usage-view','reports')}${actionBtn(icon('download')+' Exporter','m365-usage-export')}${actionBtn('Choisir les colonnes','open-modal','onedrive-usage-columns')}<span class="spacer"></span>${listSearch('Rechercher')}</div><h2>Utilisation de OneDrive</h2><div class="entra-info">Les graphiques et le tableau utilisent uniquement les relevés locaux disponibles. Les données manquantes ne sont pas estimées.</div><p>Pour gérer la confidentialité, accédez aux ${link('paramètres de l’organisation','m365/org-settings')}.</p>${oneDriveCharts()}<h3>Détails des comptes</h3>${table(columns.map(([,label])=>label),rows.map(row=>{const cells=columns.map(([key])=>row[key]===''?'—':row[key]);return `<tr data-filter-row="${attr(normal(cells.join(' ')))}">${cells.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`;}),'Aucun relevé disponible pour cette période.','1400px')}`;}
  function oneDriveUsageTabs(){return `<nav class="sub-tabs"><button class="tab ${ui.oneDriveUsageTab!=='usage'?'active':''}" data-action="onedrive-usage-tab" data-arg="activity">Activité</button><button class="tab ${ui.oneDriveUsageTab==='usage'?'active':''}" data-action="onedrive-usage-tab" data-arg="usage">Utilisation</button></nav>`;}
  function exchangeUsageTabs(){return `<nav class="sub-tabs"><button class="tab ${!['mailbox','apps'].includes(ui.exchangeUsageTab)?'active':''}" data-action="exchange-usage-tab" data-arg="email">Activité de messagerie</button><button class="tab ${ui.exchangeUsageTab==='mailbox'?'active':''}" data-action="exchange-usage-tab" data-arg="mailbox">Utilisation des boîtes aux lettres</button><button class="tab ${ui.exchangeUsageTab==='apps'?'active':''}" data-action="exchange-usage-tab" data-arg="apps">Utilisation des applications de messagerie</button></nav>`;}
  function renderM365Usage(){const period=ui.m365UsagePeriod||'30',view=ui.m365UsageView||'overview',service=ui.m365UsageService||'',available=usageServices.filter(([key])=>usageEvents(key,false).length||(key==='exchange'&&(mailboxSnapshots(false).length||emailAppEvents(false).length)||key==='onedrive'&&oneDriveSnapshots(false).length||key==='sharepoint'&&sharePointSiteSnapshots(false).length||key==='m365apps'&&(m365AppEvents(false).length||m365Activations().length))),label=usageServices.find(([key])=>key===service)?.[1]||'',events=usageEvents(service),rows=usageUserRows(service);let body='';if(view==='detail'&&service==='onedrive'&&ui.oneDriveUsageTab==='usage'){body=renderOneDriveUsage();}else if(view==='detail'&&service==='onedrive'&&hasOneDriveActivityTypes()){body=renderOneDriveActivity();}else if(view==='detail'&&service==='sharepoint'&&ui.sharePointUsageTab==='sites'){body=renderSharePointSiteUsage();}else if(view==='detail'&&service==='sharepoint'&&hasSharePointActivityTypes()){body=renderSharePointActivity();}else if(view==='detail'&&service==='m365apps'&&ui.m365AppUsageTab==='activations'){body=renderM365Activations();}else if(view==='detail'&&service==='m365apps'&&m365AppEvents(false).length){body=renderM365AppUsage();}else if(view==='detail'&&service==='teams'&&hasTeamsActivityTypes()){body=renderTeamsActivity();}else if(view==='detail'&&service==='exchange'&&ui.exchangeUsageTab==='apps'){body=renderEmailAppUsage();}else if(view==='detail'&&service==='exchange'&&ui.exchangeUsageTab==='mailbox'){body=renderMailboxUsage();}else if(view==='detail'&&service==='exchange'&&hasEmailActivityTypes()){body=renderEmailActivityDetail(events);}else if(view==='detail'&&label){const daily=events.map(x=>({date:x.date,code:label,count:Math.max(0,Number(x.count??1)||0)}));body=`<div class="toolbar">${actionBtn('Retour aux rapports','m365-usage-view','reports')}${actionBtn(icon('download')+' Exporter','m365-usage-export')}<span class="spacer"></span>${listSearch('Rechercher')}</div><h2>${esc(label)}</h2><div class="entra-info">Les données de ce rapport proviennent uniquement du laboratoire local.</div><p>Pour gérer la confidentialité des noms dans les rapports, accédez aux ${link('paramètres de l’organisation','m365/org-settings')}.</p><h3>Activité</h3>${renderNdrChart(daily,'Activité par jour')}<h3>Détails des utilisateurs</h3>${table(['Nom d’utilisateur','Nom complet','Date de dernière activité','Activité'],rows.map(x=>`<tr data-filter-row="${attr(normal([x.username,x.name,x.lastActivity,x.count].join(' ')))}"><td>${esc(x.username)}</td><td>${esc(x.name)}</td><td>${esc(x.lastActivity||'—')}</td><td>${x.count}</td></tr>`),'Aucune donnée disponible pour cette période.','750px')}`;}else if(!available.length)body=`<p>${view==='overview'?'Reports are not available for the services you are subscribed to.':'Aucun rapport disponible pour les services de ce laboratoire.'}</p>`;else body=`<div class="m365-usage-cards">${available.map(([key,name])=>`<article><h3>${esc(name)}</h3><p>${usageEvents(key).length?usageEvents(key).reduce((n,x)=>n+Math.max(0,Number(x.count??1)||0),0)+' activité(s)':key==='exchange'&&mailboxSnapshots().length?'Relevés de boîtes aux lettres disponibles':key==='exchange'&&emailAppEvents().length?'Utilisation des applications disponible':key==='onedrive'&&oneDriveSnapshots().length?'Relevés de comptes disponibles':key==='sharepoint'&&sharePointSiteSnapshots().length?'Relevés de sites disponibles':key==='m365apps'&&m365AppEvents().length?'Utilisation des applications disponible':key==='m365apps'&&m365Activations().length?'Activations disponibles':'Aucune donnée pour cette période.'}</p>${actionBtn('Afficher plus','m365-usage-report',key,'btn-link')}</article>`).join('')}</div>`;return `${crumb([{text:'Accueil',route:'m365/home'},{text:'Utilisation'}])}${title('Utilisation')}<div class="m365-usage-layout"><nav><button class="entra-blade-link ${view==='overview'?'active':''}" data-action="m365-usage-view" data-arg="overview">Vue d’ensemble</button><button class="entra-blade-link ${view!=='overview'?'active':''}" data-action="m365-usage-view" data-arg="reports">Rapports</button></nav><div><p>Les rapports d’utilisation Microsoft 365 montrent comment les membres de votre entreprise utilisent les services Microsoft 365. Les rapports sont disponibles pour les 7, 30, 90 et 180 derniers jours.</p><div class="toolbar m365-usage-toolbar"><span class="spacer"></span><label>Filtrer par date <select class="form-control" data-m365-usage-period aria-label="Filtrer par date">${['7','30','90','180'].map(n=>`<option value="${n}" ${period===n?'selected':''}>${n} derniers jours</option>`).join('')}</select></label></div>${view==='detail'&&service==='exchange'?exchangeUsageTabs():view==='detail'&&service==='onedrive'?oneDriveUsageTabs():view==='detail'&&service==='sharepoint'?sharePointUsageTabs():view==='detail'&&service==='m365apps'?m365AppUsageTabs():''}${body}</div></div>`;}

  function renderM365Adoption(){return `${crumb([{text:'Accueil',route:'m365/home'},{text:'Score d’adoption'}])}${title('Score d’adoption')}<p>Il n’existe aucune donnée pour le rapport.</p>`;}
  function renderM365OrgMessages(){const tab=ui.orgMessagesTab||'context',filters=ui.orgMessageFilters||{},items=(db.orgMessages||[]).filter(m=>m.channel===tab&&(!filters.status||filters.status==='draft')&&(!filters.location||m.location===filters.location)&&(!filters.objective||m.objective===filters.objective));return `${crumb([{text:'Accueil',route:'m365/home'},{text:'Messages de l’organisation'}])}${title('Messages de l’organisation')}<p>Créez et diffusez des messages à des groupes ciblés de votre organisation.</p><h2>Actions de pointe</h2><div class="org-message-actions">${actionBtn('Créer un message','org-message-new')}${actionBtn('Activité de vérification','org-message-tab',tab)}</div><h2>Gérer les messages</h2><div class="sub-tabs">${[['In-context','context'],['E-mail','email']].map(([label,key])=>`<button class="tab ${tab===key?'active':''}" data-action="org-message-tab" data-arg="${key}">${label}</button>`).join('')}</div><div class="toolbar"><span>Filtres :</span>${[['status','État',[['','Tous'],['draft','Brouillon']]],['location','Emplacement',[['','Tous'],...['E-mail','Zone de notifications','Barre des tâches','Fenêtre superposée d’apprentissage','Windows à la une'].map(x=>[x,x])]],['objective','Objectif',[['','Tous'],...['Adoption','Intégration','Durabilité','Mises à jour techniques','Formation','Autre'].map(x=>[x,x])]]].map(([key,label,opts])=>`<label>${label} <select data-org-filter="${key}" aria-label="${label}">${opts.map(([v,t])=>`<option value="${attr(v)}" ${filters[key]===v?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`).join('')}${listSearch('Entrez du texte pour rechercher des messages.')}<span class="muted">${items.length} message(s) chargé(s)</span></div>${table(['Nom du message','État','Emplacement','Objectif','Date de création','Date de début','Nombre total de messages consultés','Nombre total de clics','Actions'],items.map(m=>`<tr data-filter-row="${attr(normal(m.name+' '+m.objective))}"><td>${actionBtn(esc(m.name||'Brouillon sans nom'),'org-message-edit',m.id,'btn-link')}</td><td>Brouillon local</td><td>${esc(m.location)}</td><td>${esc(m.objective)}</td><td>${esc(m.created)}</td><td>${esc(m.start||'—')}</td><td>—</td><td>—</td><td>${actionBtn('Modifier','org-message-edit',m.id,'small')} ${actionBtn('Supprimer','org-message-delete',m.id,'small')}</td></tr>`),'Aucun message à afficher pour vos paramètres de filtre actuels.','1000px') }`;}
  function renderOrgMessageWizard(){const d=ui.orgMessageDraft,steps=['Objectif','Emplacement','Modèle','Destinataires','Planification','Terminer'];let body='';if(d.step===0)body=`<h2>Choisissez votre objectif</h2>${selectField('Objectif','objective',[['','Sélectionner'],...['Adoption','Intégration','Durabilité','Mises à jour techniques','Formation','Autre'].map(x=>[x,x])],d.objective)}`;if(d.step===1)body=`<h2>Choisissez où afficher votre message</h2>${selectField('Emplacement','location',[['','Sélectionner'],...['E-mail','Zone de notifications','Barre des tâches','Fenêtre superposée d’apprentissage','Windows à la une'].map(x=>[x,x])],d.location)}`;if(d.step===2)body=`<h2>Choisissez comment créer votre message</h2>${field('Nom du message','name',{value:d.name,required:true})}${textareaField('Contenu','content',d.content)}`;if(d.step===3)body=`<h2>Destinataires</h2>${selectField('Groupe ciblé','group',[['','Sélectionner un groupe'],...db.groups.map(x=>[x.id,x.name])],d.group)}`;if(d.step===4)body=`<h2>Planification</h2>${field('Date de début','start',{type:'date',value:d.start})}${field('Date de fin','end',{type:'date',value:d.end})}`;if(d.step===5)body=`<h2>Terminer</h2>${infoKV('Nom',d.name)}${infoKV('Objectif',d.objective)}${infoKV('Emplacement',d.location)}${infoKV('Groupe ciblé',groupOf(d.group)?.name||'—')}${infoKV('Date de début',d.start||'—')}<div class="entra-info">Le message sera enregistré comme brouillon local. Aucun message réel n’est envoyé.</div>`;return `<div class="wizard-backdrop"></div><section class="m365-wizard" role="dialog" aria-modal="true" aria-label="Créer un message"><header><h1>Créer un message</h1><button class="drawer-close" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></header><div class="wizard-layout"><nav>${steps.map((x,i)=>`<div class="wizard-step ${i===d.step?'active':''}"><span>${i+1}</span>${x}</div>`).join('')}</nav><div class="wizard-content"><form id="form-org-message">${body}<div id="form-error" class="form-error">${esc(ui.modalError)}</div></form></div></div><footer>${d.step?actionBtn('Retour','org-message-back'):''}<button class="btn primary" type="submit" form="form-org-message">${d.step===5?'Enregistrer le brouillon':'Suivant'}</button>${d.step>0?actionBtn('Enregistrer et fermer','org-message-save-draft'):''}${actionBtn('Annuler','close-modal')}</footer></section>`;}
  function saveOrgMessageStep(){const d=ui.orgMessageDraft,form=document.getElementById('form-org-message');if(!d||!form)return;const f=new FormData(form),keys=[['objective'],['location'],['name','content'],['group'],['start','end'],[]][d.step];for(const key of keys)d[key]=String(f.get(key)||'').trim();}
  function persistOrgMessage(d){db.orgMessages=db.orgMessages||[];const existing=db.orgMessages.find(x=>x.id===d.id),record={...d,id:d.id||id(),name:d.name||'Brouillon sans nom',channel:d.location==='E-mail'?'email':'context',created:existing?.created||new Date().toLocaleDateString('fr-FR')};delete record.step;if(existing)Object.assign(existing,record);else db.orgMessages.push(record);ui.orgMessagesTab=record.channel;ui.orgMessageDraft=null;return done('Brouillon enregistré localement.','Save simulated organization message',record.name);}
  const healthServices=['Basic Mobility and Security','Microsoft 365 Copilot Chat','Microsoft 365 suite','Microsoft Entra'];
  const messageServices=['Avis général','Microsoft 365 Copilot Chat','Microsoft Entra','Mobilité et sécurité de base','Suite Microsoft 365'];
