  function preferenceChecks(name,labels,selected){return labels.map((label,i)=>`<label class="checkbox-label"><input type="checkbox" name="${name}" value="${i}" ${selected.includes(i)?'checked':''}> ${esc(label)}</label>`).join('');}
  function renderPreferenceDrawer(kind){const health=kind==='health',p=health?(db.m365HealthPreferences||{}):(db.m365MessagePreferences||{}),all=x=>x.map((_,i)=>i),tabs=health?['Affichage de page','E-mail']:['Affichage personnalisé','E-mail'];let page,email;
    if(health){page=`<p>Afficher l’état d’intégrité de ces services uniquement *</p>${preferenceChecks('pageServices',healthServices,p.pageServices||all(healthServices))}`;email=`<label class="checkbox-label"><input type="checkbox" name="enabled" data-health-email ${p.enabled?'checked':''}> M’envoyer des notifications par e-mail sur l’état du service</label><div data-health-email-options ${p.enabled?'':'hidden'}>${field('Entrez jusqu’à 2 adresses de courrier, séparées par un point-virgule','addresses',{value:p.addresses||''})}<h3>Inclure ces types de problèmes *</h3>${preferenceChecks('types',['Incidents','Avertissements','Problèmes dans votre environnement nécessitant une action'],p.types||[0,1,2])}<h3>Inclure ces services *</h3>${preferenceChecks('emailServices',healthServices,p.emailServices||all(healthServices))}</div>`;}
    else {page=`<p>Vous pouvez personnaliser les messages qui apparaissent dans la liste en sélectionnant le service ou le tag.</p><h3>Afficher les messages pour ces services</h3>${preferenceChecks('services',messageServices,p.services||all(messageServices))}<h3>Afficher les messages avec ces étiquettes</h3>${preferenceChecks('tags',messageTags,p.tags||all(messageTags))}`;email=`<h3>Recevoir les notifications par e-mail du centre de messages</h3><label class="checkbox-label"><input type="checkbox" name="primary" ${p.primary!==false?'checked':''}> Adresse de courrier principale</label><label class="checkbox-label"><input type="checkbox" name="additional" data-message-additional ${p.additional?'checked':''}> Autres adresses de courrier</label><div data-message-addresses ${p.additional?'':'hidden'}>${field('Autres adresses de courrier','addresses',{value:p.addresses||''})}</div><h3>Choisir les courriers que vous voulez recevoir</h3><label class="checkbox-label"><input type="checkbox" name="important" ${p.important?'checked':''}> M’envoyer des courriers pour les mises à jour importantes</label><label class="checkbox-label"><input type="checkbox" name="privacy" ${p.privacy!==false?'checked':''}> M’envoyer des e-mails pour les messages liés à la confidentialité des données</label><label class="checkbox-label"><input type="checkbox" name="weekly" ${p.weekly?'checked':''}> M’envoyer une synthèse hebdomadaire sur les services que j’ai sélectionnés</label>`;}
    const formId=health?'form-m365-health-preferences':'form-m365-message-preferences',nav=`<div class="sub-tabs">${tabs.map((label,i)=>`<button type="button" class="tab ${i===0?'active':''}" id="m365-pref-tab-${i}" data-action="m365-pref-tab" data-arg="${i}">${label}</button>`).join('')}</div>`,form=`<form id="${formId}"><div id="m365-pref-panel-0">${page}</div><div id="m365-pref-panel-1" hidden>${email}</div><p class="tiny muted">Préférences locales : aucune notification réelle n’est envoyée.</p><div class="form-error" id="form-error">${esc(ui.modalError)}</div></form>`;return drawer(health?'Personnaliser':'Préférences','',nav+form,formButtons(formId,'Enregistrer'),true);
  }
  function renderM365Health(){const tab=ui.m365HealthTab||'overview',prefs=db.m365HealthPreferences||{},headers=tab==='history'?['Type','Titre du problème','Service','Source','ID','État','Heure de début','Heure de fin','Dernière mise à jour']:tab==='reported'?['Service','Catégorie','Impact significatif','Signalé par','État','Nom d’utilisateur','Heure indiquée']:['Titre du problème','Type de problème','Service affecté','Mis à jour','ID'];let body='';
    if(tab==='overview')body=`<p>Affichez les problèmes et l’état d’intégrité des services disponibles avec vos abonnements actuels.</p><div class="toolbar">${actionBtn('Lire en français','refresh')}${actionBtn('Personnaliser','open-modal','m365-health-preferences')}</div><div class="entra-info">Les données d’intégrité Microsoft en temps réel ne sont pas disponibles dans ce laboratoire.</div><h2>Problèmes actifs sur lesquels Microsoft travaille</h2>${table(headers,[],'Aucune donnée d’intégrité disponible.','900px')}<h2>État du service</h2>${table(['Service','Statut'],[],'État des services non disponible.','550px')}`;
    else body=`<p>${tab==='history'?'Consultez l’historique des problèmes des services.':'Suivez l’état des problèmes signalés par les membres de votre organisation au cours des 30 derniers jours.'}</p><div class="toolbar">${actionBtn(icon('download')+' Exporter','m365-health-export',tab)}${listSearch('Entrez du texte pour rechercher des problèmes.')}</div><div class="entra-info">Le laboratoire ne reçoit pas les données Microsoft en temps réel.</div>${table(headers,[],'Aucune donnée disponible.','900px')}`;
    return `${crumb([{text:'Accueil',route:'m365/home'},{text:'État d’intégrité des services'}])}${title('Intégrité des services')}<div class="sub-tabs">${[['Vue d’ensemble','overview'],['Historique des problèmes','history'],['Problèmes signalés','reported']].map(([label,key])=>`<button class="tab ${tab===key?'active':''}" data-action="m365-health-tab" data-arg="${key}">${label}</button>`).join('')}</div>${body}`;}
  function renderM365MessageCenter(){const tab=ui.messageCenterTab||'inbox';return `${crumb([{text:'Accueil',route:'m365/home'},{text:'Centre de messagerie'}])}${title('Centre de messagerie')}<p>Suivez les modifications et annonces des services Microsoft 365.</p><div class="sub-tabs">${[['Boîte de réception','inbox'],['Archivage','archive']].map(([label,key])=>`<button class="tab ${tab===key?'active':''}" data-action="m365-message-tab" data-arg="${key}">${label}</button>`).join('')}</div><div class="toolbar">${actionBtn('Préférences','open-modal','m365-message-preferences')}${listSearch('Rechercher')}</div><div class="entra-info">Les annonces Microsoft ne sont pas synchronisées avec ce laboratoire.</div>${table(['Titre','Favoris','Service','Dernière mise à jour','Date d’action','Importance','Catégorie'],[],'Aucun message disponible.','850px') }`;}
  const m365SupportTopics=[['Utilisateurs et mots de passe','Gérer les utilisateurs et réinitialiser un mot de passe','m365/users'],['Licences et abonnements','Consulter les licences attribuées','m365/licenses'],['Domaines','Consulter les noms de domaine','m365/domains'],['État des services','Consulter les incidents et l’intégrité des services','m365/health'],['Exchange et boîtes aux lettres','Gérer les boîtes aux lettres Exchange','exchange/mailboxes'],['Méthodes d’authentification','Gérer les méthodes d’authentification Entra','entra/auth']];
  function renderM365Support(){const query=ui.m365SupportQuery||'',matches=query?m365SupportTopics.filter(([name,desc])=>normal(name+' '+desc).includes(normal(query))):[],drafts=Array.isArray(db.m365SupportDrafts)?db.m365SupportDrafts:[];return `${crumb([{text:'Accueil',route:'m365/home'},{text:'Aide et support'}])}${title('Aide et support')}<p>Décrivez votre problème pour rechercher de l’aide ou préparer une demande de service.</p><form id="form-m365-support-search"><label for="m365-support-query">Comment pouvons-nous vous aider ?</label><div class="toolbar"><input class="form-control" id="m365-support-query" name="query" value="${attr(query)}" placeholder="Décrivez votre problème" style="max-width:520px"><button class="btn primary" type="submit">Rechercher</button></div><div class="form-error" id="form-error"></div></form>${query?`<h3>Résultats pour « ${esc(query)} »</h3>${table(['Rubrique','Description'],matches.map(([name,desc,route])=>`<tr><td>${link(name,route)}</td><td>${esc(desc)}</td></tr>`),'Aucun résultat local.','700px')}`:''}<div class="entra-info">Le support et les demandes sont simulés dans ce laboratoire ; aucune demande n’est envoyée à Microsoft.</div><h2>Demandes de service</h2><div class="toolbar">${actionBtn(icon('plus')+' Nouvelle demande de service','open-modal','m365-support-draft:new')}${actionBtn(icon('refresh')+' Actualiser','refresh')}</div>${table(['Objet','Méthode de contact','Modifié','État'],drafts.map(d=>`<tr><td>${actionBtn(esc(d.subject),'open-modal','m365-support-draft:'+d.id,'btn-link')}</td><td>${d.method==='phone'?'Téléphone':'E-mail'}</td><td>${esc(d.updatedAt||'—')}</td><td>Brouillon local</td></tr>`),'Aucune demande de service locale.','750px')}`;}
  function m365Sites(){if(!Array.isArray(db.m365Sites))db.m365Sites=[{id:'site-all',url:'https://contoso.sharepoint.com/sites/allcompany',sharing:true},{id:'site-catalog',url:'https://contoso.sharepoint.com/sites/appcatalog',sharing:false},{id:'site-team',url:'https://contoso.sharepoint.com/sites/Contoso',sharing:true},{id:'site-home',url:'https://contoso.sharepoint.com',sharing:true}];return db.m365Sites;}
  function renderM365Sites(){const query=normal(ui.m365SitesQuery||''),key=ui.m365SitesSort||'url',dir=ui.m365SitesDir||1,sites=m365Sites().filter(x=>normal(x.url).includes(query)),selected=ui.m365SiteSelected;if(ui.m365SitesSort)sites.sort((a,b)=>String(a[key]).localeCompare(String(b[key]),'fr')*dir);return `${crumb([{text:'Accueil',route:'m365/home'},{text:'Sites'}])}${title('Sites')}<div class="toolbar m365-commands">${actionBtn(icon('plus')+' Ajouter un site','open-modal','m365-site-create')}${actionBtn(icon('refresh')+' Actualiser','refresh')}<span class="spacer"></span>${selected?actionBtn('1 selected ×','m365-site-clear','','btn-link'):''}<label class="search-input">${icon('search')}<input data-m365-site-search value="${attr(ui.m365SitesQuery||'')}" placeholder="Rechercher" aria-label="Recherchez un site, puis appuyez sur Entrée pour afficher les résultats"></label><div class="m365-sites-view">${actionBtn(icon('more'),'m365-sites-view','','icon-only')}${ui.m365SitesView?`<div class="m365-sites-view-menu">${actionBtn('Liste normale','m365-sites-density','normal')}${actionBtn('Liste compacte','m365-sites-density','compact')}</div>`:''}</div></div><div class="data-table-wrap"><table class="data-table m365-sites-table ${ui.m365SitesDensity==='compact'?'compact':''}"><thead><tr><th></th><th>${actionBtn('URL','m365-sites-sort','url','btn-link')}</th><th>${actionBtn('Partage externe','m365-sites-sort','sharing','btn-link')}</th></tr></thead><tbody>${sites.map(x=>`<tr class="${selected===x.id?'selected':''}"><td><input type="radio" name="m365-site" aria-label="Sélectionner un site" data-action="m365-site-select" data-arg="${attr(x.id)}" ${selected===x.id?'checked':''}></td><td>${esc(x.url)}</td><td>${x.sharing?'Activé':'Désactivé'}</td></tr>`).join('')}</tbody></table>${sites.length?'':'<div class="empty">Nous n’avons rien trouvé à afficher ici</div>'}</div>`;}
  function renderM365AdminCenters(){const centers=[
    ['Application Microsoft 365','apps','m365/apps','Gérez, configurez et surveillez le déploiement de Microsoft 365 Apps pour votre organisation.'],
    ['Azure','centerAzure','m365/azure','Le portail Azure est une interface web unifiée qui permet aux utilisateurs de gérer, surveiller et configurer l’ensemble de leurs services et ressources Azure au même endroit.'],
    ['Exchange','navExchange','exchange/home','Gérez les paramètres de courrier avancés, tels que la mise en quarantaine, le chiffrement et les règles de flux de courrier.'],
    ['Microsoft Entra','centerEntra','entra/home','Utilisez le centre d’administration Microsoft Entra pour gérer les identités, les autorisations et l’accès réseau.'],
    ['Microsoft Purview','centerPurview','m365/purview','Utilisez le portail Microsoft Purview pour gérer la sécurité et la gouvernance des données, ainsi que les solutions de risque et de conformité pour toutes vos données, sur plusieurs plateformes et applications cloud.'],
    ['Power Platform','apps','m365/power-platform','Gérez et prenez en charge l’automatisation, les agents virtuels et l’analyse des données avec Power Apps, Power Automate et Dynamics 365.'],
    ['Recherche et intelligence','search','m365/search-intelligence','Gérez les paramètres du service Recherche Microsoft, notamment les services et le contenu disponibles pour les membres de votre organisation. Simplifiez la recherche des outils internes, des documents et des personnes comme s’il s’agissait d’une recherche sur le web via Bing.'],
    ['Sécurité','shield','m365/security','Utilisez Microsoft 365 Defender pour une visibilité sans correspondance des menaces sur votre réseau et votre posture de sécurité. Répondez aux incidents, recherchez proactivement les menaces, suivez les actifs et déployez des politiques de sécurité.'],
    ['SharePoint','apps','sharepoint/home','Ouvrez le centre d’administration SharePoint de démonstration locale.'],
    ['Teams','groups','m365/teams-center','Configurez et gérez les options de conversation, de réunions, d’accès invité, etc. de Microsoft Teams.'],
    ['Viva Engage','centerViva','m365/viva-engage','Gérez votre réseau Yammer, définissez une politique d’utilisation, contrôlez les paramètres des réseaux externes et activez des fonctionnalités telles que la traduction.']
  ];return `<div class="m365-centers-page">${crumb([{text:'Accueil',route:'m365/home'},{text:'Tous les centres d’administration'}])}${title('Tous les centres d’administration')}<div class="m365-centers-search">${listSearch('Rechercher')}<button type="button" class="m365-centers-clear" data-action="m365-centers-clear" data-centers-clear aria-label="Effacer le texte recherché" ${ui.search?'':'hidden'}>×</button></div><div class="data-table-wrap"><table class="data-table m365-centers-table"><thead><tr><th aria-label="Icône"></th><th>Nom</th><th>Description</th></tr></thead><tbody>${centers.map(([name,ico,route,description])=>`<tr data-filter-row="${attr(normal(name))}"><td><span class="m365-center-icon ${attr(ico)}">${m365AssetIcon(ico)}</span></td><td><button type="button" class="m365-center-link" data-route="${attr(route)}">${esc(name)}</button></td><td>${esc(description)}</td></tr>`).join('')}</tbody></table></div><div class="m365-centers-empty" data-centers-empty hidden>Nous n’avons rien trouvé à afficher ici<br><span>Effacer la recherche pour afficher vos éléments</span></div><span class="sr-only" data-centers-result aria-live="polite"></span></div>`;}
  function renderM365SearchIntelligence(){return `${crumb([{text:'Accueil',route:'m365/home'}])}${title('Recherche et intelligence')}<div class="m365-search-denied"><span aria-hidden="true">⚠</span> Vous n’êtes pas autorisé à afficher Recherche Microsoft. Veuillez contacter votre administrateur général</div>`;}
  function renderM365Unavailable(view){const names={copilot:'Copilot',agents:'Agents',apps:'Applications intégrées',marketplace:'Marketplace',support:'Support',reports:'Rapports',health:'État d’intégrité','teams-center':'Centre d’administration Teams','power-platform':'Centre d’administration Power Platform','admin-centers':'Tous les centres d’administration',security:'Sécurité',purview:'Microsoft Purview',azure:'Azure','search-intelligence':'Recherche et intelligence','viva-engage':'Viva Engage'};return `${crumb([{text:'Accueil',route:'m365/home'},{text:names[view]||view}])}${title(names[view]||view)}<div class="callout">Cette page n’est pas encore reproduite dans la simulation locale.</div>`;}
  function ensureMobilePolicies(){if(!Array.isArray(db.exchange.mobilePolicies))db.exchange.mobilePolicies=[{id:'mobile-default',name:'Default',isDefault:true,requirePassword:false,encryption:false,modified:'—'}];}
  function userMobilePolicy(u){ensureMobilePolicies();const assigned=u.exchangeMailbox?.mobilePolicyId;if(assigned)return db.exchange.mobilePolicies.find(p=>p.id===assigned)||null;return db.exchange.mobilePolicies.find(p=>p.isDefault)||null;}
  function ensureMobileAccess(){if(!db.exchange.mobileAccess)db.exchange.mobileAccess={action:'allow',admins:[],message:'',rules:[]};if(!Array.isArray(db.exchange.mobileAccess.rules))db.exchange.mobileAccess.rules=[];if(!Array.isArray(db.exchange.mobileAccess.devices))db.exchange.mobileAccess.devices=[];if(!Array.isArray(db.exchange.mobileAccess.exceptions))db.exchange.mobileAccess.exceptions=[];}
  function mobileDeviceOwnerKey(d){if(d.userId)return 'id:'+d.userId;const matches=db.users.filter(u=>[u.upn,u.mail].filter(Boolean).some(v=>normal(v)===normal(d.user||'')));return matches.length===1?'id:'+matches[0].id:'mail:'+normal(d.user||'');}
  function mobileDeviceAccess(d){ensureMobileAccess();const key=mobileDeviceOwnerKey(d),deviceId=normal(d.deviceId||d.id||''),exception=db.exchange.mobileAccess.exceptions.find(x=>x.ownerKey===key&&normal(x.deviceId)===deviceId);return exception?.access||d.access;}
  function mobileDeviceDefaultAccess(d){ensureMobileAccess();const candidates=db.exchange.mobileAccess.rules.filter(r=>(r.familyKey==='all'||r.familyKey===d.family)&&(r.modelKey==='all'||r.modelKey===d.model)).sort((a,b)=>Number(b.modelKey!=='all')-Number(a.modelKey!=='all')||Number(b.familyKey!=='all')-Number(a.familyKey!=='all'));return candidates[0]?.action||db.exchange.mobileAccess.action||'quarantine';}
  function reconcileMobileDevices(){ensureMobileAccess();for(const device of db.exchange.mobileAccess.devices)device.access=mobileDeviceDefaultAccess(device);}
  function setMobileDeviceException(d,access){ensureMobileAccess();const ownerKey=mobileDeviceOwnerKey(d),deviceId=d.deviceId||d.id;if(!deviceId||ownerKey==='mail:')return;db.exchange.mobileAccess.exceptions=db.exchange.mobileAccess.exceptions.filter(x=>!(x.ownerKey===ownerKey&&normal(x.deviceId)===normal(deviceId)));db.exchange.mobileAccess.exceptions.push({ownerKey,deviceId,access});}
  function mobileDevicesForUser(u){ensureMobileAccess();return db.exchange.mobileAccess.devices.filter(d=>d.userId?d.userId===u.id:[u.upn,u.mail].filter(Boolean).some(value=>normal(value)===normal(d.user||'')));}
  function renderMobileAccess(){ensureMobileAccess();const view=ui.mobileAccessView||'quarantine',rules=db.exchange.mobileAccess.rules,labels={allow:'Autoriser l’accès',block:'Bloquer l’accès',quarantine:'Mettre en quarantaine'};const devices=db.exchange.mobileAccess.devices.filter(d=>mobileDeviceAccess(d)==='quarantine'),rows=view==='rules'?rules.map(r=>`<tr data-filter-row="${attr(normal(r.name+' '+r.family))}"><td><button class="btn-link" data-action="open-modal" data-arg="exchange-mobile-access-rule:${attr(r.id)}">${esc(r.name)}</button></td><td>${esc(r.family)}</td><td>${esc(r.model)}</td><td>${esc(labels[r.action])}</td></tr>`):devices.map(d=>`<tr data-filter-row="${attr(normal([d.user,d.deviceId,d.family,d.model].join(' ')))}"><td>${actionBtn(esc(d.user||'—'),'open-modal','exchange-mobile-device:'+d.id,'btn-link')}</td><td>${esc(d.family||'—')}</td><td>${esc(d.model||'—')}</td><td>${esc(d.connectionTime||'—')}</td></tr>`);return `<div class="exchange-page">${crumb([{text:'Accueil',route:'exchange/home'},{text:'Accès aux appareils mobiles'}])}${title(view==='rules'?'Règles d’accès aux périphériques':'Périphériques mis en quarantaine')}<p>Exchange ActiveSync met en quarantaine les appareils mobiles qui ne sont pas gérés par des règles ou des exemptions personnelles et avertit les administrateurs sélectionnés lorsque ces appareils sont mis en quarantaine. Affichez les appareils et définissez des règles ici.</p>${actionBtn('Modifier','open-modal','exchange-mobile-access-settings')}<nav class="sub-tabs"><button class="tab ${view==='quarantine'?'active':''}" data-action="exchange-mobile-access-tab" data-arg="quarantine">Périphériques mis en quarantaine</button><button class="tab ${view==='rules'?'active':''}" data-action="exchange-mobile-access-tab" data-arg="rules">Règles d’accès aux périphériques</button></nav><div class="toolbar exchange-commands">${view==='rules'?actionBtn(icon('plus')+' Ajouter','open-modal','exchange-mobile-access-new'):''}${actionBtn(icon('refresh')+' Actualiser','refresh')}<span class="spacer"></span>${listSearch(view==='rules'?'Rechercher dans les règles d’accès':'Rechercher l’identification d’un appareil')}</div>${view==='rules'?table(['Nom','Appareil','La règle s’applique à','Règle d’accès à l’appareil'],rows,'Aucune règle d’accès disponible à afficher.'):table(['Utilisateur','DeviceType','Modèle','ConnectionTime'],rows,'Aucun périphérique en quarantaine trouvé !')}<p class="tiny muted">Données locales simulées.</p></div>`;}
  function ensurePublicFolders(){if(!db.exchange.publicFolderData)db.exchange.publicFolderData={mailboxes:[],folders:[]};}
  function renderPublicFolders(){ensurePublicFolders();const d=db.exchange.publicFolderData,view=ui.publicFolderView||'folders',parent=ui.publicFolderParent||'',p=d.folders.find(f=>f.id===parent),items=d.folders.filter(f=>(f.parentId||'')===parent);const rows=view==='folders'?items.map(f=>`<tr data-filter-row="${attr(normal(f.name))}"><td><button class="btn-link" data-action="exchange-public-open" data-arg="${attr(f.id)}">${esc(f.name)}</button></td><td>${d.folders.some(x=>x.parentId===f.id)?'Oui':'Non'}</td><td>${f.mailEnabled?'Oui':'Non'}</td><td>${actionBtn('Détails','open-modal','exchange-public-folder:'+f.id,'small')}</td></tr>`):d.mailboxes.map(m=>`<tr data-filter-row="${attr(normal(m.name))}"><td><button class="btn-link" data-action="open-modal" data-arg="exchange-public-mailbox:${attr(m.id)}">${esc(m.name)}</button></td><td>${m.primary?'Hiérarchie principale':'Hiérarchie secondaire'}</td></tr>`);const add=view==='folders'?(d.mailboxes.length?actionBtn(icon('plus')+' Ajouter un dossier public','open-modal','exchange-public-folder-new'):'<button class="btn" disabled>＋ Ajouter un dossier public</button>'):actionBtn(icon('plus')+' Ajouter une boîte aux lettres de dossier public','open-modal','exchange-public-mailbox-new');return `<div class="exchange-page">${crumb([{text:'Accueil',route:'exchange/home'},{text:'Dossiers publics'}])}${title('Dossiers publics')}<p>Créez et gérez des paramètres pour les dossiers publics. Vous pouvez également ajouter, supprimer et gérer des paramètres pour les sous-dossiers.</p><nav class="sub-tabs"><button class="tab ${view==='folders'?'active':''}" data-action="exchange-public-tab" data-arg="folders">Dossiers publics</button><button class="tab ${view==='mailboxes'?'active':''}" data-action="exchange-public-tab" data-arg="mailboxes">Boîtes aux lettres de dossier public</button></nav>${view==='folders'&&p?`<p>${actionBtn('Dossier parent','exchange-public-up')} ${esc(p.name)}</p>`:''}<div class="toolbar exchange-commands">${add}${actionBtn(icon('refresh')+' Actualiser','refresh')}<span class="spacer"></span>${listSearch('Rechercher')}</div>${view==='folders'?table(['Nom du sous-dossier','A des sous-dossiers','Courrier activé','Actions'],rows,d.mailboxes.length?'Aucun dossier public.':'Créez d’abord une boîte aux lettres de dossier public.'):table(['Nom','Contient'],rows,'Aucune boîte aux lettres de dossier public dans cette organisation.')}<p class="tiny muted">Les dossiers et boîtes aux lettres sont simulés localement.</p></div>`;}
  function ensureSharing(){if(!db.exchange.sharing)db.exchange.sharing={organizations:[],individual:[{id:'sharing-default',name:'Default Sharing Policy',domains:'Anonymous:CalendarSharingFreeBusyReviewer,*:CalendarSharingFreeBusySimple',isDefault:true}]};}
  function renderSharing(){ensureSharing();const view=ui.sharingView||'organization',org=view==='organization',list=org?db.exchange.sharing.organizations:db.exchange.sharing.individual;const rows=list.map(x=>`<tr data-filter-row="${attr(normal(x.name+' '+x.domains))}"><td><button class="btn-link" data-action="open-modal" data-arg="exchange-sharing-detail:${attr(x.id)}">${esc(x.name)}</button></td><td>${esc(x.domains)}</td></tr>`);return `<div class="exchange-page">${crumb([{text:'Accueil',route:'exchange/home'},{text:'Partage'}])}${title('Partage')}<p>Il permet le partage de disponibilité et d’autres informations de calendrier entre organisations Exchange fédérées.</p><nav class="sub-tabs"><button class="tab ${org?'active':''}" data-action="exchange-sharing-tab" data-arg="organization">Partage de l’organisation</button><button class="tab ${org?'':'active'}" data-action="exchange-sharing-tab" data-arg="individual">Partage individuel</button></nav><div class="toolbar exchange-commands">${actionBtn(icon('plus')+(org?' Ajouter une relation d’organisation':' Ajouter une stratégie de partage individuelle'),'open-modal',org?'exchange-sharing-org-new':'exchange-sharing-individual-new')}${actionBtn(icon('refresh')+' Actualiser','refresh')}<span class="spacer"></span>${listSearch('Rechercher')}</div>${table(['Nom','Noms de domaine'],rows,org?'Aucun partage d’organisation dans cette organisation.':'Aucune stratégie de partage individuelle.')}</div>`;}
  const exchangeUserRoleGroups=[['Informations de contact',['MyContactInformation','MyAddressInformation','MyMobileInformation','MyPersonalInformation']],['Informations sur le profil',['MyProfileInformation','MyDisplayName','MyName']],['Groupes de distribution',['MyDistributionGroups']],['Appartenance au groupe de distribution',['MyDistributionGroupMembership']],['Autres rôles',['My Custom Apps','My Marketplace Apps','My ReadWriteMailbox Apps','MyBaseOptions','MyMailSubscriptions','MyMailboxDelegation','MyRetentionPolicies','MyTextMessaging','MyVoiceMail']]];
  const exchangeUserRoles=exchangeUserRoleGroups.flatMap(x=>x[1]);
  function ensureExchangeRoles(){if(!db.exchange.roleData){const adminNames=['Communication Compliance','Communication Compliance Administrators','Communication Compliance Investigators','Compliance Administrator','Compliance Management','Discovery Management','Global Readers','Help Desk','Hygiene Management','Information Protection','Information Protection Admins','Information Protection Analysts','Information Protection Investigators','Information Protection Readers','Insider Risk Management','Insider Risk Management Admins','Insider Risk Management Investigators','Organization Management','Places Administrator','Privacy Management','Privacy Management Administrators','Privacy Management Investigators','Recipient Management','Records Management','Security Administrator','Security Operator','Security Reader','Tenant Admins','View-Only Organization Management'];const defaults=['My Custom Apps','My Marketplace Apps','My ReadWriteMailbox Apps','MyBaseOptions','MyContactInformation','MyMailSubscriptions','MyProfileInformation','MyRetentionPolicies','MyTextMessaging','MyVoiceMail','MyDistributionGroupMembership','MyDistributionGroups'];db.exchange.roleData={admin:adminNames.map((name,i)=>({id:'builtin-'+i,name,description:'Groupe de rôles intégré Exchange',builtIn:true,roles:[],members:[]})),user:[{id:'user-role-default',name:'Default Role Assignment Policy',description:'This policy grants end users the permission to set their options in Outlook on the web and perform other self-administration tasks.',roles:defaults,isDefault:true}]};}}
  function renderExchangeRoles(kind){ensureExchangeRoles();const admin=kind==='roles',list=admin?db.exchange.roleData.admin:db.exchange.roleData.user,heading=admin?'Rôles d’administrateur':'Rôles d’utilisateur',rows=list.map(r=>`<tr data-filter-row="${attr(normal(r.name+' '+r.description))}"><td><button class="btn-link" data-action="open-modal" data-arg="exchange-role-detail:${attr(r.id)}">${esc(r.name)}</button></td><td>${esc(r.description)}</td>${admin?'':`<td>${esc(r.roles.join(', '))}</td>`}</tr>`);return `<div class="exchange-page">${crumb([{text:'Accueil',route:'exchange/home'},{text:heading}])}${title(heading)}<p>${admin?'Les groupes de rôles d’administrateur permettent aux utilisateurs d’afficher des données et d’effectuer des tâches dans le Centre d’administration Exchange.':'Les stratégies d’attribution de rôle définissent le niveau d’accès que les utilisateurs ont pour gérer leurs propres boîtes aux lettres Exchange et groupes de distribution.'}</p><div class="toolbar exchange-commands">${actionBtn(icon('plus')+(admin?' Ajouter un groupe de rôles':' Stratégie d’attribution de rôle'),'open-modal',admin?'exchange-role-admin-new':'exchange-role-user-new')}${actionBtn(icon('refresh')+' Actualiser','refresh')}<span class="spacer"></span>${listSearch(admin?'Rechercher un groupe de rôles':'Rechercher une stratégie d’attribution de rôle')}</div>${table(admin?['Groupe de rôles','Description']:['Nom','Description','Rôles'],rows,'Aucun rôle disponible.')}</div>`;}
  const exchangeManagementRoles=['Address Lists','Application Calendars.Read','Application Calendars.ReadWrite','Application Contacts.Read','Application Contacts.ReadWrite','Application EWS.AccessAsApp','Application Exchange Full Access','Application Mail Full Access','Application Mail-Advanced.ReadWrite.All','Application Mail.Read','Application Mail.ReadBasic','Application Mail.ReadWrite','Application Mail.Send','Application MailboxConfigItem.Read','Application MailboxConfigItem.ReadWrite','Application MailboxFolder.Read','Application MailboxFolder.ReadWrite','Application MailboxItem.Export','Application MailboxItem.ImportExport','Application MailboxItem.Read','Application MailboxItem.ReadWrite','Application MailboxSettings.Read','Application MailboxSettings.ReadWrite','Application MailTips.ReadBasic.All','Application SMTP.SendAsApp','ApplicationImpersonation','ArchiveApplication','Audit Logs','Communication Compliance Admin','Communication Compliance Investigation','Compliance Admin','Data Loss Prevention','Distribution Groups','E-Mail Address Policies','Federated Sharing','Information Protection Admin','Information Protection Analyst','Information Protection Investigator','Information Protection Reader','Information Rights Management','Insider Risk Management Admin','Insider Risk Management Investigation','PlacesBuildingManagement','PlacesDeskManagement','Privacy Management Admin','Privacy Management Investigation','Retention Management','Role Management','TenantPlacesManagement','Mailbox Import Export','Mailbox Search','MailboxSearchApplication','Move Mailboxes','TeamMailboxLifecycleApplication','Mail Recipient Creation','Mail Recipients','Recipient Policies','View-Only Recipients','Organization Transport Settings','Transport Hygiene','Transport Rules','User Options','UserApplication','Security Admin','Security Group Creation and Membership','Security Reader','O365SupportViewConfig','View-Only Audit Logs','View-Only Configuration','Organization Client Access','Organization Configuration','Migration','Message Tracking','Mail Enabled Public Folders','Public Folders','Legal Hold','LegalHoldApplication','Remote and Accepted Domains','Journaling','Mail Tips','MeetingGraphApplication','OfficeExtensionApplication','Org Custom Apps','Org Marketplace Apps','Reset Password','SendMailApplication','SensitivityLabelAdministrator','Tenant AllowBlockList Manager'];
  function renderExchangeAdminRoleWizard(){const d=ui.exchangeAdminRoleWizard,steps=['Informations de base','Autorisation','Administrateurs','Vérifier et finaliser'];let body='';if(d.step===0)body=`<h2>Configurer les informations de base</h2><p>Pour commencer, renseignez des informations de base sur le groupe de rôles que vous créez.</p>${field('Nom','name',{value:d.name,required:true})}${textareaField('Description','description',d.description)}${selectField('Portée d’écriture','scope',[['Default','Default']],'Default')}`;if(d.step===1)body=`<h2>Ajouter des autorisations</h2><p>Sélectionnez les rôles à ajouter au groupe de rôles ${esc(d.name)}.</p><label class="search-input">${icon('search')}<input data-admin-role-search placeholder="Rechercher des rôles" aria-label="Rechercher des rôles"></label>${exchangeManagementRoles.map(r=>`<label class="choose-item" data-admin-role-row="${attr(normal(r))}"><input type="checkbox" name="roles" value="${attr(r)}" ${d.roles.includes(r)?'checked':''}> ${esc(r)}</label>`).join('')}`;if(d.step===2)body=`<h2>Affecter des administrateurs</h2><p>Sélectionnez les utilisateurs à attribuer à ce groupe de rôles.</p>${chooseUserList([],true,d.members,'members')}`;if(d.step===3)body=`<h2>Vérifier et finaliser</h2>${infoKV('Nom',d.name)}${infoKV('Description',d.description||'—')}${infoKV('Portée d’écriture',d.scope)}${infoKV('Rôles',d.roles.join(', ')||'Aucun')}${infoKV('Administrateurs',d.members.map(nameOf).join(', ')||'Aucun')}`;return `<div class="overlay-back"></div><section class="exchange-rule-wizard" role="dialog" aria-modal="true" aria-label="Ajouter un groupe de rôles"><header><h1>Ajouter un groupe de rôles</h1><button class="drawer-close" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></header><div class="exchange-rule-body"><div class="exchange-rule-steps">${steps.map((t,i)=>`<div class="exchange-rule-step ${d.step===i?'active':''} ${i<d.step?'completed':''}"><span>${i<d.step?'✓':i+1}</span>${esc(t)}</div>`).join('')}</div><div class="exchange-rule-content"><form id="form-exchange-admin-role-wizard">${body}<div class="form-error" id="form-error">${esc(ui.modalError)}</div></form></div></div><footer>${d.step?actionBtn('Précédent','exchange-admin-role-back'):''}<button type="submit" class="btn primary" form="form-exchange-admin-role-wizard">${d.step===3?'Créer':'Suivant'}</button>${actionBtn('Annuler','close-modal')}</footer></section>`;}
  function saveExchangeAdminRoleStep(form){const d=ui.exchangeAdminRoleWizard,f=new FormData(form);if(d.step===0){d.name=String(f.get('name')||'').trim();d.description=String(f.get('description')||'').trim();d.scope=String(f.get('scope')||'Default');}else if(d.step===1)d.roles=[...new Set(f.getAll('roles').map(String))].filter(r=>exchangeManagementRoles.includes(r));else if(d.step===2)d.members=[...new Set(f.getAll('members').map(String))].filter(id=>db.users.some(u=>u.id===id));}
  function advanceExchangeAdminRole(form){const d=ui.exchangeAdminRoleWizard;if(!d)return;saveExchangeAdminRoleStep(form);ensureExchangeRoles();if(d.step===0&&(!d.name||d.scope!=='Default'||db.exchange.roleData.admin.some(r=>normal(r.name)===normal(d.name))))return errorForm('Entrez un nom de groupe de rôles unique et une portée valide.');if(d.step<3){d.step++;ui.modalError='';renderOverlay();return;}db.exchange.roleData.admin.push({id:id(),name:d.name,description:d.description,scope:d.scope,roles:d.roles,members:d.members,builtIn:false});const name=d.name;ui.exchangeAdminRoleWizard=null;return done('Groupe de rôles créé localement.','Create Exchange role group',name);}
  function renderExchangeUserRoleWizard(){const d=ui.exchangeUserRoleWizard,steps=['Informations de base','Autorisations','Évaluation'];let body='';if(d.step===0)body=`<h2>Configurer les informations de base</h2><p>Pour commencer, renseignez des informations de base sur la stratégie d’attribution de rôle que vous créez.</p>${field('Nom','name',{value:d.name,required:true})}${textareaField('Description','description',d.description)}`;if(d.step===1)body=`<h2>Ajouter des autorisations</h2><p>Sélectionner les autorisations pour les utilisateurs auxquels cette stratégie est attribuée</p>${exchangeUserRoleGroups.map(([heading,roles])=>`<h3>${esc(heading)}</h3>${roles.map(role=>`<label class="choose-item"><input type="checkbox" name="roles" value="${attr(role)}" ${d.roles.includes(role)?'checked':''}> ${esc(role)}</label>`).join('')}`).join('')}`;if(d.step===2)body=`<h2>Évaluation</h2>${infoKV('Nom',d.name)}${infoKV('Description',d.description||'—')}${infoKV('Rôles',d.roles.join(', ')||'Aucun')}`;return `<div class="overlay-back"></div><section class="exchange-rule-wizard" role="dialog" aria-modal="true" aria-label="Stratégie d’attribution de rôle"><header><h1>Stratégie d’attribution de rôle</h1><button class="drawer-close" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></header><div class="exchange-rule-body"><div class="exchange-rule-steps">${steps.map((t,i)=>`<div class="exchange-rule-step ${d.step===i?'active':''} ${i<d.step?'completed':''}"><span>${i<d.step?'✓':i+1}</span>${esc(t)}</div>`).join('')}</div><div class="exchange-rule-content"><form id="form-exchange-user-role-wizard">${body}<div class="form-error" id="form-error">${esc(ui.modalError)}</div></form></div></div><footer>${d.step?actionBtn('Précédent','exchange-user-role-back'):''}<button type="submit" class="btn primary" form="form-exchange-user-role-wizard">${d.step===2?'Créer':'Suivant'}</button>${actionBtn('Annuler','close-modal')}</footer></section>`;}
  function saveExchangeUserRoleStep(form){const d=ui.exchangeUserRoleWizard,f=new FormData(form);if(d.step===0){d.name=String(f.get('name')||'').trim();d.description=String(f.get('description')||'').trim();}else if(d.step===1)d.roles=[...new Set(f.getAll('roles').map(String))].filter(r=>exchangeUserRoles.includes(r));}
  function advanceExchangeUserRole(form){const d=ui.exchangeUserRoleWizard;if(!d)return;saveExchangeUserRoleStep(form);ensureExchangeRoles();if(d.step===0&&(!d.name||db.exchange.roleData.user.some(r=>normal(r.name)===normal(d.name))))return errorForm('Entrez un nom de stratégie unique.');if(d.step<2){d.step++;ui.modalError='';renderOverlay();return;}db.exchange.roleData.user.push({id:id(),name:d.name,description:d.description,roles:d.roles,isDefault:false});const name=d.name;ui.exchangeUserRoleWizard=null;return done('Stratégie d’attribution créée localement.','Create Exchange role assignment policy',name);}
  const owaFeatureGroups=[['Gestion de la communication',['Messagerie instantanée','Messagerie texte','Exchange ActiveSync','Contacts','Synchronisation des contacts LinkedIn','Synchronisation des contacts de l’appareil mobile','Toutes les listes d’adresses']],['Gestion des informations',['Journalisation','Notes','Règles de la boîte de réception','Récupérer les éléments supprimés']],['Sécurité',['Modifier le mot de passe']],['Expérience utilisateur',['Thèmes','Client Premium','Signature par e-mail','Météo','Emplacements','Événements locaux','Calendriers intéressants']],['Gestion du temps',['Calendrier','Tâches','Rappels et notifications']]];
  const owaFeatures=owaFeatureGroups.flatMap(g=>g[1]);
  function ensureOwaPolicies(){if(!Array.isArray(db.exchange.owaPolicies))db.exchange.owaPolicies=[{id:'owa-default',name:'OwaMailboxPolicy-Default',modified:'—',builtIn:true,features:owaFeatures.filter(x=>!['Emplacements','Événements locaux'].includes(x)),publicFiles:true,privateFiles:true}];}
  function renderOwaPolicies(){ensureOwaPolicies();return `<div class="exchange-page">${crumb([{text:'Accueil',route:'exchange/home'},{text:'Stratégies de l’application web d’Outlook'}])}${title('Stratégies de l’application web d’Outlook')}<p>Vous pouvez définir les fonctionnalités et services accessibles à l’aide d’Outlook sur le web en créant une stratégie de boîte aux lettres Outlook sur le web ou en modifiant la stratégie par défaut.</p><div class="toolbar exchange-commands">${actionBtn(icon('plus')+' Nouvelle stratégie OWA','open-modal','exchange-owa-new')}${actionBtn(icon('refresh')+' Actualiser','refresh')}<span class="spacer"></span>${listSearch('Rechercher une stratégie Outlook sur le web')}</div>${table(['Nom','Dernière modification'],db.exchange.owaPolicies.map(p=>`<tr data-filter-row="${attr(normal(p.name))}"><td><button class="btn-link" data-action="open-modal" data-arg="exchange-owa-detail:${attr(p.id)}">${esc(p.name)}</button></td><td>${esc(p.modified)}</td></tr>`),'Aucune stratégie OWA.')}</div>`;}
  function renderOwaWizard(){const d=ui.owaWizard,steps=['Informations de base','Fonctionnalités','Accès au fichier','Évaluation'];let body='';if(d.step===0)body=`<h2>Configurer les informations de base</h2><p>Pour commencer, fournissez des informations de base sur la stratégie de boîte aux lettres Outlook Web App que vous créez.</p>${field('Nom','name',{required:true,value:d.name})}`;if(d.step===1)body=`<h2>Sélectionnez les fonctionnalités</h2><p>Sélectionnez les fonctionnalités à activer pour les utilisateurs auxquels cette stratégie est attribuée.</p>${owaFeatureGroups.map(([heading,features])=>`<h3>${esc(heading)}</h3>${features.map(feature=>`<label class="choose-item"><input type="checkbox" name="features" value="${attr(feature)}" ${d.features.includes(feature)?'checked':''}> ${esc(feature)}</label>`).join('')}`).join('')}`;if(d.step===2)body=`<h2>Afficher et accéder aux pièces jointes</h2><p>Sélectionner la façon dont les utilisateurs peuvent accéder aux pièces jointes des e-mails et les afficher à partir d’ordinateurs publics et privés.</p><h3>Ordinateur public ou partagé</h3><label class="checkbox-label"><input type="checkbox" name="publicFiles" ${d.publicFiles?'checked':''}> Autoriser les utilisateurs à ouvrir les fichiers joints aux courriers lors de l’utilisation d’un ordinateur public ou partagé</label><h3>Ordinateurs privés</h3><label class="checkbox-label"><input type="checkbox" name="privateFiles" ${d.privateFiles?'checked':''}> Permettre aux utilisateurs d’ouvrir des fichiers joints à des e-mails lors de l’utilisation d’un ordinateur privé.</label>`;if(d.step===3)body=`<h2>Évaluation</h2>${infoKV('Nom',d.name)}${infoKV('Fonctionnalités activées',d.features.join(', ')||'Aucune')}${infoKV('Pièces jointes sur ordinateur public',d.publicFiles?'Autorisées':'Bloquées')}${infoKV('Pièces jointes sur ordinateur privé',d.privateFiles?'Autorisées':'Bloquées')}`;return `<div class="overlay-back"></div><section class="exchange-rule-wizard" role="dialog" aria-modal="true" aria-label="Nouvelle stratégie d’application web Outlook"><header><h1>Nouvelle stratégie d’application web Outlook</h1><button class="drawer-close" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></header><div class="exchange-rule-body"><div class="exchange-rule-steps">${steps.map((t,i)=>`<div class="exchange-rule-step ${d.step===i?'active':''} ${i<d.step?'completed':''}"><span>${i<d.step?'✓':i+1}</span>${esc(t)}</div>`).join('')}</div><div class="exchange-rule-content"><form id="form-owa-wizard">${body}<div class="form-error" id="form-error">${esc(ui.modalError)}</div></form></div></div><footer>${d.step?actionBtn('Précédent','exchange-owa-back'):''}<button class="btn primary" type="submit" form="form-owa-wizard">${d.step===3?'Créer':'Suivant'}</button>${actionBtn('Annuler','close-modal')}</footer></section>`;}
  function saveOwaStep(form){const d=ui.owaWizard,f=new FormData(form);if(d.step===0)d.name=String(f.get('name')||'').trim();else if(d.step===1)d.features=[...new Set(f.getAll('features').map(String))].filter(x=>owaFeatures.includes(x));else if(d.step===2){d.publicFiles=f.has('publicFiles');d.privateFiles=f.has('privateFiles');}}
  function advanceOwaWizard(form){const d=ui.owaWizard;if(!d)return;saveOwaStep(form);ensureOwaPolicies();if(d.step===0&&(!d.name||db.exchange.owaPolicies.some(p=>normal(p.name)===normal(d.name))))return errorForm('Entrez un nom de stratégie unique.');if(d.step<3){d.step++;ui.modalError='';renderOverlay();return;}db.exchange.owaPolicies.push({id:id(),name:d.name,features:d.features,publicFiles:d.publicFiles,privateFiles:d.privateFiles,modified:new Date().toLocaleString('fr-FR'),builtIn:false});const name=d.name;ui.owaWizard=null;return done('Stratégie OWA créée localement.','Create OWA policy',name);}
  function ensureMigration(){if(!db.exchange.migration)db.exchange.migration={batches:[],endpoints:[]};}
  function renderMigration(){ensureMigration();const m=db.exchange.migration,endpoints=ui.migrationView==='endpoints';return `<div class="exchange-page">${crumb([{text:'Accueil',route:'exchange/home'},{text:endpoints?'Points de terminaison':'Lots de migration'}])}<div class="toolbar"><span class="spacer"></span>${actionBtn(endpoints?'Lots de migration':'Points de terminaison','exchange-migration-view',endpoints?'batches':'endpoints')}</div>${title(endpoints?'Points de terminaison de migration':'Lots de migration')}<p>${endpoints?'Les points de terminaison décrivent la connexion à l’environnement distant.':'Créez des lots de migration pour déplacer plusieurs boîtes aux lettres vers Microsoft 365 ou Office 365.'}</p><div class="toolbar exchange-commands">${actionBtn(icon('plus')+(endpoints?' Ajouter un point de terminaison':' Ajouter un lot de migration'),'open-modal',endpoints?'migration-endpoint-new':'migration-batch-new')}${actionBtn(icon('refresh')+' Actualiser','refresh')}<span class="spacer"></span>${listSearch(endpoints?'Rechercher un point de terminaison':'Rechercher un lot de migration')}</div>${endpoints?table(['Nom','Type','Serveur'],m.endpoints.map(e=>`<tr data-filter-row="${attr(normal(e.name))}"><td>${esc(e.name)}</td><td>${esc(e.type)}</td><td>${esc(e.server||'—')}</td></tr>`),'Aucun point de terminaison.') : table(['Nom','État','Score de cohérence des données','Pourcentage de synchronisation','Total','Synchronisé','Finalisation','Échec'],m.batches.map(b=>`<tr data-filter-row="${attr(normal(b.name))}"><td><button class="btn-link" data-action="open-modal" data-arg="migration-batch-detail:${attr(b.id)}">${esc(b.name)}</button></td><td>${esc(b.status)}</td><td>—</td><td>0 %</td><td>${b.users.length}</td><td>0</td><td>0</td><td>0</td></tr>`),'Aucun lot de migration.','1150px')}<p class="tiny muted">Cette page simule la configuration ; aucun serveur n’est contacté et aucune boîte aux lettres n’est migrée.</p></div>`;}
  function migrationEndpointCompatible(batchType,endpoint){const allowed={imap:['IMAP'],google:['Google'],remote:['ExchangeRemote','Exchange'],cutover:['OutlookAnywhere','Exchange'],cross:['CrossTenant']};return (allowed[batchType]||[]).includes(endpoint.type);}
  function migrationEndpointTypeLabel(type){return ({ExchangeRemote:'Exchange Remote',OutlookAnywhere:'Outlook Anywhere',Google:'Espace de travail Google',CrossTenant:'Inter-clients'})[type]||type;}
  function renderMigrationEndpointList(){ensureMigration();const rows=db.exchange.migration.endpoints.map(e=>`<tr><td>${esc(e.name)}</td><td>${esc(migrationEndpointTypeLabel(e.type))}</td><td>${esc(e.account||e.email||'—')}</td></tr>`);return drawer('Points de terminaison','',`<p>Les points de terminaison de migration sont des objets de gestion qui décrivent le serveur distant et les connexions qui peuvent être associées à un ou plusieurs lots.</p><div class="toolbar">${actionBtn(icon('plus')+' Ajouter','migration-endpoint-add')}${actionBtn(icon('refresh')+' Actualiser','migration-endpoint-refresh')}</div>${table(['Nom','Type','Administrateur associé'],rows,'Aucun point de terminaison.') }`,'',true);}
  function migrationRemoteFields(kind,d={}){
    const auto=!!d.autoDiscover,cutover=kind==='cutover',email=field('Adresse de courrier','email',{type:'email',required:true,value:d.email}),server=field(cutover?'Serveur Exchange':'Serveur proxy MRS distant','server',{required:!cutover,value:d.server})+(cutover?field('Serveur proxy RPC','rpc',{value:d.rpc}):'');
    return `<label class="check-line"><input type="checkbox" role="switch" name="autoDiscover" ${auto?'checked':''}> <span data-migration-switch-label>${auto?'Utilisation d’AutoDiscover':cutover?'Utilisation d’ExchangeServer':'Utilisation de RemoteServer'}</span></label><div data-migration-email ${!cutover&&!auto?'hidden':''}>${!cutover&&!auto?email.replace('<input ','<input disabled '):email}</div><div data-migration-server ${auto?'hidden':''}>${auto?server.replaceAll('<input ','<input disabled '):server}</div>`;
  }
  function renderStandaloneEndpoint(){
    const t=ui.migrationStandaloneType||'',opts=[['','Sélectionner'],['ExchangeRemote','Exchange Remote'],['OutlookAnywhere','Outlook Anywhere'],['Google','Espace de travail Google'],['IMAP','IMAP']];let body=selectField('Sélectionnez le type de migration','type',opts,t);
    if(t){body+=field('Nom du point de terminaison de migration','name',{required:true});
      if(t==='IMAP')body+=field('Serveur IMAP','server',{required:true})+selectField('Authentification','authentication',[['Basic','Basic'],['NTLM','NTLM']],'Basic')+selectField('Chiffrement','encryption',[['None','None'],['SSL','SSL'],['TLS','TLS']],'None')+'<label class="check-line"><input type="checkbox" name="acceptUntrusted"> Accepter les certificats non approuvés</label>'+field('Port','port',{type:'number',required:true,value:'993'});
      if(t==='ExchangeRemote'||t==='OutlookAnywhere'){body+=field('Compte disposant de privilèges (DOMAINE\\nom d’administrateur)','account',{required:true})+field('Mot de passe du compte avec privilèges','password',{type:'password',required:true})+migrationRemoteFields(t==='OutlookAnywhere'?'cutover':'remote');}
      if(t==='Google')body+=field('Adresse de courrier','email',{type:'email',required:true})+'<div class="form-row"><label class="required" for="f-json">Spécifier les informations d’identification du compte de service à l’aide du fichier de clé JSON</label><input id="f-json" type="file" name="json" accept=".json,application/json" required></div>';
      body+='<label class="check-line"><input type="checkbox" name="skipVerification"> Ignorer la vérification</label>'+field('Nombre maximal de migrations simultanées','max',{type:'number',value:'20'})+field('Nombre maximal de synchronisations incrémentielles simultanées','sync',{type:'number',value:'10'});
    }return modalForm('Ajouter un point de terminaison','','form-migration-endpoint',body,'Créer');
  }
  function migrationTypeNote(type){
    if(type==='imap')return '<p>REMARQUE : Cette option migre le contenu des boîtes aux lettres utilisateur de votre système de messagerie source vers Microsoft 365 ou Office 365 si votre système de messagerie source prend en charge IMAP. Vous pouvez migrer des lots de boîtes aux lettres jusqu’à la migration de toutes les boîtes aux lettres.</p><p>Cette migration est prise en charge par Exchange et d’autres systèmes de messagerie.</p>';
    if(type==='google')return '<p>Cette option migre le contenu des boîtes aux lettres à partir d’une organisation Google Espace de travail (Gmail) vers Exchange Online.</p>';
    if(type==='cross')return '<p>REMARQUE : Cette option migre le contenu des boîtes aux lettres d’une organisation Exchange Online (client) vers une autre organisation Exchange Online (client). Vous pouvez migrer des lots de boîtes aux lettres jusqu’à ce que toutes les boîtes aux lettres souhaitées soient migrées vers l’autre client.</p>';
    if(type==='cutover')return '<p>REMARQUE : Cette option migre le contenu des boîtes aux lettres à partir d’Exchange local vers Exchange Online. Vous pouvez migrer des lots de boîtes aux lettres jusqu’à la migration de toutes les boîtes aux lettres vers le cloud.</p><p>Cette migration est prise en charge par Exchange Server 2003 et versions ultérieures.</p>';
    if(type==='remote')return '<p>REMARQUE : Cette option migre le contenu des boîtes aux lettres à partir d’Exchange local vers Exchange Online. Vous pouvez migrer des lots de boîtes aux lettres jusqu’à la migration de toutes les boîtes aux lettres vers le cloud.</p><p>Cette migration est prise en charge par Exchange Server 2010 et versions ultérieures.</p>';
    return '';
  }
  function migrationPrerequisites(type){
    if(type==='imap')return '<h2>Conditions préalables à la migration de l’IMAP</h2><p>Avant de commencer, préparez une migration IMAP.</p><p>Pour achever la migration du protocole IMAP (Internet Message Access Protocol) :</p><ul><li>Créez les utilisateurs et leurs boîtes aux lettres cibles dans Microsoft 365 ou Office 365 avant la migration.</li><li>Ajoutez si nécessaire le domaine en tant que domaine accepté avant de créer les utilisateurs.</li><li>Recherchez le nom complet de votre serveur de messagerie actuel.</li><li>Créez un fichier de migration contenant la liste des boîtes aux lettres à migrer.</li></ul><p>Ces prérequis ne sont pas vérifiés par le simulateur.</p>';
    if(type==='remote')return '<h2>Conditions préalables à la migration à distance</h2><p>Avant de commencer, préparez une migration à distance.</p><p>Pour achever la migration à distance :</p><ul><li>Prévoyez environ 10 minutes pour configurer le lot ; la durée de migration dépend du nombre de boîtes aux lettres.</li><li>Disposez des autorisations nécessaires pour effectuer cette procédure.</li><li>Configurez le déploiement hybride entre les organisations locales et Exchange Online.</li><li>Pour Exchange 2013, vérifiez que le service proxy de réplication de boîte aux lettres (MRSProxy) est activé sur les serveurs locaux d’accès au client.</li></ul><p>Ces prérequis ne sont pas vérifiés par le simulateur.</p>';
    if(type==='google')return `<h2>Conditions préalables pour la migration Google Espace de travail</h2><p>Vous devez être administrateur général Microsoft 365 pour effectuer les étapes de migration.</p><details open><summary>Vous pouvez automatiser la configuration de votre Google Espace de travail pour la migration</summary><p>Automatiser les 4 étapes préalables requises.</p><ol><li>Créer un projet Google Espace de travail</li><li>Créer un compte de service dans le projet</li><li>Créer une clé d’assistance</li><li>Activer les API Gmail, Calendrier et Contacts</li></ol></details><details><summary>Configurer manuellement votre Google Espace de travail pour la migration</summary><ul><li>Créer un projet et un compte de service.</li><li>Enregistrer la clé privée et déléguer l’accès à l’échelle du domaine.</li><li>Noter l’ID client et activer les API de courrier, calendrier et contacts.</li><li>Ajouter un sous-domaine de routage et choisir d’ignorer la mise à jour de l’enregistrement MX.</li></ul></details><p>Ces prérequis ne sont pas vérifiés par le simulateur.</p>`;
    if(type==='cross')return '<h2>Conditions préalables à la migration inter-clients</h2><p>Avant de commencer, préparez une migration inter-clients.</p><p>Vous devez effectuer ces tâches avant de poursuivre la migration inter-clients :</p><ul><li>Configurez correctement les objets utilisateur et les boîtes aux lettres dans les clients source et cible.</li><li>Configurez une relation d’organisation et des points de terminaison de migration inter-clients dans les clients source et cible.</li><li>Incluez les boîtes aux lettres du lot parmi celles qui peuvent être migrées dans le client source.</li><li>Disposez des autorisations nécessaires pour migrer les boîtes aux lettres.</li></ul><p>Ces prérequis ne sont pas vérifiés par le simulateur.</p>';
    if(type==='cutover')return '<h2>Conditions préalables à la migration à basculement</h2><p>Avant de commencer, préparez une migration à basculement.</p><p>Pour achever la migration à basculement :</p><ul><li>Vérifiez la configuration Outlook Anywhere du serveur Exchange local et utilisez un certificat émis par une autorité approuvée.</li><li>Vérifiez, si nécessaire, la connexion à l’organisation Exchange avec Outlook Anywhere.</li><li>Assurez-vous que l’administrateur de migration dispose des autorisations d’accès aux boîtes aux lettres locales.</li><li>Désactivez la messagerie unifiée, créez les groupes de sécurité et nettoyez les délégués.</li></ul><p>Ces prérequis ne sont pas vérifiés par le simulateur.</p>';
    return '<h2>Conditions préalables à la migration</h2><p>Préparez les utilisateurs, les boîtes aux lettres et les paramètres de connexion à l’environnement source.</p><p>Ces prérequis ne sont pas vérifiés par le simulateur.</p>';
  }
  function renderMigrationWizard(){const d=ui.migrationWizard,steps=['Chemin de migration',...(d.path==='out'?[]:['Type de migration','Conditions préalables']),'Point de terminaison de la migration',...(d.type==='cutover'&&d.path!=='out'?[]:['Ajouter des utilisateurs','Configuration']),'Planification'],active=d.path==='out'&&d.step>=3?d.step-2:d.type==='cutover'&&d.step===6?4:d.step;let body='';if(d.step===0)body=`<h2>Ajouter un lot de migration</h2><p>Sélectionnez une option de migration de boîte aux lettres et nommez le lot.</p>${field('Attribuer un nom unique au lot de migration','name',{required:true,value:d.name})}${selectField('Sélectionner le chemin de migration des boîtes aux lettres','path',[['in','Migration vers Exchange Online'],['out','Migration à partir d’Exchange Online']],d.path)}`;if(d.step===1)body=`<h2>Sélectionner le type de migration</h2><p>Le type de migration que vous choisissez pour ce lot dépend de votre système de messagerie existant. Choisissez le type de migration qui correspond le mieux aux besoins de votre équipe.</p>${selectField('Sélectionnez le type de migration','type',[['remote','Migration à distance'],['cutover','Migration à basculement'],['cross','Migration inter-clients'],['google','Migration Google Espace de travail (Gmail)'],['imap','Migration IMAP']],d.type)}${migrationTypeNote(d.type)}`;if(d.step===2)body=migrationPrerequisites(d.type);if(d.step===3)body=`<h2>Définir un point de terminaison de la migration</h2><p>Les points de terminaison de migration sont des paramètres de connexion pour le serveur à partir duquel ou vers lequel vous voulez migrer des utilisateurs.</p><fieldset class="migration-endpoint-choice"><legend class="sr-only">Choisir un point de terminaison de migration</legend><label><input type="radio" name="endpointMode" value="existing" ${d.endpointMode==='existing'?'checked':''}> Sélectionner le point de terminaison de migration</label>${selectField('Point de terminaison de migration','endpoint',[['','Sélectionner'],...db.exchange.migration.endpoints.filter(e=>migrationEndpointCompatible(d.type,e)).map(e=>[e.id,e.name])],d.endpoint).replace('<select ',`<select ${d.endpointMode==='existing'?'':'disabled '}data-migration-endpoint `)}<label><input type="radio" name="endpointMode" value="new" ${d.type==='cross'?'disabled':''} ${d.endpointMode==='new'?'checked':''}> Créer un point de terminaison de migration</label></fieldset>`;if(d.step===4)body=`<h2>Ajouter des utilisateurs</h2><p>Sélectionnez les utilisateurs fictifs du lot.</p>${chooseUserList([],true,d.users,'users')}`;if(d.step===5)body=`<h2>Configuration</h2>${selectField('Domaine de remise cible','domain',[['','Sélectionner'],...getVerifiedDomains()],d.domain)}`;if(d.step===6)body=`<h2>Planification</h2>${selectField('Démarrage du lot','start',[['manual','Démarrer manuellement'],['automatic','Démarrer automatiquement']],d.start)}${selectField('Finalisation du lot','complete',[['manual','Finaliser manuellement'],['automatic','Finaliser automatiquement']],d.complete)}<p>La création ne lance aucune migration réelle.</p>`;return `<div class="overlay-back"></div><section class="exchange-rule-wizard" role="dialog" aria-modal="true" aria-label="Ajouter un lot de migration"><header><h1>Ajouter un lot de migration</h1><button class="drawer-close" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></header><div class="exchange-rule-body"><div class="exchange-rule-steps">${steps.map((t,i)=>`<div class="exchange-rule-step ${active===i?'active':''} ${i<active?'completed':''}"><span>${i<active?'✓':i+1}</span>${esc(t)}</div>`).join('')}</div><div class="exchange-rule-content"><form id="form-migration-wizard">${body}<div class="form-error" id="form-error">${esc(ui.modalError)}</div></form></div></div><footer>${d.step?actionBtn('Précédent','migration-wizard-back'):''}<button class="btn primary" type="submit" form="form-migration-wizard">${d.step===6?'Créer':'Suivant'}</button>${actionBtn('Annuler','close-modal')}</footer></section>`;}
  function renderMigrationEndpointWizard(){
    const d=ui.migrationEndpointDraft,remote=['remote','cutover'].includes(d.kind),steps=['Chemin de migration',...(ui.migrationWizard.path==='out'?[]:['Type de migration','Conditions préalables']),'Point de terminaison de la migration',remote?'Informations d’identification du compte local':d.kind==='google'?'Informations':'Paramètres du compte de point de terminaison',remote?'Confirmer le point de terminaison de migration':d.kind==='google'?'Configuration':'Paramètres de connexion du point de terminaison',remote||d.kind==='google'?'État':'État de configuration du point de terminaison',...(d.kind==='cutover'?[]:['Ajouter des utilisateurs','Configuration']),'Planification'],active=(ui.migrationWizard.path==='out'?2:4)+d.step;
    let body='';
    if(d.step===0&&!remote)body=`<h2>${d.kind==='google'?'Informations générales':'Ajouter les paramètres du compte de point de terminaison'}</h2><p>Saisissez la valeur des informations générales concernant le point de terminaison de migration qui va être appliqué aux migrations associées.</p>${field('Nom du point de terminaison de migration','name',{required:true,value:d.name})}${field('Nombre maximal de migrations simultanées','max',{type:'number',value:d.max})}${field('Nombre maximal de synchronisations incrémentielles simultanées','sync',{type:'number',value:d.sync})}`;
    if(d.step===1&&!remote&&d.kind!=='google')body=`<h2>Configuration de migration de l’IMAP</h2><p>Pour migrer le courrier, nous avons besoin de connaître les paramètres de connexion de votre serveur IMAP. Ces paramètres seront utilisés pour d’autres lots de migration IMAP.</p>${field('Serveur IMAP','server',{required:true,value:d.server})}${selectField('Authentification','authentication',[['Basic','Basic'],['NTLM','NTLM']],d.authentication)}${selectField('Chiffrement','encryption',[['None','None'],['SSL','SSL'],['TLS','TLS']],d.encryption)}<label class="check-line"><input type="checkbox" name="acceptUntrusted" ${d.acceptUntrusted?'checked':''}> Accepter les certificats non approuvés</label>${field('Port','port',{type:'number',required:true,value:d.port})}<label class="check-line"><input type="checkbox" name="skipVerification" ${d.skipVerification?'checked':''}> Ignorer la vérification</label>`;
    if(d.kind==='google'&&d.step===1)body=`<h2>Configuration de la migration de Gmail</h2><p>Entrez les paramètres liés au compte de service qui fournissent l’accès à votre client Google Espace de travail.</p>${field('Adresse de courrier','email',{type:'email',required:true,value:d.email})}<div class="form-row"><label class="required" for="f-json">Spécifier les informations d’identification du compte de service à l’aide du fichier de clé JSON</label><input id="f-json" name="json" type="file" accept=".json,application/json" required></div><label class="check-line"><input type="checkbox" name="skipVerification" ${d.skipVerification?'checked':''}> Ignorer la vérification</label><p class="tiny muted">Le contenu du fichier n’est ni lu ni enregistré par le simulateur.</p>`;
    if(remote&&d.step===0)body=`<h2>Informations d’identification du compte local</h2><p>Saisissez la valeur des informations générales concernant le point de terminaison de migration qui va être appliqué aux migrations associées.</p>${field('Nom du point de terminaison de migration','name',{required:true,value:d.name})}${field('Compte disposant de privilèges (DOMAINE\\nom d’administrateur)','account',{required:true,value:d.account})}${field('Mot de passe du compte avec privilèges','password',{type:'password',required:true})}${migrationRemoteFields(d.kind,d)}<label class="check-line"><input type="checkbox" name="skipVerification" ${d.skipVerification?'checked':''}> Ignorer la vérification</label><p class="tiny muted">Le mot de passe est utilisé uniquement dans ce formulaire simulé et n’est pas enregistré.</p>`;
    if(remote&&d.step===1)body=`<h2>Confirmer le point de terminaison de migration</h2><p>Vérifiez les informations avant de poursuivre.</p><p>Nom : ${esc(d.name)}</p><p>${d.kind==='cutover'?'Adresse de courrier : '+esc(d.email):(d.autoDiscover?'Adresse de courrier : '+esc(d.email):'Serveur proxy MRS distant : '+esc(d.server))}</p><p>La connexion ne sera pas vérifiée par le simulateur.</p>`;
    if(d.step===2)body=`<h2>État de configuration du point de terminaison</h2><p>Le point de terminaison ${esc(d.name)} a été enregistré localement.</p><p>La connexion au serveur n’a pas été vérifiée.</p>`;
    return `<div class="overlay-back"></div><section class="exchange-rule-wizard" role="dialog" aria-modal="true" aria-label="Ajouter un lot de migration"><header><h1>Ajouter un lot de migration</h1><button class="drawer-close" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></header><div class="exchange-rule-body"><div class="exchange-rule-steps">${steps.map((t,i)=>`<div class="exchange-rule-step ${active===i?'active':''} ${i<active?'completed':''}"><span>${i<active?'✓':i+1}</span>${esc(t)}</div>`).join('')}</div><div class="exchange-rule-content"><form id="form-migration-endpoint-wizard">${body}<div class="form-error" id="form-error">${esc(ui.modalError)}</div></form></div></div><footer>${d.step<2?actionBtn('Précédent','migration-endpoint-back'):''}<button class="btn primary" type="submit" form="form-migration-endpoint-wizard">Suivant</button>${actionBtn('Annuler','close-modal')}</footer></section>`;
  }
  function saveMigrationEndpointStep(form){
    const d=ui.migrationEndpointDraft,f=new FormData(form),v=k=>String(f.get(k)||'').trim();
    if(d.step===0){d.name=v('name');if(['remote','cutover'].includes(d.kind)){d.account=v('account');d.server=v('server');d.email=v('email');d.rpc=v('rpc');d.autoDiscover=f.has('autoDiscover');d.skipVerification=f.has('skipVerification');}else{d.max=v('max');d.sync=v('sync');}}
    if(d.step===1&&d.kind==='google'){d.email=v('email');d.skipVerification=f.has('skipVerification');}
    if(d.step===1&&!['remote','cutover','google'].includes(d.kind)){d.server=v('server');d.authentication=v('authentication');d.encryption=v('encryption');d.port=v('port');d.acceptUntrusted=f.has('acceptUntrusted');d.skipVerification=f.has('skipVerification');}
  }
  function advanceMigrationEndpointWizard(form){
    const d=ui.migrationEndpointDraft;if(!d)return;saveMigrationEndpointStep(form);ensureMigration();
    if(d.step===0&&['remote','cutover'].includes(d.kind)){const password=String(new FormData(form).get('password')||'');if(!d.name||!d.account||!(d.kind==='cutover'||d.autoDiscover?d.email:d.server)||!password||db.exchange.migration.endpoints.some(e=>normal(e.name)===normal(d.name)))return errorForm('Renseignez le compte, le serveur et un nom unique.');d.step=1;}
    else if(d.step===0){if(!d.name||!Number.isInteger(Number(d.max))||Number(d.max)<1||!Number.isInteger(Number(d.sync))||Number(d.sync)<1||db.exchange.migration.endpoints.some(e=>normal(e.name)===normal(d.name)))return errorForm('Entrez un nom unique et des limites valides.');d.step=1;}
    else if(d.step===1&&['remote','cutover'].includes(d.kind)){const endpoint={id:id(),name:d.name,type:d.kind==='cutover'?'OutlookAnywhere':'ExchangeRemote',server:d.server,account:d.account,email:d.email,rpc:d.rpc,autoDiscover:d.autoDiscover,skipVerification:d.skipVerification};db.exchange.migration.endpoints.push(endpoint);ui.migrationWizard.endpoint=endpoint.id;eventLog('Create migration endpoint',d.name);save();d.step=2;}
    else if(d.step===1&&d.kind==='google'){const key=new FormData(form).get('json');if(!d.email||!key||typeof key==='object'&&!key.name)return errorForm('Indiquez une adresse de courrier et sélectionnez un fichier JSON.');const endpoint={id:id(),name:d.name,type:'Google',server:'',email:d.email,max:Number(d.max),sync:Number(d.sync),skipVerification:d.skipVerification};db.exchange.migration.endpoints.push(endpoint);ui.migrationWizard.endpoint=endpoint.id;eventLog('Create migration endpoint',d.name);save();d.step=2;}
    else if(d.step===1){const port=Number(d.port);if(!d.server||!['Basic','NTLM'].includes(d.authentication)||!['None','SSL','TLS'].includes(d.encryption)||!Number.isInteger(port)||port<1||port>65535)return errorForm('Renseignez des paramètres de connexion valides.');const endpoint={id:id(),name:d.name,type:'IMAP',server:d.server,max:Number(d.max),sync:Number(d.sync),authentication:d.authentication,encryption:d.encryption,port,acceptUntrusted:d.acceptUntrusted,skipVerification:d.skipVerification};db.exchange.migration.endpoints.push(endpoint);ui.migrationWizard.endpoint=endpoint.id;eventLog('Create migration endpoint',d.name);save();d.step=2;}
    else {ui.migrationEndpointReturn=false;ui.migrationEndpointDraft=null;ui.overlay='migration-batch-new';ui.migrationWizard.endpointMode='existing';ui.migrationWizard.step=ui.migrationWizard.type==='cutover'?6:4;ui.modalError='';renderOverlay();return;}
    ui.modalError='';renderOverlay();
  }
  function startMigrationEndpoint(){ui.migrationEndpointReturn=true;ui.migrationEndpointDraft=['imap','google'].includes(ui.migrationWizard.type)?{kind:ui.migrationWizard.type,step:0,name:'',max:'20',sync:'10',server:'',authentication:'Basic',encryption:'None',port:'993',acceptUntrusted:false,skipVerification:false}:['remote','cutover'].includes(ui.migrationWizard.type)?{kind:ui.migrationWizard.type,step:0,name:'',account:'',server:'',email:'',rpc:'',remoteServer:false,skipVerification:false}:null;ui.overlay='migration-endpoint-new';ui.modalError='';renderOverlay();}
  function saveMigrationStep(form){const d=ui.migrationWizard,f=new FormData(form),v=k=>String(f.get(k)||'').trim();if(d.step===0){d.name=v('name');d.path=v('path');}else if(d.step===1){d.type=v('type');if(d.type==='cross')d.endpointMode='existing';}else if(d.step===3){d.endpointMode=v('endpointMode')||d.endpointMode;d.endpoint=v('endpoint');}else if(d.step===4)d.users=[...new Set(f.getAll('users').map(String))].filter(id=>db.users.some(u=>u.id===id));else if(d.step===5)d.domain=v('domain');else if(d.step===6){d.start=v('start');d.complete=v('complete');}}
  function advanceMigrationWizard(form){const d=ui.migrationWizard;if(!d)return;saveMigrationStep(form);ensureMigration();if(d.step===0&&(!d.name||!['in','out'].includes(d.path)||db.exchange.migration.batches.some(b=>normal(b.name)===normal(d.name))))return errorForm('Entrez un nom unique et un chemin valide.');if(d.step===1&&!['remote','cutover','cross','google','imap'].includes(d.type))return errorForm('Sélectionnez un type de migration.');if(d.step===3){if(d.endpointMode==='new'&&d.type!=='cross'){startMigrationEndpoint();return;}if(d.endpointMode!=='existing'||!db.exchange.migration.endpoints.some(e=>e.id===d.endpoint&&migrationEndpointCompatible(d.type,e)))return errorForm('Sélectionnez un point de terminaison.');}if(d.step===4&&!d.users.length)return errorForm('Sélectionnez au moins un utilisateur.');if(d.step===5&&!db.tenant.domains.some(x=>x.verified&&x.name===d.domain))return errorForm('Sélectionnez un domaine vérifié.');if(d.step===6&&(!['manual','automatic'].includes(d.start)||!['manual','automatic'].includes(d.complete)))return errorForm('Sélectionnez une planification valide.');if(d.step<6){if(d.step===0&&d.path==='out'){d.type='remote';d.endpointMode='existing';d.step=3;}else d.step=d.step===3&&d.type==='cutover'?6:d.step+1;ui.modalError='';renderOverlay();return;}db.exchange.migration.batches.push({id:id(),name:d.name,path:d.path,type:d.type,endpoint:d.endpoint,users:d.users,domain:d.domain,start:d.start,complete:d.complete,status:'Créé (simulation)',createdAt:new Date().toISOString()});const name=d.name;ui.migrationWizard=null;return done('Lot créé localement.','Create migration batch',name);}
  const outlookUsageColumns=[['username','Nom d’utilisateur'],['lastActivity','Date de la dernière activité (UTC)'],['newOutlook','Utilisation d’Outlook pour Windows'],['classic','Utilisation d’Outlook pour Windows (classique)']];
  function outlookUsageEvents(){const now=Date.now(),start=now-Number(ui.outlookUsagePeriod||'7')*86400000,apps=(Array.isArray(db.m365AppUsageEvents)?db.m365AppUsageEvents:[]).filter(e=>e.app==='outlook'&&e.platform==='windows'),mail=(Array.isArray(db.m365EmailAppEvents)?db.m365EmailAppEvents:[]).filter(e=>e.app==='windowsOutlook');return [...apps,...mail].filter(e=>e.userId&&['new','classic'].includes(e.variant)&&Number.isFinite(Date.parse(e.date))&&Date.parse(e.date)>=start&&Date.parse(e.date)<=now);}
  function outlookUsageRows(){const events=outlookUsageEvents(),users=[...db.users,...(db.deletedUsers||[])],concealed=db.usageReportsConcealNames!==false;return [...new Set(events.map(e=>e.userId))].sort().map(id=>{const user=users.find(u=>u.id===id);if(!user)return null;const own=events.filter(e=>e.userId===id),lastActivity=own.reduce((a,e)=>Date.parse(e.date)>Date.parse(a||'1970-01-01')?e.date:a,'');return {username:concealed?emailActivityAlias(id):user.upn,lastActivity,newOutlook:own.some(e=>e.variant==='new')?'Oui':'Non',classic:own.some(e=>e.variant==='classic')?'Oui':'Non'};}).filter(Boolean);}
  function renderOutlookUsage(){const period=ui.outlookUsagePeriod||'7',events=outlookUsageEvents(),known=new Set([...db.users,...(db.deletedUsers||[])].map(u=>u.id)),daily=new Map();for(const e of events){if(!known.has(e.userId))continue;const key=String(e.date).slice(0,10)+'|'+e.variant;if(!daily.has(key))daily.set(key,new Set());daily.get(key).add(e.userId);}const chart=[...daily].map(([key,ids])=>{const [date,variant]=key.split('|');return {date,code:variant==='new'?'Nouvel Outlook':'Outlook classique',count:ids.size};}),rows=outlookUsageRows();return `${crumb([{text:'Accueil',route:'exchange/home'},{text:'Utilisation d’Outlook pour Windows'}])}${title('Utilisation d’Outlook pour Windows')}<p>Activité des utilisateurs sur Outlook pour Windows (nouveau) et Outlook pour Windows (classique).</p><div class="entra-info">Seuls les événements locaux indiquant explicitement la version nouvelle ou classique sont utilisés.</div><div class="toolbar"><select class="form-control" data-outlook-period aria-label="Période du rapport">${['7','30','90','180'].map(n=>`<option value="${n}" ${period===n?'selected':''}>${n} jours</option>`).join('')}</select></div>${chart.length?renderNdrChart(chart,'Utilisateurs uniques Outlook pour Windows par jour'):'<div class="outlook-report-graph" role="img" aria-label="Aucune donnée à afficher">Aucune donnée à afficher</div>'}<h2>Détails de l’utilisateur</h2><p class="muted">${rows.length} enregistrements disponibles</p><div class="toolbar">${actionBtn(icon('download')+' Exporter','export-outlook-usage')}<span>${rows.length} éléments</span>${listSearch('Rechercher')}</div>${table(outlookUsageColumns.map(([,label])=>label),rows.map(row=>{const cells=outlookUsageColumns.map(([key])=>row[key]||'—');return `<tr data-filter-row="${attr(normal(cells.join(' ')))}">${cells.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`; }),'Aucune donnée n’est disponible pour la période sélectionnée.','850px')}`;}

