  function renderNdrChart(items,label='Nombre de messages non remis par jour et par code d’erreur',showLegend=true,colorFor=null){
    const days=new Map(),colors=['#0078d4','#00a6a6','#8764b8','#d83b01','#6b8e23','#ca8b00'];for(const item of items){const day=String(item.date||'').slice(0,10),code=String(item.code||'Autre'),count=Math.max(0,Number(item.count)||0);if(!days.has(day))days.set(day,new Map());const counts=days.get(day);counts.set(code,(counts.get(code)||0)+count);}const all=[...days].sort(([a],[b])=>a.localeCompare(b)),codes=[...new Set(all.flatMap(([,map])=>[...map.keys()]))],max=Math.max(1,...all.map(([,map])=>[...map.values()].reduce((a,b)=>a+b,0)));if(!all.length)return '<p class="muted">Aucune donnée disponible pour la période sélectionnée.</p>';return `<div class="ndr-chart" role="img" aria-label="${attr(label)}">${all.map(([day,map])=>`<div class="ndr-chart-day"><div class="ndr-chart-stack">${codes.map((code,index)=>{const n=map.get(code)||0;return n?`<span title="${attr(day+' · '+code+' : '+n)}" style="height:${Math.max(1,n/max*130).toFixed(1)}px;background:${(colorFor?colorFor(code):colors[index%colors.length])}"></span>`:'';}).join('')}</div><span>${esc(day)}</span></div>`).join('')}</div>${showLegend?`<div class="ndr-chart-legend">${codes.map((code,index)=>`<span><i style="background:${(colorFor?colorFor(code):colors[index%colors.length])}"></i>${esc(code)}</span>`).join('')}</div>`:''}`;
  }
