  function topDomainInboundItems(includeSearch=true){const query=includeSearch?normal(ui.search||''):'',st=detailMailState('topDomainIn'),filter=detailMailFilters('topDomainIn').find(f=>f.id===st.filterId);return (Array.isArray(db.exchange.topDomainInbound)?db.exchange.topDomainInbound:[]).filter(x=>(!query||normal(topDomainInboundColumns.map(([k])=>x[k]??'').join(' ')).includes(query))&&(!filter||filter.clauses.every(c=>{const actual=normal(String(x[c.field]??'')),wanted=normal(c.value);return c.operator==='starts'?actual.startsWith(wanted):actual===wanted;}))).sort((a,b)=>String(a[st.sort]??'').localeCompare(String(b[st.sort]??''),'fr',{numeric:true,sensitivity:'base'})*st.dir);}
  function topDomainOutboundItems(includeSearch=true,range=null,ungroup=false){const period=Number(ui.topDomainPeriod||'7'),now=Date.now(),start=range?range.start:now-period*86400000,end=range?Math.min(range.end,now):now,events=Array.isArray(db.exchange.topDomainOutbound)?db.exchange.topDomainOutbound:[],groups=new Map(),keys=topDomainOutboundColumns.slice(1).map(([k])=>k);for(const event of events){const time=Date.parse(event.date);if(!Number.isFinite(time)||time<start||time>end||!event.domain)continue;const key=normal(event.domain);if(!groups.has(key))groups.set(key,{domain:event.domain,...Object.fromEntries(keys.map(k=>[k,0]))});const group=groups.get(key);for(const k of keys)group[k]+=Math.max(0,Number(event[k])||0);}const other={domain:'Tous les autres domaines',...Object.fromEntries(keys.map(k=>[k,0]))},items=[];let hasOther=false;for(const group of groups.values()){const total=keys.reduce((n,k)=>n+group[k],0);if(ungroup||total>20||group.highRisk>0||group.normalRelay>0||group.highRiskRelay>0)items.push(group);else{hasOther=true;for(const k of keys)other[k]+=group[k];}}if(hasOther)items.push(other);const query=includeSearch?normal(ui.search||''):'';return items.filter(x=>!query||normal(topDomainOutboundColumns.map(([k])=>x[k]??'').join(' ')).includes(query)).sort((a,b)=>a.domain.localeCompare(b.domain,'fr',{sensitivity:'base'}));}
