  function traceDefault(){return {sender:'',recipient:'',subject:'',messageId:'',status:'all',direction:'all',hours:'48'};}
  function traceAddressMatches(actual,filter){const terms=normal(filter).split(/[;,\s]+/).filter(Boolean),address=normal(actual||'');return !terms.length||terms.some(term=>{const parts=term.split('*');return parts.length===1?address===term:parts.length===2&&address.startsWith(parts[0])&&address.endsWith(parts[1])&&address.length>=parts[0].length+parts[1].length;});}
  function readTraceCriteria(form){const f=new FormData(form),v=k=>String(f.get(k)||'').trim(),c={sender:v('sender'),recipient:v('recipient'),subject:v('subject'),messageId:v('messageId'),hours:v('hours'),status:v('status'),direction:v('direction')};if(!['48','168','240','720','2160'].includes(c.hours)||!['all','Delivered','Failed','Pending','Expanded','Quarantined'].includes(c.status)||!['all','Inbound','Outbound'].includes(c.direction)||[c.sender,c.recipient].some(x=>x.split(/[;,\s]+/).some(term=>(term.match(/\*/g)||[]).length>1))){errorForm('Vérifiez les critères de recherche et les caractères génériques.');return null;}return c;}
  function traceRecordMatches(r,c,start,end){const date=Date.parse(r.date);return Number.isFinite(date)&&date>=start&&date<=end&&traceAddressMatches(r.sender,c.sender)&&traceAddressMatches(r.recipient,c.recipient)&&(!c.subject||normal(r.subject||'').includes(normal(c.subject)))&&(!c.messageId||normal(r.messageId||'')===normal(c.messageId))&&(c.status==='all'||r.status===c.status)&&(c.direction==='all'||r.direction===c.direction);}
  function traceItems(includeSearch=true){const c=ui.traceCriteria;if(!c)return [];const now=Date.now(),query=includeSearch?normal(ui.search||''):'';return (Array.isArray(db.exchange.messageTraceRecords)?db.exchange.messageTraceRecords:[]).filter(r=>traceRecordMatches(r,c,now-Number(c.hours)*3600000,now)&&(!query||normal(traceColumns.map(([k])=>r[k]??'').join(' ')).includes(query))).sort((a,b)=>{const key=ui.traceSort||'date',dir=ui.traceSortDir||-1;return String(a[key]??'').localeCompare(String(b[key]??''),'fr',{numeric:true,sensitivity:'base'})*dir;}).slice(0,20000);}
  const traceReportExtra=[['messageId','ID du message'],['direction','Direction'],['clientIp','Adresse IP du client']];
  function traceReportColumns(type){return type==='extended'?[...traceColumns,...traceReportExtra,['events','Événements du message']]:[...traceColumns,...traceReportExtra];}

