  function replyAllItems(includeSearch=true){const hours=Number(ui.replyAllPeriod||'3'),now=Date.now(),query=includeSearch?normal(ui.search||''):'';return (Array.isArray(db.exchange.replyAllStorms)?db.exchange.replyAllStorms:[]).filter(x=>{const start=Date.parse(x.startAt);return Number.isFinite(start)&&start<=now&&start>=now-hours*3600000&&Number(x.blocked)>0&&(!query||normal((x.subject||'')+' '+(x.sender||'')+' '+(x.messageId||'')).includes(query));}).sort((a,b)=>Date.parse(b.startAt)-Date.parse(a.startAt));}
