  function renderReplyAllReport(){const settings=exchangeMailflowDefaults(),period=ui.replyAllPeriod||'3',items=replyAllItems(false);return `<div class="exchange-page">${crumb([{text:'Accueil',route:'exchange/home'},{text:'Rapports de flux de messagerie',route:'exchange/reports'},{text:'Protection contre l’afflux d’e-mails suite à un « Répondre à tous »'}])}${title('Protection contre l’afflux d’e-mails suite à un « Répondre à tous »')}<p>Consultez les afflux détectés et les messages bloqués.</p><div class="entra-info">Les paramètres et les événements affichés sont ceux du laboratoire local.</div><div class="transport-report-summary"><section><h3>Paramètres actuels</h3>${infoKV('État',settings.replyAllProtection?'Activé':'Désactivé')}${infoKV('Nombre minimal de destinataires',settings.minRecipients)}${infoKV('Nombre minimal de réponses à tous',settings.minResponders)}${infoKV('Durée du blocage',settings.blockHours+' h')}${actionBtn('Modifier les paramètres','open-modal','exchange-mailflow-preference','btn-link')}</section><section><h3>Messages détectés</h3><p>${items.every(x=>x.detected!=null)?items.reduce((n,x)=>n+(Number(x.detected)||0),0):'Non disponible'} message(s)</p>${items.map(x=>`<p>${actionBtn(esc(x.subject||'Sans objet'),'replyall-detail',x.id,'btn-link')} : ${x.detected==null?'—':Math.max(0,Number(x.detected)||0)}</p>`).join('')}</section><section><h3>Messages bloqués</h3><p>${items.reduce((n,x)=>n+(Number(x.blocked)||0),0)} message(s)</p>${items.map(x=>`<p>${actionBtn(esc(x.subject||'Sans objet'),'replyall-detail',x.id,'btn-link')} : ${Number(x.blocked)||0}</p>`).join('')}</section></div><h2>Détails des afflux de réponses à tous</h2><div class="toolbar">${actionBtn(icon('download')+' Exporter','exchange-report-export','replyall')}<label>Période <select data-replyall-period>${[['3','3 dernières heures'],['24','24 dernières heures'],['168','7 derniers jours'],['720','30 derniers jours']].map(([v,l])=>`<option value="${v}" ${period===v?'selected':''}>${l}</option>`).join('')}</select></label>${listSearch('Rechercher')}</div>${table(replyAllColumns.map(([,label])=>label),items.map(x=>`<tr data-filter-row="${attr(normal((x.subject||'')+' '+(x.sender||'')+' '+(x.messageId||'')))}">${replyAllColumns.map(([key])=>`<td>${key==='subject'?actionBtn(esc(x[key]||'Sans objet'),'replyall-detail',x.id,'btn-link'):key==='messageId'&&x.messageId?actionBtn(esc(x.messageId),'replyall-trace',x.id,'btn-link'):esc(x[key]??'—')}</td>`).join('')}</tr>`),'Aucun afflux de réponses à tous détecté.','1050px')}${actionBtn('Retour aux rapports','mailflow-report-back')}</div>`;}
