  const onPremColumns=[['server','Serveur'],['connector','Connecteur entrant Exchange Online'],['build','Version détectée'],['firstDetected','Première détection'],['throttleFrom','Limitation activée le'],['blockFrom','Blocage activé le'],['throttled','Messages limités'],['blocked','Messages bloqués'],['throttleRate','Taux de limitation'],['blockRate','Taux de blocage'],['updatedBuild','Version mise à jour'],['updatedAt','Date de mise à jour'],['status','État'],['details','Détails']];
  function onPremPausePlan(days,now=new Date()){const p=db.exchange.onPremEnforcementPause||{},previous=Date.parse(p.endAt||''),cursor=Number.isFinite(previous)&&previous>now.getTime()?new Date(previous):new Date(now),allocations={...(p.allocations||{})};for(let i=0;i<days;i++){const year=String(cursor.getFullYear()),used=Number(allocations[year])||0;if(used>=90)return null;allocations[year]=used+1;cursor.setDate(cursor.getDate()+1);}return {endAt:cursor.toISOString(),allocations};}
