  function renderConnectorReport(index){const inbound=index===1,kind=inbound?'connectorIn':'connectorOut',st=detailMailState(kind),items=detailMailItems(kind,false),filters=detailMailFilters(kind),name=mailflowReports[index][0],chart=items.map(x=>({date:x.date,code:x.connector||'Internet',count:x.count})),tls=[['noTls','Aucun TLS'],['tls10','TLS 1.0'],['tls11','TLS 1.1'],['tls12','TLS 1.2'],['tls13','TLS 1.3']];return `<div class="exchange-page">${crumb([{text:'Accueil',route:'exchange/home'},{text:'Rapports de flux de messagerie',route:'exchange/reports'},{text:name}])}${title(name)}<p>Surveillez le volume des messages et le chiffrement TLS pour chaque connecteur ${inbound?'entrant':'sortant'}.</p><div class="entra-info">Ce rapport utilise uniquement les données disponibles dans le laboratoire local.</div><div class="transport-report-summary"><section><h3>Volume de messages</h3>${renderNdrChart(chart,'Volume de messages par jour et connecteur')}</section><section><h3>Messages par version TLS utilisée</h3>${items.length?tls.map(([key,label])=>`<p>${label} : ${items.reduce((sum,x)=>sum+(Number(x[key])||0),0)}</p>`).join(''):'<p>Aucune donnée disponible.</p>'}</section></div><h2>Détails du rapport sur les connecteurs</h2><p class="muted">${items.length} enregistrements chargés</p><div class="toolbar">${actionBtn(icon('download')+' Exporter','exchange-report-export','connector')}${actionBtn('Demander un rapport','open-modal','connector-report-request:'+index)}<label>Date <select data-detail-mail-period="${kind}">${[['7','7 jours'],['30','30 jours'],['90','90 jours'],['custom','Date personnalisée']].map(([v,l])=>`<option value="${v}" ${st.period===v?'selected':''}>${l}</option>`).join('')}</select></label>${st.period==='custom'?`<label>Date de début <input type="date" data-detail-mail-start="${kind}" value="${attr(st.start)}"></label>`:''}<div class="entra-new-wrap">${actionBtn('Filtrer','detail-mail-menu',kind)}${st.menu?`<div class="entra-new-menu">${actionBtn('Nouveau filtre','detail-mail-filter-new',kind)}${actionBtn('Effacer tous les filtres','detail-mail-filter-select',kind+'|')}${filters.map(f=>actionBtn((st.filterId===f.id?'✓ ':'')+esc(f.name),'detail-mail-filter-select',kind+'|'+f.id)).join('')}</div>`:''}</div>${listSearch('Rechercher')}</div>${st.filterId?`<p>Filtre actif : ${esc(filters.find(f=>f.id===st.filterId)?.name||'')} ${actionBtn('Supprimer le filtre enregistré','detail-mail-filter-delete',kind+'|'+st.filterId,'btn-link')}</p>`:''}${table(connectorReportColumns.map(([key,label])=>actionBtn(esc(label)+(st.sort===key?(st.dir===1?' ↑':' ↓'):''),'detail-mail-sort',kind+'|'+key,'btn-link')),items.map(x=>`<tr data-filter-row="${attr(normal(connectorReportColumns.map(([key])=>x[key]??'').join(' ')))}">${connectorReportColumns.map(([key])=>`<td>${esc(x[key]??'—')}</td>`).join('')}</tr>`),'Aucune donnée n’est disponible pour la requête donnée','1100px')}${(db.exchange.reportRequests||[]).some(x=>x.reportIndex===index)?`<h3>Demandes locales</h3>${table(['Nom du rapport','Période','Destinataires','État','Actions'],db.exchange.reportRequests.filter(x=>x.reportIndex===index).map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.start)} – ${esc(x.end)}</td><td>${esc(x.recipients)}</td><td>${esc(x.status)}</td><td>${Array.isArray(x.rows)?actionBtn('Télécharger','connector-report-download',x.id,'btn-link'):'Données non disponibles'} ${actionBtn('Supprimer','connector-report-delete',x.id,'btn-link')}</td></tr>`),'','800px')}`:''}${actionBtn('Retour aux rapports','mailflow-report-back')}</div>`;}
  function renderMigrationReports(){ensureMigration();const period=ui.migrationReportPeriod||'7',status=ui.migrationReportStatus||'all',batches=db.exchange.migration.batches.filter(b=>(status==='all'||b.status===status)&&(!b.createdAt||Date.parse(b.createdAt)>=Date.now()-Number(period)*86400000)),headers=['Nom','État','Pourcentage de synchronisation','Total','Synchronisé','Finalisation','Échec'];return `<div class="exchange-page">${crumb([{text:'Accueil',route:'exchange/home'},{text:'Rapport de migration'}])}${title('Rapport de migration')}<p>Ce rapport présente les lots de migration de boîtes aux lettres créés pour votre organisation.</p><h2>Rapport détaillé sur la migration</h2><div class="toolbar">${actionBtn(icon('download')+' Exporter','exchange-report-export','migration')}<label>Heure de début <select data-migration-report-period>${['7','30','90'].map(n=>`<option value="${n}" ${period===n?'selected':''}>${n} jours</option>`).join('')}</select></label><label>État <select data-migration-report-status><option value="all">All</option>${[...new Set(db.exchange.migration.batches.map(x=>x.status))].map(v=>`<option value="${attr(v)}" ${status===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>${listSearch('Rechercher')}</div>${table(headers,batches.map(b=>`<tr data-filter-row="${attr(normal(b.name))}"><td>${actionBtn(esc(b.name),'open-modal','migration-batch-detail:'+b.id,'btn-link')}</td><td>${esc(b.status)}</td><td>0 %</td><td>${(b.users||[]).length}</td><td>0</td><td>0</td><td>0</td></tr>`),'Aucune donnée n’est disponible pour la requête donnée','850px')}<p class="tiny muted">Lots locaux simulés ; les anciens lots sans date restent visibles.</p></div>`;}
  function renderExchangeVolume(){const accounts=db.exchange.hveAccounts||[],rows=accounts.map(a=>`<tr data-filter-row="${attr(normal(a.name+' '+a.email))}"><td>${actionBtn(esc(a.name),'open-modal','exchange-hve-detail:'+a.id,'btn-link')}</td><td>${esc(a.email)}</td><td>${esc(a.billing||'Non configurée')}</td><td>${a.enabled?'Activé':'Désactivé'}</td></tr>`);return `<div class="exchange-page">${crumb([{text:'Accueil',route:'exchange/home'},{text:'E-mails à volume élevé'}])}${title('E-mails à volume élevé')}<p>Le service d’e-mails à volume élevé permet d’envoyer des communications en masse à l’aide du point de terminaison SMTP. Vous pouvez ajouter jusqu’à 1 000 comptes.</p><div class="toolbar exchange-commands">${actionBtn(icon('plus')+' Ajouter un compte HVE','exchange-hve-new')}${actionBtn(icon('download')+' Exporter','exchange-hve-export')}${actionBtn(icon('refresh')+' Actualiser','refresh')}<span class="spacer"></span>${listSearch('Rechercher un compte d’e-mails à volume élevé')}</div>${table(['Nom d’affichage','Adresse e-mail','Politique de facturation','Statut du compte'],rows,'Aucune donnée disponible','850px') }</div>`;}
  function renderExchangeHveWizard(){const d=ui.hveDraft,steps=['Informations de base','Politique de facturation avec paiement à l’utilisation','Vérifier le compte HVE'];let body='';if(d.step===0)body=`<h2>Configurer les informations de base</h2><p>Pour commencer, fournissez les informations de base du compte HVE.</p>${field('Nom d’affichage','name',{value:d.name,required:true})}${field('Adresse e-mail principale','local',{value:d.local,required:true})}${selectField('Domaine','domain',db.tenant.domains.filter(x=>x.verified).map(x=>[x.name,x.name]),d.domain)}${field('Alias','alias',{value:d.alias})}${field('Mot de passe','password',{type:'password',required:true})}${field('Confirmer un mot de passe','confirmation',{type:'password',required:true})}<p class="muted">Le mot de passe sert uniquement à la validation de cet assistant et n’est pas conservé.</p>`;if(d.step===1)body=`<h2>Politique de facturation avec paiement à l’utilisation</h2><p>Choisissez une politique de facturation pour ce compte dans le laboratoire.</p>${selectField('Politique de facturation','billing',[['','Aucune politique configurée'],...(db.exchange.hveBillingPolicies||[]).map(x=>[x.name,x.name])],d.billing)}<div class="entra-info">Aucun abonnement ni paiement réel n’est configuré dans cette simulation.</div>`;if(d.step===2)body=`<h2>Vérifier le compte HVE</h2>${infoKV('Nom d’affichage',d.name)}${infoKV('Adresse e-mail principale',d.local+'@'+d.domain)}${infoKV('Alias',d.alias||d.local)}${infoKV('Politique de facturation',d.billing||'Non configurée')}<p>La création est locale et ne permet pas d’envoyer de courrier.</p>`;return `<div class="overlay-back"></div><section class="exchange-rule-wizard" role="dialog" aria-modal="true" aria-label="Nouveau compte d’e-mail à volume élevé"><header><h1>Nouveau compte d’e-mail à volume élevé</h1><button class="drawer-close" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></header><div class="exchange-rule-body"><div class="exchange-rule-steps">${steps.map((t,i)=>`<div class="exchange-rule-step ${i===d.step?'active':''} ${i<d.step?'completed':''}"><span>${i+1}</span>${esc(t)}</div>`).join('')}</div><div class="exchange-rule-content"><form id="form-exchange-hve">${body}<div id="form-error" class="form-error">${esc(ui.modalError)}</div></form></div></div><footer>${d.step?actionBtn('Précédent','exchange-hve-back'):''}<button class="btn primary" type="submit" form="form-exchange-hve">${d.step===2?'Créer':'Suivant'}</button>${actionBtn('Annuler','close-modal')}</footer></section>`;}
  const alertEvents=['Mail loop','Slow transport rule','New users forwarding','New domains being forwarded','Cert expiry'];
  function renderExchangeAlertPolicies(){const policies=db.exchange.alertPolicies||[],rows=policies.map(p=>`<tr data-filter-row="${attr(normal(p.name+' '+p.event))}"><td>${actionBtn(esc(p.name),'open-modal','exchange-alert-detail:'+p.id,'btn-link')}</td><td>${esc(p.severity)}</td><td>${p.enabled?'Activé':'Désactivé'}</td><td>${esc(p.event)}</td><td>${esc(p.modified)}</td></tr>`);return `<div class="exchange-page">${crumb([{text:'Accueil',route:'exchange/home'},{text:'Stratégies d’alerte'}])}${title('Stratégies d’alerte')}<p>Créez des stratégies d’alerte pour vous avertir lorsque certains événements liés à l’e-mail se produisent.</p><div class="toolbar exchange-commands">${actionBtn(icon('download')+' Exporter','exchange-alert-export')}${actionBtn(icon('plus')+' Nouvelle stratégie d’alerte','exchange-alert-new')}${actionBtn(icon('refresh')+' Actualiser','refresh')}<span class="spacer"></span>${listSearch('Rechercher des stratégies d’alerte')}</div>${table(['Nom de l’alerte','Gravité','État','Type','Dernière modification'],rows,'Aucune donnée n’est disponible pour la requête donnée','850px') }</div>`;}
  function renderExchangeAlerts(){const period=ui.exchangeAlertPeriod||'7';return `<div class="exchange-page">${crumb([{text:'Accueil',route:'exchange/home'},{text:'Alertes'}])}${title('Alertes')}<p>Affichez les alertes les plus récentes pour votre organisation.</p><div class="toolbar exchange-commands">${actionBtn(icon('download')+' Exporter','exchange-alert-export','alerts')}<label>Date de début <select data-exchange-alert-period aria-label="Date de début">${['7','30','90'].map(n=>`<option value="${n}" ${period===n?'selected':''}>${n} jours</option>`).join('')}</select></label><span class="spacer"></span>${listSearch('Rechercher des alertes récentes')}</div><div class="entra-info">Les alertes Exchange réelles ne sont pas disponibles dans ce laboratoire.</div>${table(['Nom de l’alerte','Gravité','État','Catégorie','Nombre d’activités','Dernière occurrence'],[],'Aucune donnée disponible','850px')}</div>`;}
  function renderExchangeAlertWizard(){const d=ui.exchangeAlertDraft,steps=['Nommez votre stratégie','Modifier les paramètres','Destinataires','Évaluer la stratégie et terminer'];let body='';if(d.step===0)body=`<h2>Nommez votre stratégie</h2><p>Renseignez des informations de base sur la stratégie que vous créez.</p>${field('Nom','name',{value:d.name,required:true})}${textareaField('Description','description',d.description)}`;if(d.step===1)body=`<h2>Modifier les paramètres</h2><p>Attribuez une catégorie et un niveau de gravité pour gérer la stratégie et les alertes qu’elle déclenche.</p>${selectField('Gravité','severity',[['','Sélectionner un niveau de gravité'],['None','None'],['High','High'],['Medium','Medium'],['Low','Low']],d.severity)}${selectField('Déclencher une alerte lors de la génération des informations suivantes','event',[['','Sélectionnez un type d’informations'],...alertEvents.map(x=>[x,x])],d.event)}`;if(d.step===2)body=`<h2>Destinataires</h2><p>Indiquez si vous voulez avertir les contacts lorsque cette alerte est déclenchée.</p><label class="checkbox-label"><input type="checkbox" name="notify" ${d.notify?'checked':''}> Envoyer une notification par e-mail</label>${field('Destinataires du courrier','recipients',{value:d.recipients})}${selectField('Limite de notification quotidienne','limit',[['0','Aucune limite'],...['1','5','10','25','50','100','150','200'].map(x=>[x,x])],d.limit)}`;if(d.step===3)body=`<h2>Évaluer la stratégie et terminer</h2>${infoKV('Nom de la stratégie',d.name)}${infoKV('Description',d.description||'—')}${infoKV('Gravité',d.severity)}${infoKV('Déclencher une alerte lorsque',d.event)}${infoKV('Destinataires',d.notify?d.recipients:'Ne pas envoyer de notifications par e-mail')}${infoKV('Limite de notification quotidienne',d.limit==='0'?'Aucune limite':d.limit)}<p class="muted">Cette stratégie est simulée et ne surveille pas les messages réels.</p>`;return `<div class="overlay-back"></div><section class="exchange-rule-wizard" role="dialog" aria-modal="true" aria-label="Nouvelle stratégie d’alerte"><header><h1>Nouvelle stratégie d’alerte</h1><button class="drawer-close" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></header><div class="exchange-rule-body"><div class="exchange-rule-steps">${steps.map((t,i)=>`<div class="exchange-rule-step ${i===d.step?'active':''} ${i<d.step?'completed':''}"><span>${i+1}</span>${esc(t)}</div>`).join('')}</div><div class="exchange-rule-content"><form id="form-exchange-alert-wizard">${body}<div id="form-error" class="form-error">${esc(ui.modalError)}</div></form></div></div><footer>${d.step?actionBtn('Précédent','exchange-alert-back'):''}<button class="btn primary" type="submit" form="form-exchange-alert-wizard">${d.step===3?'Créer':'Suivant'}</button>${actionBtn('Annuler','close-modal')}</footer></section>`;}
  function renderExchangeSettings(){const entries=[['Préférence de l’affichage de liste','Sélectionner l’affichage normal ou compact comme étant votre paramètre d’affichage de liste préféré.','exchange-list-preference'],['Flux de courrier','Gérer les paramètres de votre organisation pour l’envoi et la réception de messages','exchange-mailflow-preference'],['Configuration hybride','Connectez et gérez vos organisations locales et Exchange Online.','exchange-hybrid-setup']];return `<div class="exchange-page">${crumb([{text:'Accueil',route:'exchange/home'},{text:'Paramètres'}])}${title('Paramètres')}<div class="toolbar">${listSearch('Paramètres de recherche')}</div>${table(['Nom','Description'],entries.map(([name,desc,action])=>`<tr data-filter-row="${attr(normal(name+' '+desc))}"><td>${actionBtn(esc(name),'open-modal',action,'btn-link')}</td><td>${esc(desc)}</td></tr>`),'Aucun paramètre trouvé','700px')}</div>`;}
  function exchangeInsightSummary(){const now=Date.now(),recent=(item,days)=>{const date=Date.parse(item.date);return Number.isFinite(date)&&date<=now&&date>=now-days*86400000;},forwards=(Array.isArray(db.exchange.autoForwardEvents)?db.exchange.autoForwardEvents:[]).filter(x=>recent(x,7)),limits=(Array.isArray(db.exchange.receivingLimitEvents)?db.exchange.receivingLimitEvents:[]).filter(x=>recent(x,1));return [{key:'forward',title:'Messages transférés automatiquement',period:'7 derniers jours',count:forwards.reduce((n,e)=>n+Math.max(0,Number(e.count??1)||0),0),entities:new Set(forwards.map(e=>e.domain).filter(Boolean)).size,entityLabel:'domaines relevés',report:0},{key:'receiving',title:'Boîtes aux lettres au-delà des limites de réception',period:'24 dernières heures',count:limits.length,entities:new Set(limits.map(e=>normal(e.mailbox)).filter(Boolean)).size,entityLabel:'boîtes aux lettres relevées',report:8}];}
  function renderExchangeInsights(){const items=exchangeInsightSummary();return `<div class="exchange-page">${crumb([{text:'Accueil',route:'exchange/home'},{text:'Insights'}])}${title('Insights')}<p>Utilisez ces informations pour examiner les tendances du flux de courrier.</p><div class="entra-info">Ces informations sont calculées à partir des seuls événements locaux disponibles ; elles ne représentent pas les insights du service Microsoft réel.</div><h2>Flux de courrier</h2><div class="secure-score-cards">${items.map(x=>`<section class="card"><h3>${esc(x.title)}</h3><p>${esc(x.period)}</p><strong>${x.count}</strong><p>${x.entities} ${esc(x.entityLabel)}</p>${actionBtn('Afficher le rapport','exchange-insight-report',String(x.report),'btn-link')}</section>`).join('')}</div><div class="toolbar">${actionBtn(icon('download')+' Exporter','exchange-insights-export')}${actionBtn(icon('refresh')+' Actualiser','refresh')}</div><div class="quick-links">${link('Alertes','exchange/alerts')}${link('Rapports de flux de courrier','exchange/reports')}</div></div>`;}

  function exchangeMailflowDefaults(){return {disableAliases:false,sendAliases:false,disableSmtp:true,legacyTls:false,replyAllProtection:true,minRecipients:2500,minResponders:10,blockHours:6,recall:true,recallRead:true,recallAlerts:false,recallScope:'read',recallDays:0,recallHours:0,recallMinutes:0,...(db.exchange.mailflowSettings||{})};}
  const exchangeMailboxColumnCatalog=[['name','Nom complet'],['email','Adresse de courrier'],['type','Type de destinataire'],['alias','Alias'],['archive','État de l’archive'],['city','Ville'],['company','Entreprise'],['country','Pays ou région'],['department','Service'],['addresses','Adresses de courrier'],['exchangeVersion','Version d’Exchange'],['firstName','Prénom'],['lastName','Nom'],['litigation','Conservation pour litige activée'],['officeLocation','Bureau'],['phone','Téléphone'],['postalCode','Code postal'],['state','Département ou région'],['jobTitle','Titre'],['modified','Heure de la dernière modification'],...Array.from({length:15},(_,i)=>['custom'+(i+1),'Attribut personnalisé '+(i+1)])];
  const defaultExchangeMailboxColumns=['name','email','type','archive','modified'];
  function exchangeMailboxColumns(){const saved=db.exchange.mailboxColumns;return Array.isArray(saved)&&saved.includes('name')&&saved.every(k=>exchangeMailboxColumnCatalog.some(c=>c[0]===k))&&new Set(saved).size===saved.length?exchangeMailboxColumnCatalog.filter(([k])=>saved.includes(k)).map(([k])=>k):defaultExchangeMailboxColumns;}
  function exchangeMailboxValue(item,key){const {type,object:o}=item,m=type==='user'?o.exchangeMailbox||{}:o;if(key==='name')return type==='user'?o.displayName:o.name;if(key==='email')return type==='user'?o.mail||o.upn:o.email;if(key==='type')return type==='user'?'Boîte aux lettres utilisateur':'Boîte aux lettres partagée';if(key==='archive')return m.archive?'Activé':'Désactivé';if(key==='litigation')return m.litigationHold?'Oui':'Non';if(key==='addresses')return [type==='user'?o.mail||o.upn:o.email,...(o.proxyAddresses||[])].filter(Boolean).join(', ');if(key==='alias')return o.alias||o.mailNickname||(type==='user'?(o.mail||o.upn).split('@')[0]:'');if(key==='modified')return m.modified||o.created||'—';if(key.startsWith('custom'))return m.customAttributes?.[Number(key.slice(6))-1]||'—';return o[key]||'—';}
  function saveExchangeMailboxFilterDraft(form){const d=ui.exchangeMailboxFilterDraft;if(!d||!form)return;const f=new FormData(form),v=k=>String(f.get(k)||'').trim();d.name=v('name');d.clauses=d.clauses.map((c,i)=>({field:v('filterField'+i)||c.field,operator:v('filterOperator'+i)||c.operator,value:c.field==='litigation'?(f.has('filterValue'+i)?'Oui':'Non'):v('filterValue'+i)}));}
  function exchangeMailboxItems(filterOverride=null){const filter=filterOverride||ui.exchangeMailboxFilter||'all',custom=ui.exchangeMailboxCustomFilter,sort=ui.exchangeMailboxSort||'',dir=ui.exchangeMailboxSortDir||1;return [...db.users.filter(u=>u.license).map(object=>({type:'user',object})),...db.exchange.mailboxes.map(object=>({type:'shared',object}))].filter(item=>filter==='all'||filter==='custom'&&custom&&(custom.clauses||[]).every(c=>{const actual=normal(exchangeMailboxValue(item,c.field)),expected=normal(c.value);return c.operator==='is'?actual===expected:actual.startsWith(expected);})||filter===item.type||filter==='archive'&&(item.type==='user'?item.object.exchangeMailbox?.archive:item.object.archive)||filter==='litigation'&&(item.type==='user'?item.object.exchangeMailbox?.litigationHold:item.object.litigationHold)).sort((a,b)=>sort?dir*String(exchangeMailboxValue(a,sort)).localeCompare(String(exchangeMailboxValue(b,sort)),'fr',{sensitivity:'base'}):0);}
  function selectedExchangeMailboxes(){return ui.selected.map(key=>{const [type,id]=key.split(':');if(type==='user'){const user=db.users.find(u=>u.id===id&&u.license);return user?{type,id,object:user,settings:user.exchangeMailbox||{}}:null;}if(type==='shared'){const mailbox=db.exchange.mailboxes.find(m=>m.id===id);return mailbox?{type,id,object:mailbox,settings:mailbox}:null;}return null;}).filter(Boolean);}
  const ddgConditionFields=[['department','Service'],['company','Société'],['state','État ou région'],...Array.from({length:15},(_,i)=>['customAttribute'+(i+1),'Attribut personnalisé '+(i+1)])];
