  const exchangeRuleColumns=[['status','État'],['name','Règle'],['priority','Priorité'],['stop','Arrêter le traitement des règles'],['size','Taille (octets)'],['lastExecution','Dernière exécution'],['supported','Configuration prise en charge'],['unsupportedReason','Raison non prise en charge']];
  function exchangeRuleValue(r,i,key){if(key==='status')return r.enabled?'Activé':'Désactivé';if(key==='priority')return i;if(key==='stop')return r.stop?'Oui':'Non';if(key==='size')return r.size??'—';if(key==='supported')return r.configurationSupported===false?'Non':'Oui';return r[key]||'—';}
