  function exchangeRemoteItems(){const key=ui.exchangeRemoteSort||'name',dir=ui.exchangeRemoteSortDir||1,value=d=>key==='domain'?d.domain||d.email||'':key==='oof'?({None:'Aucun',External:'Externe',ExternalLegacy:'Externe et hérité',InternalLegacy:'Interne'})[d.oof]||'Externe':key==='autoReply'?(d.autoReply?'Activé':'Désactivé'):d.name||'';return [...db.exchange.remoteDomains].sort((a,b)=>dir*String(value(a)).localeCompare(String(value(b)),'fr',{sensitivity:'base'}));}
  function exchangeRemoteViewMenu(){const compact=db.exchange.listView==='compact'||db.exchange.listView!=='normal'&&db.exchange.listView!=='compact'&&db.exchange.remoteListView==='compact';return `<div class="entra-new-wrap">${actionBtn(icon('more'),'exchange-remote-view-menu','','icon-only')}${ui.exchangeRemoteViewMenu?`<div class="entra-new-menu">${actionBtn((compact?'':'✓ ')+'Liste normale','exchange-remote-display','normal')}${actionBtn((compact?'✓ ':'')+'Liste compacte','exchange-remote-display','compact')}</div>`:''}</div>`;}
