  const exchangeGroupColumnCatalog=[['name','Nom du groupe'],['mail','Adresse de courrier du groupe'],['sync','État de synchronisation'],['teams','Statut Teams'],['membership','Type d’appartenance'],['visibility','Confidentialité du groupe'],['created','Date de création'],['modified','Dernière modification le'],['nextRefresh','Prochaine actualisation planifiée']];
  function exchangeGroupColumns(){const tab=ui.exchangeGroupView||'standard',available=exchangeGroupColumnCatalog.filter(([key])=>tab==='dynamic'||!['modified','nextRefresh'].includes(key)),saved=db.exchange.groupColumns?.[tab];return available.filter(([key])=>key==='name'||!Array.isArray(saved)||saved.includes(key)).map(([key])=>key);}
