  function saveGroupNamingDraft(form){const d=ui.groupNamingDraft;if(!d||!form)return;const f=new FormData(form),v=k=>String(f.get(k)||'').trim();if(ui.groupNamingTab==='blocked'){d.blockedWords=v('blockedWords');return;}for(const side of ['prefixes','suffixes'])d[side]=d[side].map((row,i)=>({kind:v(side+'Kind'+i)||row.kind,value:v(side+'Value'+i)}));}
  function renderGroupNaming(){const d=ui.groupNamingDraft,tab=ui.groupNamingTab||'policy',rows=(side)=>d[side].map((row,i)=>`<div class="exchange-filter-clause">${selectField('Type',side+'Kind'+i,[['attribute','Attribut'],['text','Texte']],row.kind).replace('<select ',`<select data-group-naming-kind="${side}|${i}" `)}${row.kind==='attribute'?selectField('Attribut',side+'Value'+i,[['','Sélectionnez un'],...groupNamingAttributes],row.value):field('Texte',side+'Value'+i,{value:row.value})}${actionBtn('Supprimer','exchange-group-naming-row',side+'|'+i,'small')}</div>`).join(''),preview=side=>d[side].map(x=>x.value?(x.kind==='attribute'?'['+(groupNamingAttributes.find(a=>a[0]===x.value)?.[1]||x.value)+']':x.value):'').join('');let body=tab==='blocked'?`<p>Ajoutez le blocage de mots spécifiques pour empêcher leur utilisation dans les noms de groupes et les alias.</p>${textareaField('Bloquer les mots (séparés par une virgule)','blockedWords',d.blockedWords)}`:`<p>Ajoutez des préfixes et des suffixes aux noms des nouveaux groupes.</p><h3>Choisir un préfixe à ajouter au début des noms de groupe</h3>${rows('prefixes')}${actionBtn('Ajouter un préfixe','exchange-group-naming-row','prefixes|add')}<h3>Sélectionner un suffixe à ajouter à la fin des noms de groupes</h3>${rows('suffixes')}${actionBtn('Ajouter un suffixe','exchange-group-naming-row','suffixes|add')}<h3>Stratégie de préversion</h3><p data-group-naming-preview>${esc(preview('prefixes'))}&lt;GroupName&gt;${esc(preview('suffixes'))}</p>`;return `<div class="overlay-back"></div><section class="drawer m365-detail" role="dialog" aria-modal="true" aria-label="Modifier la stratégie de noms de groupes"><div class="m365-detail-top"><button class="drawer-close" data-action="close-modal" aria-label="Fermer">${icon('close')}</button><h1>Modifier la stratégie de noms de groupes</h1><nav class="sub-tabs">${[['policy','Stratégie'],['blocked','Mots bloqués']].map(([key,label])=>`<button class="tab ${tab===key?'active':''}" data-action="exchange-group-naming-tab" data-arg="${key}">${label}</button>`).join('')}</nav></div><div class="drawer-body"><form id="form-exchange-group-naming">${body}<div class="form-error" id="form-error">${esc(ui.modalError)}</div><button class="btn primary" type="submit">Enregistrer</button></form></div></section>`;}
  function exchangeGroupCategory(g){if(g.membership==='Dynamic Distribution')return 'dynamic';if(g.type==='Microsoft 365')return 'standard';if(g.type==='Distribution')return 'distribution';if(g.type==='Security'&&(g.mailEnabled||g.mail))return 'security';return '';}
  function exchangeGroupItems(all=false){const tab=ui.exchangeGroupView||'standard',filters=ui.exchangeGroupFilters||[];return db.groups.filter(g=>{const category=exchangeGroupCategory(g);return category&&(all||category===tab&&filters.every(f=>f==='dynamic'?['Dynamic','Dynamic User'].includes(g.membership):f==='ownerless'?!(g.owners||[]).length:true));}).sort((a,b)=>(ui.exchangeGroupSortDir||1)*String(a.name||'').localeCompare(String(b.name||''),'fr',{sensitivity:'base'}));}
  function exchangeGroupValues(g){return [g.name,g.mail||'',g.onPremisesSyncEnabled?'Synchronisé':'Dans le cloud',(g.teamsEnabled||g.teams)?'Connecté à Microsoft Teams':'Non connecté à Microsoft Teams',['Dynamic','Dynamic User','Dynamic Distribution'].includes(g.membership)?'Dynamique':'Affecté',(g.visibility||g.privacy)==='Public'?'Public':['Private','Privé'].includes(g.visibility||g.privacy)?'Privé':'—',g.created||'—'];}
