  function bulkSortValue(job,key){if(key==='status')return entraBulkStatus(job.status);if(key==='kind')return entraBulkType(job.kind);if(key==='modifiedAt')return job.modifiedAt||job.createdAt||'';if(key==='format')return job.format||job.fileName?.split('.').pop()||'';return job[key]||'';}
  function bulkViewLink(){const p=new URL('https://local.invalid/').searchParams,f=ui.entraBulkFilters||{days:30,types:null,status:[]};p.set('days',f.days);if(f.types)p.set('types',JSON.stringify(f.types));if(f.status?.length)p.set('status',JSON.stringify(f.status));if(ui.search)p.set('search',ui.search);p.set('sort',ui.bulkSortKey||'fileName');p.set('direction',ui.bulkSortDir===-1?'desc':'asc');p.set('cols',(ui.entraBulkLinkedColumns||db.entraBulkColumns||bulkDefaultColumns).join(','));return location.href.split('#')[0]+'#entra/monitoring-bulk/view?'+p.toString();}
  function applyBulkViewRoute(route){if(!route.startsWith('entra/monitoring-bulk/view?'))return;const p=new URL('https://local.invalid/?'+route.split('?')[1]).searchParams,days=Number(p.get('days')),allowedStatus=['Annulé','Échec','Non démarré','En pause','En cours d’exécution','Opération réussie'],f={days:[1,7,30].includes(days)?days:30,types:null,status:[]};for(const [key,allowed] of [['types',entraBulkTypes.map(([id])=>id)],['status',allowedStatus]])try{const v=JSON.parse(p.get(key)||'[]');if(Array.isArray(v)&&v.length<=allowed.length&&v.every(x=>allowed.includes(x)))f[key]=v.length?[...new Set(v)]:(key==='types'?null:[]);}catch{}const cols=(p.get('cols')||'').split(',').filter(Boolean);ui.entraBulkLinkedColumns=cols.includes('fileName')&&cols.every(key=>bulkColumnCatalog.some(([id])=>id===key))?[...new Set(cols)]:null;ui.bulkSortKey=bulkColumnCatalog.some(([id])=>id===p.get('sort'))?p.get('sort'):'fileName';ui.bulkSortDir=p.get('direction')==='desc'?-1:1;ui.entraBulkFilters=f;ui.entraBulkSelected=[];ui.search=(p.get('search')||'').slice(0,256);}
