  function filteredDomainServices(){return (db.domainServices||[]).filter(item=>(!Array.isArray(ui.domainServiceSubscriptions)||ui.domainServiceSubscriptions.includes(item.subscription))&&domainServiceFilters().every(filter=>{if(!filter.values.length)return true;const text=normal(item[filter.key]||''),negative=['ne','notContains','notStarts','notEnds'].includes(filter.op),match=filter.values.some(value=>{const needle=normal(value);if(['eq','ne'].includes(filter.op))return text===needle;if(['contains','notContains'].includes(filter.op))return text.includes(needle);if(['starts','notStarts'].includes(filter.op))return text.startsWith(needle);return text.endsWith(needle);});return negative?!match:match;}));}
