  function domainServiceViewSnapshot(){return {columns:[...domainServiceColumns()],filters:domainServiceFilters().map(f=>({key:f.key,op:f.op,values:[...f.values]})),subscriptions:Array.isArray(ui.domainServiceSubscriptions)?[...ui.domainServiceSubscriptions]:null,group:ui.domainServiceGroup||'none',search:ui.search||''};}
