    let results;if(!all.length)results=`<div class="domain-services-empty"><h2>Aucun Microsoft Entra Domain Services à afficher</h2><p>Activez la jonction de domaine transparente, l’intégration LDAP et les applications prenant en charge les répertoires dans les environnements Microsoft Entra pour simplifier la gestion et l’accès des utilisateurs.</p>${actionBtn(icon('plus')+' Créer','domain-service-new','', 'primary')} <a href="https://learn.microsoft.com/entra/identity/domain-services/overview?WT.mc_id=Portal-HubsExtension" target="_blank" rel="noopener noreferrer">En savoir plus</a></div>`;else if(!items.length||group[0]==='none')results=list(items);else{const buckets=new Map();for(const item of items){const label=value(item,group[0]);if(!buckets.has(label))buckets.set(label,[]);buckets.get(label).push(item);}results=[...buckets].map(([label,entries])=>`<section><h3>${esc(label)} (${entries.length})</h3>${list(entries)}</section>`).join('');}
    return `${crumb([{text:'Accueil',route:'entra/home'},{text:'Microsoft Entra Domain Services'}])}${title('Microsoft Entra Domain Services')}<p class="muted">${esc(db.tenant.name)} (${esc(db.tenant.primaryDomain)})</p><div class="toolbar entra-command">${actionBtn(icon('plus')+' Créer','domain-service-new')}<div class="entra-new-wrap domain-service-view-anchor"><button class="btn" data-action="domain-service-view-menu" aria-expanded="${!!ui.domainServiceViewMenu}">Gérer l’affichage ⌄</button>${ui.domainServiceViewMenu?`<div class="entra-new-menu">${actionBtn('Enregistrer l’affichage','domain-service-view-save')}${actionBtn('Enregistrer l’affichage sous','domain-service-view-save-as')}${actionBtn('Modifier les colonnes','domain-service-columns-open')}${actionBtn('Choisir l’affichage favori','domain-service-view-favorite')}${actionBtn('Affichage par défaut','domain-service-view-default')}${actionBtn('Parcourir toutes les vues pour « Microsoft Entra Domain Services »','domain-service-view-browse')}</div>`:''}</div>${actionBtn(icon('refresh')+' Actualiser','refresh')}${actionBtn(icon('download')+' Exporter au format CSV','domain-service-export')}<button class="btn" disabled>Attribuer des balises</button><div class="entra-new-wrap domain-service-group-anchor"><button class="btn" data-action="domain-service-group-menu" aria-expanded="${!!ui.domainServiceGroupMenu}" aria-haspopup="true">Regrouper par ${esc(group[1])} ⌄</button>${ui.domainServiceGroupMenu?`<div class="entra-new-menu" role="menu">${domainServiceGroups.map(([key,label])=>actionBtn('Regrouper par '+esc(label),'domain-service-group',key)).join('')}</div>`:''}</div></div><div class="toolbar">${listSearch('Rechercher')}${actionBtn('Abonnement est égal à '+esc(Array.isArray(ui.domainServiceSubscriptions)?(ui.domainServiceSubscriptions.join(', ')||'aucun'):'tout'),'domain-service-subscriptions-open','','entra-filter-pill')}${domainServiceFilters().map(f=>`<span class="entra-filter-pill">${actionBtn(esc(domainServiceFilterFields.find(([key])=>key===f.key)[1])+' '+esc(domainServiceFilterOps.find(([key])=>key===f.op)[1].toLocaleLowerCase('fr'))+' '+esc(f.values.join(', ')||'tout'),'domain-service-filter-open',f.key,'btn-link')}${actionBtn('×','domain-service-filter-remove',f.key,'btn-link','Supprimer le filtre')}</span>`).join('')}${actionBtn('Ajouter un filtre','domain-service-filter-open','new','entra-filter-pill')}</div>${results}<p class="muted">Affichage de ${items.length} sur ${all.length}</p>`;
