  function crossAccessDefaults(){return {inbound:{collabUsers:'allow',collabApps:'allow',directUsers:'block',directApps:'block',trustMfa:false,trustCompliant:false,trustHybrid:false},outbound:{collabUsers:'allow',collabApps:'allow',directUsers:'block',directApps:'block'},restrictions:{users:'block',apps:'block'},...(db.crossAccessDefaults||{})};}
  function renderCrossAccess(){const tab=ui.crossAccessTab||'organizations',settings=crossAccessDefaults(),state=v=>v==='allow'?'Tous autorisés':'Tous bloqués',row=(type,target,val)=>`<tr><td>${type}</td><td>${target}</td><td>${state(val)}</td></tr>`,section=(title,key)=>{const d=settings[key];return `<h3>${title}</h3><div class="toolbar">${actionBtn(icon('edit')+' Modifier les valeurs par défaut '+(key==='inbound'?'entrantes':'sortantes'),'open-modal','cross-access-edit:'+key)}</div>${table(['Type','S’applique à','État'],[row('B2B Collaboration',key==='inbound'?'Utilisateurs et groupes externes':'Utilisateurs et groupes',d.collabUsers),row('B2B Collaboration',key==='inbound'?'Applications':'Applications externes',d.collabApps),row('Connexion directe B2B',key==='inbound'?'Utilisateurs et groupes externes':'Utilisateurs et groupes',d.directUsers),row('Connexion directe B2B',key==='inbound'?'Applications':'Applications externes',d.directApps),...(key==='inbound'?[`<tr><td>Paramètres d’approbation</td><td>N/A</td><td>${d.trustMfa||d.trustCompliant||d.trustHybrid?'Activé':'Désactivé'}</td></tr>`]:[])])}`;};let body='';
    if(tab==='organizations'){const orgs=db.crossAccessOrganizations||[];body=`<div class="toolbar entra-command">${actionBtn(icon('plus')+' Ajouter une organisation','open-modal','cross-access-org')}${actionBtn(icon('refresh')+' Actualisez','refresh')}</div><p>Utilisez les paramètres d’accès inter-locataires pour gérer la collaboration avec les clients Microsoft Entra externes.</p>${actionBtn('Modifier ou afficher les restrictions de collaboration','external-view','settings')}<p>Les organisations qui ne figurent pas dans cette liste utilisent les paramètres par défaut.</p>${listSearch('Rechercher par nom de locataire ou ID de locataire')}<p class="muted">${orgs.length} organisations trouvées</p>${table(['Nom','Accès entrant','Accès sortant','Restrictions liées au locataire','Supprimer'],orgs.map(o=>`<tr data-filter-row="${attr(normal(o.identifier))}"><td>${esc(o.identifier)}</td>${['inbound','outbound','restrictions'].map(k=>`<td>${actionBtn(o.overrides?.[k]?'Personnalisé':'Hérité des valeurs par défaut','open-modal','cross-access-edit:'+k+'|'+o.id,'btn-link')}</td>`).join('')}<td>${actionBtn(icon('trash'),'cross-access-delete',o.id,'icon-only')}</td></tr>`),'Ajouter votre première organisation pour configurer les paramètres spécifiques à l’organisation') }`;}
    else if(tab==='defaults')body=`<p>Les paramètres par défaut s’appliquent à toutes les organisations Microsoft Entra externes qui ne sont pas répertoriées sous l’onglet Paramètres d’organisation.</p>${section('Paramètres d’accès entrant','inbound')}${section('Paramètres d’accès sortant','outbound')}<h3>Restrictions liées au locataire</h3><div class="toolbar">${actionBtn(icon('edit')+' Modifier les restrictions liées au locataire par défaut','open-modal','cross-access-edit:restrictions')}</div>${table(['S’applique à','État'],[`<tr><td>Utilisateurs et groupes externes</td><td>${state(settings.restrictions.users)}</td></tr>`,`<tr><td>Applications externes</td><td>${state(settings.restrictions.apps)}</td></tr>`])}`;
    else {const d=db.crossAccessClouds||{},check=(k,t)=>`<label class="checkbox-label"><input type="checkbox" name="${k}" ${d[k]?'checked':''}> ${t}</label>`,labels=[['gov','Microsoft Azure Government'],['china','Microsoft Azure Chine (géré par 21Vianet)'],['france','Microsoft Azure France (géré par Bleu)']];body=`<form id="form-cross-cloud"><p>Les paramètres cloud Microsoft vous permettent de collaborer avec des organisations de différents clouds Microsoft.</p>${labels.map(([k,t])=>check('access_'+k,t)).join('')}<p>Les paramètres de synchronisation entre clouds vous permettent de gérer le cycle de vie des utilisateurs à travers les locataires de votre organisation.</p>${labels.map(([k,t])=>check('sync_'+k,t)).join('')}<div class="toolbar"><button type="submit" class="btn primary">Enregistrer</button>${actionBtn('Abandonner','cross-access-reset')}</div></form>`;}
    return `<nav class="sub-tabs">${[['Paramètres d’organisation','organizations'],['Paramètres par défaut','defaults'],['Paramètres du cloud Microsoft','cloud']].map(([label,key])=>`<button class="tab ${tab===key?'active':''}" data-action="cross-access-tab" data-arg="${key}">${label}</button>`).join('')}</nav>${body}`;
  }
  const manageTenantColumns=[['name','Nom de l’organisation'],['domain','Nom du domaine'],['type','Type de locataire'],['id','ID d’organisation'],['favorite','Favori']];
  function manageTenantSubscriptions(){return (db.azureSubscriptions||[]).length?db.azureSubscriptions:[{id:'lab-subscription',name:'Abonnement fictif'}];}
  function manageTenantResourceGroups(){const groups=(db.azureScopes||[]).filter(x=>x.type==='resourceGroup');return groups.length?groups:[{id:'lab-resource-group',name:'Groupe de ressources fictif',type:'resourceGroup',subscriptionId:'lab-subscription'}];}
  function selectedManageTenantColumns(){const saved=db.manageTenantColumns;return Array.isArray(saved)?manageTenantColumns.filter(([key])=>key==='name'||saved.includes(key)):manageTenantColumns;}
  function visibleManageTenants(){const type=ui.manageTenantsType||'Tout',query=normal(ui.manageTenantsQuery||''),items=[{id:db.tenant.id,name:db.tenant.name,domain:db.tenant.primaryDomain,type:'Employés',current:true,favorite:!!db.favoriteCurrentTenant},...(db.simulatedTenants||[])];return (ui.manageTenantsTab||'all')==='all'?items.filter(t=>(type==='Tout'||t.type===type)&&normal([t.name,t.domain,t.id].join(' ')).includes(query)):[];}
  function renderManageTenants(){
    const tab=ui.manageTenantsTab||'all',type=ui.manageTenantsType||'Tout',tenants=[db.tenant,...(db.simulatedTenants||[])],visible=visibleManageTenants(),selected=Array.isArray(ui.manageTenantSelected)?ui.manageTenantSelected:[],cols=tab==='all'?selectedManageTenantColumns():[...manageTenantColumns.slice(0,4),['actions','Actions']];
    const row=t=>{const cells={name:esc(t.name)+(t.current?' (Par défaut)':''),domain:esc(t.domain),type:esc(t.type),id:esc(t.id),favorite:actionBtn(t.favorite?'Retirer':'Définir','manage-tenant-favorite',t.id,'btn-link')};return `<tr><td><input type="checkbox" data-action="manage-tenant-select" data-arg="${attr(t.id)}" aria-label="Sélectionner ${attr(t.name)}" ${selected.includes(t.id)?'checked':''}></td>${cols.map(([key])=>`<td>${cells[key]||''}</td>`).join('')}</tr>`;};
    const canDelete=selected.length>0&&selected.every(id=>visible.some(t=>!t.current&&t.id===id)),toolbar=tab==='all'?`${actionBtn(icon('plus')+' Créer','open-modal','manage-tenant-create')}${actionBtn(icon('refresh')+' Actualiser','refresh')}${actionBtn('Colonnes','open-modal','manage-tenant-columns')}<button class="btn" disabled>Commutateur</button><button class="btn" data-action="manage-tenant-delete" ${canDelete?'':'disabled'}>Supprimer</button><button class="btn" disabled>Quitter le locataire</button><button class="btn" disabled>Définir comme locataire par défaut</button>`:`${actionBtn(icon('refresh')+' Actualiser','refresh')}<button class="btn" disabled>Commutateur</button><button class="btn" disabled>Informations supplémentaires</button>`;
    return `${crumb([{text:'Accueil',route:'entra/home'},{text:'Microsoft Entra',route:'entra/home'}])}${title('Gérer les clients')}<div class="toolbar entra-command">${toolbar}</div><p>Locataire actuel : ${esc(db.tenant.name)}</p><div class="toolbar"><input type="search" data-manage-tenant-search aria-label="Rechercher un locataire" placeholder="Rechercher" value="${attr(ui.manageTenantsQuery||'')}"><div class="suggestion-filter-anchor">${actionBtn('Type de locataire : '+type,'manage-tenant-filter')}${ui.manageTenantsFilterOpen?`<form id="form-manage-tenant-filter" class="suggestion-filter-menu" aria-label="Type de locataire"><h3>Type de locataire</h3>${['Employés','Externe','Tout'].map(x=>`<label class="checkbox-label"><input type="radio" name="type" value="${x}" ${type===x?'checked':''}> ${x}</label>`).join('')}<div class="suggestion-filter-actions"><button class="btn primary" type="submit">Appliquer</button>${actionBtn('Annuler','manage-tenant-filter')}</div></form>`:''}</div></div><p>Affichage de ${visible.length} sur ${tab==='all'?tenants.length:0} résultats</p><nav class="sub-tabs"><button class="tab ${tab==='all'?'active':''}" data-action="manage-tenant-tab" data-arg="all">Tous les locataires</button><button class="tab ${tab==='governed'?'active':''}" data-action="manage-tenant-tab" data-arg="governed">Locataires gouvernés</button></nav>${table([`<input type="checkbox" data-action="manage-tenant-select-all" aria-label="Sélectionner tous les éléments" ${visible.length&&visible.every(t=>selected.includes(t.id))?'checked':''}>`,...cols.map(([,label])=>esc(label))],visible.map(row),'Aucun locataire trouvé','950px',false)}<p class="muted">Les fiches créées sont fictives ; le changement de locataire n’est pas encore disponible.</p>`;
  }
  function localPasswordExpirationPolicy(){return db.passwordExpirationPolicy||{neverExpires:true,validityDays:730};}
  function secureRecommendations(){const admins=new Set(db.roleAssignments.filter(a=>a.roleId==='global'&&db.users.some(u=>u.id===a.userId&&u.enabled)).map(a=>a.userId)),privilegedUsers=new Set(db.roleAssignments.filter(a=>roleOf(a.roleId)?.privileged===true&&db.users.some(u=>u.id===a.userId)).map(a=>a.userId)),privilegedUnknown=db.roleAssignments.some(a=>roleOf(a.roleId)?.privileged===null&&db.users.some(u=>u.id===a.userId)),passwordPolicy=localPasswordExpirationPolicy();return [
    {id:'app-consent',name:'Ne pas autoriser les utilisateurs à accorder leur consentement aux applications non fiables',priority:'Moyen',points:'—',resource:'Niveau du locataire',computed:'Non évalué',description:'Examinez les paramètres de consentement des applications et limitez les autorisations accordées aux applications non fiables.',route:'entra/enterprise'},
    {id:'multiple-admins',name:'Désigner plus d’un administrateur général',priority:'Faible',points:admins.size>=2?'1/1':'0/1',resource:'Utilisateurs',computed:admins.size>=2?'Terminé':'Actif',description:`Vous avez actuellement ${admins.size} administrateur${admins.size===1?'':'s'} généra${admins.size===1?'l':'ux'} actif${admins.size===1?'':'s'}.`,route:'entra/roles'},
    {id:'password-hash',name:'Activer la synchronisation de hachage de mot de passe si hybride',priority:'Moyen',points:'—',resource:'Niveau du locataire',computed:'Non évalué',description:db.tenant.passwordSyncEnabled?'La synchronisation de hachage de mot de passe est activée.':'Examinez la configuration de synchronisation de votre annuaire hybride.',route:'entra/connect'},
    {id:'password-expiry',name:'Ne pas laisser expirer les mots de passe',priority:'Élevé',points:passwordPolicy.neverExpires?'8/8':'0/8',resource:'Niveau du locataire',computed:passwordPolicy.neverExpires?'Terminé':'Actif',description:passwordPolicy.neverExpires?'Votre stratégie actuelle est définie de manière à ne jamais laisser les mots de passe expirer.':`La stratégie locale prévoit une expiration après ${passwordPolicy.validityDays} jours.`,route:'m365/org-settings'},
    {id:'least-privilege',name:'Utilisez les rôles d’administration les moins privilégiés',priority:'Faible',points:'—',resource:'Utilisateurs',computed:'Non évalué',description:`Vous avez actuellement ${privilegedUnknown?'au moins ':''}${privilegedUsers.size} utilisateur${privilegedUsers.size===1?'':'s'} doté${privilegedUsers.size===1?'':'s'} de rôles d’administration privilégiés.`,route:'entra/roles'}
  ].map(x=>{const status=db.secureRecommendationStates?.[x.id]||x.computed,detail=db.secureRecommendationStateDetails?.[x.id],updated=detail?.status===status&&Number.isFinite(Date.parse(detail.at||''))?detail.at:'';return {...x,components:x.id==='password-expiry'?[]:['Applications'],status,updated};});}
  function localIdentityScore(){const values=secureRecommendations().map(r=>r.points.split('/').map(Number)).filter(v=>v.length===2&&v.every(Number.isFinite)&&v[1]>0),earned=values.reduce((sum,v)=>sum+v[0],0),possible=values.reduce((sum,v)=>sum+v[1],0);return possible?((earned/possible)*100).toFixed(2)+' %':'Non disponible';}
  function recommendationStateDescription(r){const entry=db.secureRecommendationStateDetails?.[r.id],when=entry?.at?new Date(entry.at):null;if(entry&&entry.status===r.status&&when&&!Number.isNaN(when.getTime()))return 'Marqué comme '+r.status.toLocaleLowerCase('fr-FR')+' par '+(entry.by||'un utilisateur local')+' le '+when.toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'})+'.';return r.status==='Non évalué'?'Non évalué dans le laboratoire.':r.status;}
  function recommendationResourcesFor(key){const items=db.secureRecommendationResources?.[key];return Array.isArray(items)?items.filter(x=>x&&typeof x.id==='string'&&typeof x.name==='string'):[];}
  function recommendationResources(){const key=ui.overlay?.startsWith('secure-recommendation:')?ui.overlay.slice('secure-recommendation:'.length):'';return recommendationResourcesFor(key);}
  function filteredRecommendationResources(){const status=ui.recommendationResourceStatus||'Tout',query=normal(ui.recommendationResourceSearch||''),sort=ui.recommendationResourceSort||{},keys={'Ressource':'name','ID':'id','Détecté pour la première fois':'firstDetected','État':'status'};return recommendationResources().filter(r=>(status==='Tout'||r.status===status)&&normal(r.id).includes(query)).sort((a,b)=>{if(!sort.key)return 0;const av=a[keys[sort.key]]||'',bv=b[keys[sort.key]]||'';if(sort.key==='Détecté pour la première fois'){const at=av?Date.parse(av):NaN,bt=bv?Date.parse(bv):NaN;if(Number.isFinite(at)&&Number.isFinite(bt))return (at-bt)*(sort.desc?-1:1);if(Number.isFinite(at)!==Number.isFinite(bt))return Number.isFinite(at)?-1:1;}return String(av).localeCompare(String(bv),'fr',{sensitivity:'base'})*(sort.desc?-1:1);});}
  function recommendationResourceDate(value,zone){const d=new Date(value);if(!value||Number.isNaN(d.getTime()))return '—';return d.toLocaleString('fr-FR',{dateStyle:'medium',timeStyle:'short',...(zone==='UTC'?{timeZone:'UTC'}:{})});}
  function renderRecommendationResources(){const status=ui.recommendationResourceStatus||'Tout',date=ui.recommendationResourceDate||'Local',sort=ui.recommendationResourceSort||{},all=recommendationResources(),items=filteredRecommendationResources(),selected=ui.recommendationResourceSelected||[],visible=items.slice(0,1000),selectedCount=visible.filter(r=>selected.includes(r.id)).length,allSelected=visible.length>0&&selectedCount===visible.length;return `<section class="recommendation-resources"><h3>Ressources impactées</h3><div class="secure-score-categories">${['Tout','Actif','Terminé','Ignoré','Reporté'].map(label=>`<button class="${status===label?'active':''}" aria-pressed="${status===label}" data-action="recommendation-resource-status" data-arg="${attr(label)}">${esc(label)}<strong>${label==='Tout'?all.length:all.filter(r=>r.status===label).length}</strong></button>`).join('')}</div><div class="sub-tabs suggestion-category-tabs" role="tablist" aria-label="États des ressources impactées">${['Tout','Actif','Terminé','Ignoré','Reporté'].map(label=>`<button role="tab" aria-selected="${status===label}" tabindex="${status===label?'0':'-1'}" data-action="recommendation-resource-status" data-arg="${attr(label)}">${esc(label)}</button>`).join('')}</div><div class="toolbar"><div class="suggestion-filter-anchor recommendation-resource-menu-anchor"><button class="btn" data-action="recommendation-resource-menu" aria-haspopup="true" ${selected.length?'':'disabled'} aria-expanded="${!!ui.recommendationResourceMenu}">Marquer la ressource comme ﹀</button>${ui.recommendationResourceMenu&&selected.length?`<div class="entra-new-menu">${['Actif','Ignoré','Reporté'].map(v=>actionBtn(v,'recommendation-resource-set-status',v)).join('')}</div>`:''}</div>${actionBtn(icon('download')+' Exporter','recommendation-resource-export')}</div><div class="toolbar"><span class="recommendation-resource-search" role="search" aria-label="Rechercher par ID">${icon('search')}<input type="search" data-recommendation-resource-search placeholder="Rechercher par ID" aria-label="Rechercher par ID" value="${attr(ui.recommendationResourceSearch||'')}">${ui.recommendationResourceSearch?`<button type="button" class="recommendation-search-clear" data-action="recommendation-resource-search-clear" aria-label="Effacer le texte">×</button>`:''}</span><div class="suggestion-filter-anchor recommendation-date-anchor"><button type="button" class="btn" data-action="recommendation-resource-date" aria-expanded="${!!ui.recommendationResourceDateOpen}">Afficher les dates au format : ${esc(date)}</button>${ui.recommendationResourceDateOpen?`<div class="suggestion-filter-menu" role="menu" aria-label="Afficher les dates au format"><h3>Afficher les dates au format</h3><div class="suggestion-filter-section" role="group" aria-label="Valeur"><div>Valeur</div><div role="radiogroup" aria-label="Afficher les dates au format">${['UTC','Local'].map(v=>`<label class="checkbox-label"><input type="radio" name="recommendation-resource-date" data-recommendation-resource-date value="${v}" ${ui.recommendationResourceDateDraft===v?'checked':''}> ${v}</label>`).join('')}</div></div><div class="suggestion-filter-actions"><button class="btn primary" data-action="recommendation-resource-date-apply" ${ui.recommendationResourceDateDraft===date?'disabled':''}>Appliquer</button>${actionBtn('Annuler','recommendation-resource-date-cancel')}</div></div>`:''}</div>${actionBtn(icon('filterClear')+' Réinitialiser les filtres','recommendation-resource-reset')}</div><span class="sr-only" role="status">Chargement des ressources terminé</span><div class="entra-info" role="status">Affichage des 1 000 premières lignes. Pour plus de détails, cliquez sur Exporter pour un maximum de 100 000 enregistrements. Pour en télécharger d’autres, <a href="https://aka.ms/recommendation-list-impactedresources" target="_blank" rel="noopener noreferrer">voir ici.</a></div>${table([`<input type="checkbox" data-recommendation-resource-all aria-label="Activer/désactiver la sélection pour toutes les ressources de recommandation sélectionnables dans l’affichage actuel" aria-checked="${allSelected?'true':selectedCount?'mixed':'false'}" ${allSelected?'checked':''}>`,...[['Ressource','Ressource'],['ID','ID'],['Détecté pour la première fois',date==='UTC'?'Première détection (UTC)':'Détecté pour la première fois'],['État','État']].map(([key,label])=>actionBtn(esc(label)+(sort.key===key?(sort.desc?' ↓':' ↑'):''),'recommendation-resource-sort',key,'btn-link'))],items.slice(0,1000).map(r=>`<tr><td><input type="checkbox" data-recommendation-resource-check="${attr(r.id)}" aria-label="Sélectionner ${attr(r.name)}" ${selected.includes(r.id)?'checked':''}></td><td>${esc(r.name)}</td><td>${esc(r.id)}</td><td>${esc(recommendationResourceDate(r.firstDetected,date))}</td><td>${esc(r.status||'—')}</td></tr>`),'Aucun résultat.','650px',false)}<p role="status" aria-live="polite">${items.length} ressource${items.length===1?'':'s'} trouvée${items.length===1?'':'s'}</p></section>`;}

  function renderSecurityGettingStarted(){const documentation=[['Accès conditionnel Microsoft Entra','https://go.microsoft.com/fwlink/?linkid=2085020'],['Protection des ID Microsoft Entra','https://go.microsoft.com/fwlink/?linkid=2035976'],['Azure Security Center','https://go.microsoft.com/fwlink/?linkid=2085021'],["Score d’identité sécurisée",'https://go.microsoft.com/fwlink/?linkid=2085022'],['Emplacements nommés','https://go.microsoft.com/fwlink/?linkid=2085023'],["Méthodes d’authentification",'https://go.microsoft.com/fwlink/?linkid=2084917'],['Authentification multifacteur','https://go.microsoft.com/fwlink/?linkid=2085024']],guidance=[["5 étapes pour sécuriser votre infrastructure d’identité",'https://go.microsoft.com/fwlink/?linkid=2084916'],['Guide de mot de passe Microsoft Entra','https://go.microsoft.com/fwlink/?linkid=2085125'],['Livre blanc sur la sécurité des données avec Microsoft Entra ID','https://aka.ms/aaddatawhitepaper'],['Fonctionnement de la synchronisation de hachage de mot de passe (PHS)','https://go.microsoft.com/fwlink/?linkid=2085112&clcid=0x409']],list=items=>`<ul>${items.map(([label,url])=>`<li><a href="${attr(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a></li>`).join('')}</ul>`;return `<div class="security-getting-started"><section><span class="security-guide-icon" aria-hidden="true">${icon('chart')}</span><div><h3>Documentation</h3><p>Microsoft Entra ID propose une gamme de fonctionnalités de sécurité afin de protéger votre organisation. Pour plus d’informations, voici quelques fonctionnalités pour commencer.</p>${list(documentation)}</div></section><section><span class="security-guide-icon" aria-hidden="true">${icon('info')}</span><div><h3>Guide de la sécurité</h3><p>Pour une sécurité renforcée, nous vous recommandons ce qui suit :</p>${list(guidance)}</div></section><section><span class="security-guide-icon" aria-hidden="true">${icon('document')}</span><div><h3>Guides de déploiement</h3><p>Pour déployer les fonctionnalités ci-dessus dans votre organisation, consultez <a href="https://go.microsoft.com/fwlink/?linkid=2085126" target="_blank" rel="noopener noreferrer">Plans de déploiement Microsoft Entra ID.</a></p></div></section></div>`;}
  function renderRiskyAgentsEmpty(){return `<section class="risk-agents-empty"><svg viewBox="0 0 100 90" width="100" height="90" aria-hidden="true"><rect x="3" y="12" width="94" height="72" rx="4" fill="#7ab9e0"/><path d="M10 8c15-4 28-2 40 5v65c-12-7-25-8-40-5z" fill="#f4f5f6"/><path d="M90 8c-15-4-28-2-40 5v65c12-7 25-8 40-5z" fill="#e9eaec"/><path d="M18 18h24M18 26h24M18 34h24M18 42h24M18 50h24M18 58h24M18 66h18" stroke="#cdd2d6" stroke-width="3"/></svg><h2>Aucun agent à risque n’est identifié</h2><p>La protection des ID pour les agents est désormais disponible avec Microsoft Agent 365 dans Entra.</p><a href="https://learn.microsoft.com/en-us/entra/identity/conditional-access/agent-id?tabs=custom-security-attributes" target="_blank" rel="noopener noreferrer">Découvrez plus d’informations.</a></section>`;}
  function renderPkiFilterPopover(){const isDate=ui.pkiFilterField==='date'&&ui.pkiTab==='deleted';return `<div class="suggestion-filter-menu pki-filter-popover" role="dialog" aria-label="Ajouter un filtre"><h3>Ajouter un filtre</h3><form id="form-pki-filter">${field('Filtrer','filter',{value:isDate?'Date et heure de suppression':'Nom d’affichage',readonly:true})}${selectField('Opérateur','op',isDate?[['gte','>='],['lte','<=']]:[['starts','commence par'],['eq','==']],isDate?'gte':'starts')}${field('Valeur','value',{type:isDate?'date':'text',required:true})}<div class="suggestion-filter-actions"><button type="submit" form="form-pki-filter" class="btn primary" disabled>Appliquer</button>${actionBtn('Annuler','pki-filter-cancel')}</div></form></div>`;}
  function renderEntraPki(){const deleted=ui.pkiTab==='deleted',items=(db.publicKeyInfrastructures||[]).filter(x=>!!x.deleted===deleted&&normal(x.name).includes(normal(ui.search||''))&&(!ui.pkiFilter||(ui.pkiFilter.field==='date'?(x.deletedAt&&((ui.pkiFilter.op==='lte'?(new Date(x.deletedAt).getTime()<=new Date(ui.pkiFilter.value+'T23:59:59').getTime()):(new Date(x.deletedAt).getTime()>=new Date(ui.pkiFilter.value+'T00:00:00').getTime())))):(ui.pkiFilter.op==='eq'?normal(x.name)===normal(ui.pkiFilter.value):normal(x.name).startsWith(normal(ui.pkiFilter.value)))))),selected=items.some(x=>x.id===ui.pkiSelected),columns=db.pkiColumns||['status','details'],labels={status:'État de la dernière opération',details:'Détails de l’état',id:'ID d’objet'};return `<div class="sub-tabs" role="tablist"><button role="tab" aria-selected="${!deleted}" class="tab ${!deleted?'active':''}" data-action="pki-tab" data-arg="active">Indicateurs de performance clés</button><button role="tab" aria-selected="${deleted}" class="tab ${deleted?'active':''}" data-action="pki-tab" data-arg="deleted">Infrastructures à clé publique supprimées</button></div><div class="toolbar entra-command">${deleted?`<button class="btn" disabled>Supprimer définitivement</button><button class="btn" data-action="pki-restore" ${selected?'':'disabled'}>Restaurer l’infrastructure à clé publique</button>`:`${actionBtn(icon('plus')+' Créer un PKI','open-modal','pki-create')}<button class="btn" disabled>Modifier</button><button class="btn" data-action="pki-delete" ${selected?'':'disabled'}>Supprimer</button>`} ${actionBtn(icon('refresh')+' Actualisez','pki-refresh')} ${deleted?'':actionBtn('Modifier les colonnes','pki-columns-open')}</div>${listSearch('Rechercher')}${ui.pkiFilter?`<span class="entra-filter-pill"><button class="btn-link" disabled>${esc(ui.pkiFilter.field==='date'?'Date et heure de suppression':'Nom d’affichage')} ${esc(({eq:'==',starts:'commence par',gte:'>=',lte:'<='})[ui.pkiFilter.op])} ${esc(ui.pkiFilter.value)}</button>${actionBtn('×','pki-filter-clear','','btn-link','Supprimer')}</span>`:`<span class="entra-new-wrap pki-filter-anchor"><button class="btn" data-action="pki-filter-menu" aria-expanded="${!!(ui.pkiFilterMenu||ui.pkiFilterEditing)}">Ajouter un filtre</button>${ui.pkiFilterEditing?renderPkiFilterPopover():ui.pkiFilterMenu?`<span class="entra-new-menu" role="menu"><strong>Ajouter un filtre</strong>${actionBtn('Nom d’affichage','pki-filter-open','name')}${deleted?actionBtn('Date et heure de suppression','pki-filter-open','date'):''}</span>`:''}</span>`}<p>${items.length} PKI détectées</p>${table(['','Nom d’affichage',...(deleted?['Date et heure de suppression']:[]),...(deleted?['État de la dernière opération','Détails de l’état']:columns.map(x=>labels[x]))],items.map(x=>`<tr><td><input type="radio" name="pki-selection" data-pki-select="${attr(x.id)}" aria-label="Sélectionner ${attr(x.name)}" ${ui.pkiSelected===x.id?'checked':''}></td><td>${esc(x.name)}</td>${deleted?`<td>${esc(x.deletedAt&&Number.isFinite(Date.parse(x.deletedAt))?new Date(x.deletedAt).toLocaleString('fr-FR'):x.deletedAt||'')}</td>`:''}${(deleted?['status','details']:columns).map(x=>`<td>${x==='status'?'Réussie':x==='id'?esc(x.id):'—'}</td>`).join('')}</tr>`),'Aucun résultat.','700px',false)}`;}
  function renderEntraSecurityCenter(){return `<div class="entra-security-center"><button class="entra-security-upgrade" data-action="goto" data-arg="entra/defender-setup"><span aria-hidden="true">✦</span> Pour améliorer les fonctionnalités de sécurité, mettez à niveau votre abonnement Microsoft Defender pour le cloud 'Ordinateurs virtuels, Posture du cloud, App Services, Conteneurs, Bases de données Azure SQL Database, Comptes de stockage' plans <span aria-hidden="true">→</span></button><div class="entra-info">Visiter Microsoft Defender pour le cloud pour gérer la sécurité sur vos réseaux virtuels, données, applications, etc.</div><div class="entra-security-center-summary"><section><div>Recommandations par gravité</div><p>Élevée &nbsp; 0</p><p>Moyenne &nbsp; 0</p><p>Faible &nbsp; 0</p></section><section><div>Alertes par gravité</div><p>Élevée &nbsp; 0</p><p>Moyenne &nbsp; 0</p><p>Faible &nbsp; 0</p></section><section><div>En savoir plus</div><p><a href="https://go.microsoft.com/fwlink/?linkid=2118618" target="_blank" rel="noopener noreferrer">À propos de Microsoft Defender pour le cloud</a></p><p><a href="https://learn.microsoft.com/azure/security-center/security-center-identity-access?WT.mc_id=Portal-Microsoft_Azure_Security" target="_blank" rel="noopener noreferrer">À propos de l’analyse de l’identité et de l’accès</a></p></section></div><h2>Recommandations sur l’identité et l’accès</h2><p>Microsoft Defender pour le cloud surveille en permanence l’activité d’identité et d’accès des utilisateurs, identifie les vulnérabilités et recommande des actions pour les atténuer.</p><div class="entra-security-center-empty"><div aria-hidden="true">☑<br>☑<br>☑</div><p>Aucune recommandation à afficher<br>Il n’y a aucune recommandation de sécurité pour les abonnements sélectionnés</p><button class="btn primary" disabled title="Microsoft Defender pour le cloud n’est pas connecté au laboratoire">Afficher toutes les recommandations dans Defender pour le cloud</button></div><h2>Alertes de sécurité</h2><p>Découvrez les menaces à un stade précoce pour y répondre rapidement et empêcher les attaques futures</p><p>Mettez à niveau {0} pour une meilleure sécurité, notamment</p><ul><li>Accès JIT, qui réduit l’exposition aux attaques du réseau</li><li>Contrôles d’application adaptatifs pour bloquer les applications malveillantes ou non prises en charge</li><li>Détection des menaces à l’aide de l’analytique avancée et du renseignement général sur les menaces</li><li>Outils d’enquête interactifs et résolution automatique pour une réponse rapide</li><li>Et bien plus encore</li></ul><button class="btn" disabled title="Microsoft Defender pour le cloud n’est pas connecté au laboratoire">Essayer gratuitement pendant les 30 premiers jours</button></div>`;}
  const defenderAwsRegions=['USA Est (Virginie du Nord)','USA Est (Ohio).','USA Ouest (Californie du Nord)','USA Ouest (Oregon)','Afrique (Cape Town)','Asie-Pacifique (Hong Kong)','Asie-Pacifique (Hyderabad)','Asie-Pacifique (Mumbai)','Asie-Pacifique (Tokyo)','Asie-Pacifique (Osaka)','Asie-Pacifique (Séoul)','Asie-Pacifique (Singapour)','Asie-Pacifique (Sydney)','Asie-Pacifique (Jakarta)','Asie-Pacifique (Melbourne)','Canada (Centre)','Canada Ouest (Canada)','Europe (Irlande)','Europe (Londres)','Europe (Paris)','Europe (Milan)','Europe (Espagne)','Europe (Stockholm)','Europe (Francfort)','Europe (Zurich)','Israël (Tel Aviv)','Moyen-Orient (Bahreïn)','Moyen-Orient (Émirats arabes unis)','Amérique du Sud (Sao Paulo)'];
  function renderDefenderSetup(){return `${crumb([{text:'Accueil',route:'entra/home'},{text:'Sécurité | Centre de sécurité',route:'entra/security-center'}])}<div class="defender-setup-heading">${actionBtn('×','goto','entra/security-center','btn icon-only','Fermer')}</div><div class="entra-info">Vous consultez peut-être des informations limitées. Pour obtenir une visibilité à l’échelle du locataire, cliquez ici</div><section class="defender-setup"><h1>Connecter vos environnements à Defender pour le cloud</h1><p>Protégez les applications natives Cloud, du code à l’exécution.. Terminez l’intégration de vos charges de travail Azure et protégez d’autres environnements cloud.</p><div class="defender-setup-cards"><article><img src="assets/m365/azure.svg" alt=""><h2>Microsoft Azure</h2><p>0 intégré</p><p>Tous les abonnements éligibles sont intégrés</p></article><article><strong class="defender-cloud-logo">aws</strong><h2>Amazon Web Services</h2><p>0 intégré</p>${actionBtn('Intégrer &gt;','open-modal','defender-aws','btn-link')}</article><article><strong class="defender-cloud-logo">G</strong><h2>Google Cloud Platform</h2><p>0 intégré</p>${actionBtn('Intégrer &gt;','open-modal','defender-gcp','btn-link')}</article><article><h2>Environnements supplémentaires</h2><button class="btn-link" disabled>Explorer les environnements &gt;</button></article></div><h2>Étapes suivantes pour démarrer</h2><div class="defender-setup-cards">${[['Configurer le contact de sécurité pour les alertes','Recevez des notifications par e-mail pour les alertes importantes et les chemins d’attaque potentiels dans votre environnement.'],['Configurer les stratégies de sécurité','Attribuez facilement des normes de conformité ou créez des stratégies de sécurité personnalisées pour renforcer votre environnement.'],['Explorer les rapports intégrés','Accédez aux rapports et personnalisez-les dans les classeurs pour obtenir des insights à partir de vos données de sécurité.']].map(([name,desc])=>`<article><h2>${esc(name)}</h2><p>${esc(desc)}</p>${name==='Explorer les rapports intégrés'?actionBtn('Voir les classeurs','goto','entra/defender-workbooks','btn-link'):'<button class="btn-link" disabled>En savoir plus</button>'}</article>`).join('')}</div></section>`;}
  const defenderWorkbookCatalog=[['Defender pour le cloud',['Degré de sécurisation dans le temps','Conformité au fil du temps',"Résultats de l’évaluation des vulnérabilités",'Alertes actives','Mises à jour système','Estimation des coûts','Gouvernance','Sécurité DevOps','API Sécurité','Gestion des autorisations (CIEM)','Serveurs SQL sur l’assistance machines AMA']],['Communauté',['Chemins d’attaques','Recommandations actives','Vulnérabilité log4j','Couverture','Tableau de bord ransomware','Sécurité des conteneurs','CSPM Defender']]];
  function renderDefenderWorkbooks(){
    const detail=ui.defenderWorkbookDetail,tab=ui.defenderWorkbookTab||'all',q=normal(ui.search||''),crumbs=crumb([{text:'Accueil',route:'entra/home'},{text:'Connecter vos environnements',route:'entra/defender-setup'},{text:'Microsoft Defender pour le cloud'}]);
    if(detail==='alerts')return `${crumbs}<h1>Microsoft Defender pour le cloud | Alertes actives</h1><div class="toolbar entra-command">${actionBtn('Classeurs','defender-workbook-back')} <button class="btn" disabled>Modifier</button><button class="btn" disabled>Enregistrer</button>${actionBtn('Actualiser','refresh')}</div><h2>Alertes actives</h2><div class="sub-tabs"><button class="tab ${ui.defenderWorkbookMap?'':'active'}" data-action="defender-workbook-mode" data-arg="list">Mode Liste</button><button class="tab ${ui.defenderWorkbookMap?'active':''}" data-action="defender-workbook-mode" data-arg="map">Vue cartographique</button></div><div class="entra-info">La requête n’a retourné aucun résultat.</div><p>Alertes actives a rencontré une erreur.</p>`;
    const descriptions=['Suivre les scores de vos abonnements et les changements de recommandations pour vos ressources','Effectuer le suivi de vos changements de conformité et de normes au fil du temps pour vos ressources','Voir les résultats de l’analyse des vulnérabilités de vos ressources Azure','Afficher les alertes de sécurité actives de vos ressources Azure','Voir les mises à jour système manquantes par ressource, système d’exploitation, gravité, etc.','Estimation du coût des plans Defender pour le cloud','Visibilité complète des règles de gouvernance et état actuel des évaluations gérées par les règles de gouvernance','Obtenez une visibilité et des insights sur votre posture de sécurité DevOps','Obtenir une visibilité et des insights sur la posture de sécurité de votre API et les détections de menaces','Bénéficiez d’une vue d’ensemble unique des fonctionnalités de gestion des autorisations dans Microsoft Defender pour le cloud','Suivez l’état de l’approvisionnement automatique de Defender pour SQL AMA','Suivre vos chemins d’attaques au fil du temps','Obtenir des insights sur les recommandations actives par abonnement Azure, compte AWS et projet GCP','Rechercher les machines et conteneurs à risque en cas de vulnérabilité Log4j','Afficher l’état du plan Defender pour le cloud par abonnement Azure, comptes AWS et projets GCP','Recommandations mappées avec MITRE ATT&CK Framework','Fournit un mappage de sécurité pour le plan Microsoft Defender pour les conteneurs en fonction de la télémétrie des ressources','Bénéficiez d’une visibilité et d’insights sur votre posture de sécurité cloud'];
    const groups=defenderWorkbookCatalog.map(([name,items],group)=>[name,items.map((item,index)=>({name:item,description:descriptions[index+(group?11:0)]})).filter(item=>normal(name+' '+item.name).includes(q))]);
    const card=item=>`<button class="defender-workbook-card" data-action="defender-workbook-open" data-arg="alerts" ${item.name==='Alertes actives'?'':'disabled title="Modèle non encore disponible dans le laboratoire"'}><span class="defender-workbook-icon" aria-hidden="true">▧</span><span><span>${esc(item.name)}</span><small>${esc(item.description)}</small></span></button>`;
    const section=([name,items],index)=>{if(!items.length)return '';const key=String(index),open=!(ui.defenderWorkbookCollapsed||[]).includes(key);return `<section class="defender-workbook-section"><button class="defender-workbook-group" data-action="defender-workbook-group" data-arg="${key}" aria-expanded="${open}">${open?'⌄':'›'} &nbsp; ${esc(name)} (${items.length})</button>${!open?'':tab==='public'?`<table class="defender-workbook-table"><tbody>${items.map(item=>`<tr><td><span class="defender-workbook-icon" aria-hidden="true">▧</span></td><td>${item.name==='Alertes actives'?actionBtn(esc(item.name),'defender-workbook-open','alerts','btn-link'):`<button class="btn-link" disabled title="Modèle non encore disponible dans le laboratoire">${esc(item.name)}</button>`}</td><td>${esc(name)}</td><td>${esc(item.description)}</td></tr>`).join('')}</tbody></table>`:`<div class="defender-workbook-grid">${items.map(card).join('')}</div>`}</section>`;};
    return `${crumbs}<h1>Microsoft Defender pour le cloud | Galerie</h1><div class="toolbar entra-command"><button class="btn" disabled>Nouveau ⌄</button>${actionBtn('Actualiser','refresh')}<button class="btn" disabled>Commentaires</button><a href="https://aka.ms/WorkbookPreviewDocs" target="_blank" rel="noopener noreferrer">Aide</a></div><div class="entra-info">Bienvenue dans la préversion du classeur ! <a href="https://aka.ms/WorkbookPreviewDocs" target="_blank" rel="noopener noreferrer">Que sont les nouveautés de la préversion ?</a></div><div class="toolbar">${listSearch('Filtrer par nom ou catégorie')}<button class="btn" disabled>Abonnement : Abonnement fictif</button><button class="btn" disabled>Groupes de ressources : Tous</button><button class="btn" disabled>Balises : 0 sélectionné(s)</button></div><div class="sub-tabs" role="tablist">${[['all','Tous'],['workbooks','Classeurs (0)'],['public','Modèles publics (18)'],['mine','Mes modèles (0)']].map(([key,label])=>`<button role="tab" aria-selected="${tab===key}" class="tab ${tab===key?'active':''}" data-action="defender-workbook-tab" data-arg="${key}">${label}</button>`).join('')}</div>${tab==='workbooks'||tab==='mine'?'<p>Aucun résultat.</p>':`${tab==='all'&&!q?section(['Démarrage rapide',[{name:'Vide',description:'Classeur complètement vide'},{name:'Tableau de bord',description:'Un tableau de bord vide'}]],2):''}${tab==='public'?'<table class="defender-workbook-table defender-workbook-header"><thead><tr><th></th><th>Nom du modèle</th><th>Catégorie</th><th>Description</th></tr></thead></table>':''}${groups.map(section).join('')}`}`;
  }
  const securityDiagnosticTopics=[
    ['Clés de sécurité FIDO2','Découvrez comment configurer des clés de sécurité Azure FIDO 2.'],
    ['Paramètres de sécurité par défaut','Découvrez les paramètres de sécurité par défaut dans Microsoft Entra ID.'],
    ['Problèmes liés aux groupes de sécurité','Découvrez comment résoudre des problèmes liés aux groupes de sécurité.'],
    ['Rapports de sécurité','Découvrez les rapports de sécurité (utilisateurs avec indicateur de risque, connexion risquée).'],
    ['Résoudre des problèmes liés aux stratégies d’accès Azure Key Vault et RBAC Azure','Découvrez comment résoudre des problèmes liés aux stratégies d’accès Azure Key Vault et RBAC Azure.']
  ];
  function securityDiagnosticGuide(i){
    const external=(text,url)=>`<a href="${attr(url)}" target="_blank" rel="noopener noreferrer">${esc(text)}</a>`;
    if(i===0)return `<h3>Clés de sécurité Fido2 – Mon problème n’est pas répertorié</h3><h4>Découvrez comment configurer des clés de sécurité Azure FIDO 2</h4><p>Pour configurer les clés de sécurité Azure FIDO 2, procédez comme suit.</p><p>Vérifiez d'abord les conditions préalables, comme indiqué ci-dessous. Ensuite, configurez la clé de sécurité.</p><h5>Prérequis importants</h5><ul><li>${external('Activer la connexion par clé FIDO 2','https://docs.microsoft.com/azure/active-directory/authentication/howto-authentication-passwordless-security-key')}.</li><li>${external('Vérifier que votre clé FIDO 2 répond aux exigences de Microsoft','https://docs.microsoft.com/azure/active-directory/authentication/concept-authentication-passwordless#fido2-security-keys')}</li><li>Pour la jonction hybride, veillez à exécuter Windows 10 version 2004 ou une version plus récente.</li><li>Pour les dispositifs de jonction Microsoft Entra (Azure Active Directory), vérifiez d'abord que vous exécutez Windows 10 version 1809 ou une version plus récente.</li></ul><h5>Configurer une clé de sécurité</h5><ul><li>${external('Configurer une clé de sécurité pour votre compte','https://docs.microsoft.com/azure/active-directory/user-help/security-info-setup-security-key')}</li></ul><h5>Problèmes connus</h5><ul><li>${external('Problèmes connus','https://docs.microsoft.com/azure/active-directory/authentication/howto-authentication-passwordless-security-key#known-issues')}</li></ul><h5>Ressources</h5><ul><li>${external('Apprenez-en davantage sur la technologie FIDO 2 et son implémentation dans Windows','https://techcommunity.microsoft.com/t5/identity-standards-blog/all-about-fido2-ctap2-and-webauthn/ba-p/288910')}</li></ul><h5>Résultats pertinents à partir du web</h5>`;
    if(i===1)return `<h3>Paramètres de sécurité par défaut</h3><h4>Découvrez les paramètres de sécurité par défaut dans Microsoft Entra ID</h4><p>Les paramètres de sécurité par défaut proposent une protection de base des identités sans licence Entra ID P1 ou P2 : inscription à l’authentification multifacteur, protection des administrateurs et des activités privilégiées, et blocage de l’authentification héritée.</p><p>${external('Plus d’informations sur le nom Microsoft Entra ID','https://learn.microsoft.com/azure/active-directory/fundamentals/new-name')}</p><h4>La sécurité par défaut sera activée dans votre organisation dans X jours</h4><p>Les administrateurs des locataires éligibles peuvent être informés du déploiement.</p><p>${external('Élévation du niveau de sécurité de base pour toutes les organisations','https://techcommunity.microsoft.com/t5/microsoft-entra-azure-ad-blog/raising-the-baseline-security-for-all-organizations-in-the-world/ba-p/3299048')}</p><h4>Raisons pour lesquelles vous pourriez vouloir désactiver la sécurité par défaut (non recommandé)</h4><ul><li>Utilisation de stratégies d’accès conditionnel avec une licence adaptée.</li><li>Présence d’applications utilisant des protocoles d’authentification hérités.</li><li>Besoin d’exclure des utilisateurs ou de choisir d’autres méthodes d’authentification.</li></ul><h4>Désactivation des paramètres de sécurité par défaut</h4><p>Dans la vue d’ensemble de l’identité, ouvrez Propriétés puis Gérer les paramètres de sécurité par défaut.</p><h4>Paramètres de sécurité par défaut et accès conditionnel</h4><p>La licence et les besoins de l’organisation déterminent le choix des protections.</p><h4>Activer les paramètres de sécurité par défaut</h4><p>${external('Activer les paramètres de sécurité par défaut dans votre répertoire','https://docs.microsoft.com/azure/active-directory/fundamentals/concept-fundamentals-security-defaults#enabling-security-defaults')}</p><h4>Créer une stratégie d’accès conditionnel similaire aux paramètres de sécurité par défaut</h4><ul><li>${external('Exiger l’inscription à l’authentification multifacteur','https://docs.microsoft.com/azure/active-directory/conditional-access/howto-conditional-access-policy-registration')}</li><li>${external('Exiger MFA pour tous les utilisateurs','https://docs.microsoft.com/azure/active-directory/conditional-access/howto-conditional-access-policy-all-users-mfa')}</li><li>${external('Exiger MFA pour les administrateurs','https://docs.microsoft.com/azure/active-directory/conditional-access/howto-conditional-access-policy-admin-mfa')}</li><li>${external('Bloquer l’authentification héritée','https://docs.microsoft.com/azure/active-directory/conditional-access/howto-conditional-access-policy-block-legacy')}</li><li>${external('Protéger les activités privilégiées','https://docs.microsoft.com/azure/active-directory/conditional-access/howto-conditional-access-policy-azure-management')}</li></ul><h4>Questions fréquentes (FAQ) : Paramètres de sécurité par défaut</h4><p><strong>Peut-on exclure un utilisateur ou un groupe ?</strong><br>Les paramètres de sécurité par défaut ne proposent pas d’exclusion individuelle ; l’accès conditionnel permet un ciblage plus précis.</p><p><strong>Peut-on activer un mot de passe d’application ?</strong><br>Les mots de passe d’application ne sont pas disponibles avec les paramètres de sécurité par défaut.</p><p><strong>La MFA est-elle demandée à chaque connexion ?</strong><br>La demande dépend notamment du contexte de connexion.</p><h4>Ressources</h4><ul><li>${external('Paramètres de sécurité par défaut dans Microsoft Entra ID','https://docs.microsoft.com/azure/active-directory/fundamentals/concept-fundamentals-security-defaults')}</li><li>${external('Paramètres de sécurité par défaut et authentification multifacteur','https://docs.microsoft.com/microsoft-365/business-premium/m365bp-conditional-access?view=o365-worldwide')}</li><li>${external('Configurer une application ou un appareil multifonction pour envoyer un e-mail','https://docs.microsoft.com/exchange/mail-flow-best-practices/how-to-set-up-a-multifunction-device-or-application-to-send-email-using-microsoft-365-or-office-365')}</li></ul><h4>Résultats pertinents à partir du web</h4>`;
    if(i===2)return `<h3>Problème lié aux groupes de sécurité</h3><h4>Résoudre les problèmes liés aux groupes de sécurité</h4><p>Si vous obtenez l’erreur réseau AADDS104, passez en revue les étapes de dépannage ci-dessous.</p><h5>Étapes de dépannage</h5><p>Des règles de groupe de sécurité réseau (NSG) invalides sont la cause la plus courante d’erreurs réseau pour Microsoft Entra Domain Services. Le groupe de sécurité réseau pour le réseau virtuel doit autoriser l’accès à des ports et protocoles spécifiques. Si ces ports sont bloqués, la plateforme Azure ne peut pas surveiller ou mettre à jour le domaine managé. La synchronisation entre le répertoire Microsoft Entra et Microsoft Entra Domain Services est également impactée. Veillez à garder ces ports par défaut ouverts pour éviter les interruptions de service.</p><p>Pour comprendre et résoudre les alertes courantes découlant de problèmes de configuration des groupes de sécurité réseau, consultez ${external('Ajouter et vérifier des groupes de sécurité','https://docs.microsoft.com/azure/active-directory-domain-services/alert-nsg#verify-and-edit-existing-security-rules')}.</p>`;
    if(i===3)return `<h3>Security Reports (Users Flagged at Risk, Risky Sign-In)</h3><h4>Découvrez les rapports de sécurité (utilisateurs associés à un indicateur de risque, connexion à risque)</h4><p><strong>AVIS : Azure Active Directory (Azure AD) est renommé en Microsoft Entra ID. Aucune action de la part du client n'est requise</strong>. Les capacités, les licences, la tarification, les contrats de niveau de service, les API, l’authentification et l’expérience des développeurs ne sont pas affectés. ${external('Plus d’informations','https://learn.microsoft.com/azure/active-directory/fundamentals/new-name')}</p><p>Utilisez les ressources suivantes pour en savoir plus sur les rapports de sécurité.</p><h5>Ressources</h5><ul><li>${external('Rapport de sécurité des utilisateurs associés à un indicateur de risque','https://docs.microsoft.com/azure/active-directory/reports-monitoring/concept-user-at-risk')}</li><li>${external('Rapport de connexion à risque dans le centre d’administration Microsoft Entra','https://docs.microsoft.com/azure/active-directory/reports-monitoring/concept-risky-sign-ins')}</li><li>${external('Événements à risque dans Microsoft Entra','https://docs.microsoft.com/azure/active-directory/reports-monitoring/concept-risk-events')}</li></ul><h5>Résultats pertinents à partir du web</h5>`;
    return `<h3>Résoudre les problèmes liés aux stratégies d’accès Azure Key Vault et à RBAC Azure</h3><h4>Découvrez la gestion de la stratégie de coffre de clés</h4><p>Azure Key Vault propose le contrôle d’accès en fonction du rôle Azure et le modèle hérité de stratégie d’accès. Vérifiez le modèle sélectionné, les attributions de rôles et les autorisations des principaux concernés.</p><h4>Gérer les stratégies d’accès</h4><p>Dans le coffre de clés, ouvrez les stratégies d’accès et choisissez les autorisations et principaux adaptés au scénario.</p><h4>Modifier une stratégie existante</h4><p>Recherchez le principal dans la liste des stratégies et examinez les autorisations attribuées.</p><h4>Supprimer une stratégie existante</h4><p>Identifiez la stratégie concernée dans le coffre avant de la retirer.</p><h4>Problèmes courants</h4><p><strong>Un groupe a reçu l’accès mais ses membres ne peuvent pas effectuer une opération.</strong><br>La propagation des autorisations peut prendre du temps ; vérifiez l’attribution et son étendue.</p><p><strong>Une opération précédemment autorisée ne fonctionne plus.</strong><br>Vérifiez le modèle d’accès du coffre et les autorisations ou rôles du principal.</p><p><strong>Le principal de service est introuvable dans IAM.</strong><br>Vérifiez son attribution de rôle et son étendue dans Microsoft Entra ID.</p><p><strong>La stratégie récemment ajoutée n’apparaît pas.</strong><br>Vérifiez la pagination et l’affichage avant de conclure à une erreur.</p><h4>Ressources</h4><ul><li>${external('Groupes de sécurité Microsoft Entra','https://docs.microsoft.com/azure/active-directory/fundamentals/active-directory-groups-create-azure-portal')}</li><li>${external('Présentation de l’authentification Key Vault','https://docs.microsoft.com/azure/key-vault/general/authentication')}</li><li>${external('Présentation du modèle d’accès à Key Vault','https://docs.microsoft.com/azure/key-vault/general/secure-your-key-vault')}</li></ul>`;
  }
  function renderSecurityDiagnostics(){
    const mode=ui.securityDiagnosticMode||'home';
    if(mode==='signin')return renderUserDiagnostics(null);
    const toolbar=`<div class="toolbar entra-command">${mode==='home'?'<button class="btn" disabled>Recommencer</button>':actionBtn('Recommencer','security-diagnostic-mode','home')}${actionBtn('Support en libre-service','goto','entra/support')}${actionBtn('Nouvelle demande de support','goto','entra/support')}</div>`;
    if(mode.startsWith('topic:')){const i=Number(mode.slice(6)),topic=securityDiagnosticTopics[i];if(!topic)return toolbar;return `${toolbar}<h2>Résolution du problème : ${esc(topic[0])}</h2><p>${esc(topic[1])}</p><details open><summary>Conseils sur la solution</summary>${securityDiagnosticGuide(i)}<p>Ces informations vous ont-elle été utiles ?</p><fieldset><legend class="sr-only">Ces informations vous ont-elle été utiles ?</legend><label><input type="radio" name="security-diagnostic-feedback" value="yes"> Oui</label> <label><input type="radio" name="security-diagnostic-feedback" value="no"> Non</label></fieldset></details>${actionBtn('Précédent','security-diagnostic-mode','home')}`;}
    const query=normal(ui.securityDiagnosticQuery||''),topics=securityDiagnosticTopics.map(([name,description],i)=>({name,description,i})).filter(x=>normal(x.name+' '+x.description).includes(query));
    return `${toolbar}<div class="diagnostic-notice"><strong>Tout nouveau !</strong> Essayez notre assistance en libre-service alimentée par l’IA pour obtenir une aide instantanée avec les problèmes de Microsoft Entra. ${actionBtn('Cliquez ici pour démarrer.','goto','entra/support','btn-link')}</div><h3>Que pouvons-nous faire pour vous ?</h3><form id="form-security-diagnostic-search"><input type="search" name="query" data-security-diagnostic-search placeholder="Décrivez brièvement le problème" aria-label="Décrivez brièvement le problème" value="${attr(ui.securityDiagnosticQuery||'')}"></form><div class="diagnostic-notice">Dans le portail Microsoft, la recherche est traitée par Bing. Dans ce laboratoire, la recherche reste locale. <a href="https://www.microsoft.com/licensing/terms/productoffering/microsoftsearchinbing/EAEAS" target="_blank" rel="noopener noreferrer">Voir les Conditions générales du produit Bing</a></div>${query?`<h3>Résultats de la recherche</h3><h4>Résultats pertinents sur le web</h4><p>La recherche Web n’est pas connectée dans ce laboratoire.</p>`:`<h3>Utilitaires de résolution des problèmes</h3><p>Sélectionnez Dépanner pour le problème que vous essayez de résoudre.</p><div class="diagnostic-grid"><article class="diagnostic-card"><h3>Diagnostic de connexion</h3><p>Utilisez le diagnostic pour analyser ce qui s’est passé lors d’une connexion et connaître les actions à effectuer pour résoudre les problèmes.</p>${actionBtn('Résoudre des problèmes','security-diagnostic-mode','signin','btn-link')}</article></div>`}${topics.length?`<h3>Problèmes courants</h3><div class="diagnostic-grid">${topics.map(t=>`<article class="diagnostic-card"><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p>${actionBtn('Afficher les conseils','security-diagnostic-mode','topic:'+t.i,'btn-link','Afficher les conseils : « '+t.name+' »')}</article>`).join('')}</div>`:''}`;
  }
  function renderSecureScore(start=false,agents=false,center=false,pki=false){const riskReport={'entra/security-risk-users':{view:'users',key:'risk-users',title:'Utilisateurs à risque',y:642},'entra/security-risk-signins':{view:'signins',key:'risk-signins',title:'Connexions à risque',y:722},'entra/security-risk-workloads':{view:'workloads',key:'risk-workloads',title:'Identités de charge de travail à risque',y:674}}[ui.route],diagnostic=ui.route==='entra/security-diagnostics',navIcons={'security-getting-started':103,'diagnostics':136,'conditional':224,'identity-protection':256,'security-center':288,'secure-score':361,'locations':394,'auth':426,'mfa-blocked':457,'certificates':489,'security-pki':537,'risk-agents':610,'risk-users':642,'risk-workloads':674,'risk-signins':722},sections=[['',[['Prise en main','security-getting-started','info'],['Diagnostiquer et résoudre les problèmes','diagnostics','settings']]],['Protéger',[['Accès conditionnel','conditional','shield'],['Protection d’ID','identity-protection','shield'],['Centre de sécurité','security-center','shield']]],['Gérer',[["Score d’identité sécurisée",'secure-score','shield'],['Emplacements nommés','locations','globe'],["Méthodes d’authentification",'auth','key'],['Authentification multifacteur','mfa-blocked','key'],['Autorités de certification (classiques)','certificates','document'],['Infrastructure de clé publique','security-pki','document']]],['Rapport',[['Agents à risque','risk-agents','user'],['Utilisateurs à risque','risk-users','user'],['Identités de charge de travail à risque','risk-workloads','apps'],['Connexions à risque','risk-signins','clock']]],['Aide',[['Support + Résolution des problèmes','support','help']]]],query=normal(ui.secureNavSearch||''),matchesNav=([label,key])=>normal(label+' '+(['auth','mfa-blocked'].includes(key)?'certificat':'')).includes(query),matchCount=sections.reduce((count,[,entries])=>count+entries.filter(matchesNav).length,0);return `${crumb([{text:'Accueil',route:'entra/home'},{text:'Sécurité'},{text:riskReport?riskReport.title:diagnostic?'Diagnostiquer et résoudre les problèmes | Diagnostiquer et résoudre les problèmes':pki?'Infrastructure de clé publique':center?'Centre de sécurité':agents?'Agents à risque':start?'Prise en main':'Score d’identité sécurisée'}])}<div class="entra-blade-heading security-page-heading">${riskReport?`<span class="security-reference-risk-heading" style="--risk-icon-y:-${riskReport.y*1.75}px" aria-hidden="true"></span>`:diagnostic?'<span class="security-reference-heading-icon" aria-hidden="true"></span>':start?`<svg class="security-page-icon" viewBox="0 0 32 32" aria-hidden="true"><defs><linearGradient id="security-page-shield" x2="0" y2="1"><stop stop-color="#5bb8ed"/><stop offset="1" stop-color="#0067c5"/></linearGradient></defs><path fill="url(#security-page-shield)" d="M16 2 28 6v8c0 8-4.5 12.5-12 16C8.5 26.5 4 22 4 14V6z"/></svg>`:!pki&&!center&&!agents?'<span class="security-reference-trophy security-reference-trophy-heading" aria-hidden="true"></span>':`<img class="security-page-icon" src="assets/m365/${pki?'entra-pki.svg':center?'entra-security-center.svg':'entra-identity-protection.svg'}" alt="">`}<h1><strong>Sécurité</strong> | ${riskReport?riskReport.title:diagnostic?'Diagnostiquer et résoudre les problèmes | Diagnostiquer et résoudre les problèmes':pki?'Infrastructure de clé publique':center?'Centre de sécurité':agents?'Agents à risque':start?'Prise en main':'Score d’identité sécurisée'}</h1></div><div class="entra-blade-layout security-layout ${ui.secureNavCollapsed?'is-nav-collapsed':''}"><nav class="entra-blade-nav secure-score-nav" aria-label="Menu Sécurité"><button type="button" class="security-nav-toggle" data-action="secure-nav-toggle" aria-label="${ui.secureNavCollapsed?'Afficher le menu pour Sécurité':'Masquer le menu pour Sécurité'}" aria-expanded="${!ui.secureNavCollapsed}">${ui.secureNavCollapsed?'»':'«'}</button><div class="security-nav-search"><label class="search-input">${icon('search')}<input type="search" data-secure-nav-search placeholder="Rechercher" aria-label="Rechercher dans le menu Sécurité" value="${attr(ui.secureNavSearch||'')}"></label>${ui.secureNavSearch?`<button type="button" class="security-nav-clear" data-action="secure-nav-clear" aria-label="Effacer la recherche">×</button>`:''}</div>${query?`<span class="sr-only" role="status">${matchCount} résultat${matchCount===1?'':'s'} pour « ${esc(ui.secureNavSearch)} »</span>`:''}${sections.map(([heading,entries])=>{const filtered=entries.filter(matchesNav);return filtered.length?`${heading?`<strong>${esc(heading)}</strong>`:''}${filtered.map(([label,key,ico])=>`<button class="entra-blade-link ${key===(riskReport?riskReport.key:diagnostic?'diagnostics':pki?'security-pki':center?'security-center':agents?'risk-agents':start?'security-getting-started':'secure-score')?'active':''}" data-action="secure-score-nav" data-arg="${attr(key)}" ${key?'':'disabled title="Cette page n’est pas encore disponible dans le laboratoire"'}>${navIcons[key]!=null?`<span class="security-reference-icon" style="--security-icon-y:-${navIcons[key]}px" aria-hidden="true"></span>`:icon(ico)}${esc(label)}</button>`).join('')}`:'';}).join('')}</nav><div class="entra-blade-content">${riskReport?(riskReport.view==='workloads'?renderSecurityRiskWorkloads():renderIdentityProtection(riskReport.view)):diagnostic?renderSecurityDiagnostics():pki?renderEntraPki():center?renderEntraSecurityCenter():agents?renderRiskyAgentsEmpty():start?renderSecurityGettingStarted():renderOverviewSuggestions()}</div></div>`;}
  function temporaryPassWindow(m){const start=Date.parse(m.startAt||m.createdAt||''),minutes=Number(m.lifetimeMinutes??(Number(m.hours)*60));return {start,end:Number.isFinite(start)&&Number.isFinite(minutes)&&minutes>0?start+minutes*60000:NaN};}
  function authMethodUsable(m){if(m.usable===false||m.oneTime&&m.usedAt)return false;if(m.kind==='tap'){const {start,end}=temporaryPassWindow(m),now=Date.now();if(Number.isFinite(start)&&now<start||Number.isFinite(end)&&now>=end)return false;}return true;}
  function authMethodDetail(m){if(m.kind!=='tap')return m.detail||'—';const {start,end}=temporaryPassWindow(m),now=Date.now();if(m.oneTime&&m.usedAt)return 'Déjà utilisé';if(Number.isFinite(start)&&now<start)return 'Valide à partir du '+new Date(start).toLocaleString('fr-FR');if(Number.isFinite(end)&&now>=end)return 'Expiré le '+new Date(end).toLocaleString('fr-FR');return Number.isFinite(end)?'Expire le '+new Date(end).toLocaleString('fr-FR'):m.detail||'—';}
  function userAuthMethods(u){if(Array.isArray(u.authMethods))return u.authMethods;return u.mfa&&u.mfa!=='Not registered'?[{id:'legacy',type:u.mfa,detail:'',usable:true}]:[];}
  const profileEditTabs=[['all','Tout'],['identity','Identité'],['work','Informations de travail'],['contact','Informations de contact'],['parent','Contrôle parental'],['settings','Paramètres'],['local','Localement']];
  const userDiagnosticTopics=[['Attribution d’utilisateurs et de groupes dans l’accès conditionnel','Comment affecter des utilisateurs et des groupes à la stratégie d’accès conditionnel.'],['Gérer les rôles, utilisateurs, groupes et invités des révisions d’accès','Découvrez comment gérer les rôles, les utilisateurs, les groupes et les invités des révisions d’accès.'],['Mise à jour des utilisateurs','Comment mettre à jour les propriétés utilisateur pour les utilisateurs de Microsoft Entra ID.'],['Problèmes liés aux mappages d’attributs lors de l’approvisionnement d’utilisateurs dans une application','Comment résoudre les problèmes liés aux mappages d’attributs lors de l’approvisionnement d’utilisateurs dans une application.'],['Problèmes lors de la configuration et de l’approvisionnement des utilisateurs sur une application','Comment résoudre les problèmes lors de la configuration et de l’approvisionnement des utilisateurs dans une application.'],['Rapports de sécurité (utilisateurs avec indicateur de risque, connexion risquée)','En savoir plus sur les rapports de sécurité.'],['Résoudre des problèmes Microsoft Entra Connect courants de synchronisation des utilisateurs et des groupes','Comment résoudre les problèmes courants liés aux utilisateurs et à la synchronisation de groupe de Microsoft Entra Connect.'],['Résoudre les problèmes liés aux utilisateurs à risque','Comment résoudre le problème des utilisateurs à risque.']];
  function diagnosticEvents(user,criteria={}){const target=user||(criteria.userId?db.users.find(x=>x.id===criteria.userId):null),now=Date.now(),start=criteria.start??now-48*3600000,end=criteria.end??now;return (Array.isArray(db.signInEvents)?db.signInEvents:[]).filter(x=>{const time=Date.parse(x.date);return Number.isFinite(time)&&time>=start&&time<=end&&(!target||(x.userId?x.userId===target.id:normal(x.upn||'')===normal(target.upn||'')))&&(!criteria.flagged||x.flagged===true)&&(!criteria.application||normal(x.application||'').includes(normal(criteria.application)))&&(!criteria.requestId||[x.requestId,x.correlationId].some(v=>normal(v||'')===normal(criteria.requestId)));}).sort((a,b)=>Date.parse(b.date)-Date.parse(a.date));}
  function diagnosticEventTable(items,empty){return table(['Date','Utilisateur','Application','État','ID de demande'],items.map(x=>`<tr><td>${actionBtn(esc(x.date||'—'),'signin-detail',String((db.signInEvents||[]).indexOf(x)),'btn-link')}</td><td>${esc(x.user||x.upn||'—')}</td><td>${esc(x.application||'—')}</td><td>${esc(x.status||'—')}</td><td>${esc(x.requestId||'—')}</td></tr>`),empty,'900px');}
  function diagnosticUtcTime(date){const h=date.getUTCHours(),minutes=String(date.getUTCMinutes()).padStart(2,'0');return `${h%12||12}:${minutes} ${h<12?'AM':'PM'}`;}
  function diagnosticUtcTimestamp(date,time){const match=/^(0?[1-9]|1[0-2]):([0-5][0-9])\s*([ap]m)$/i.exec(time.trim());if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!match)return NaN;const hour=Number(match[1])%12+(match[3].toUpperCase()==='PM'?12:0),iso=`${date}T${String(hour).padStart(2,'0')}:${match[2]}:00Z`,parsed=Date.parse(iso);return Number.isFinite(parsed)&&new Date(parsed).toISOString()===iso.replace('Z','.000Z')?parsed:NaN;}
  function diagnosticInfo(text){return `<details class="diagnostic-info"><summary aria-label="Information">ⓘ</summary><span role="tooltip">${esc(text)}</span></details>`;}
