    groups:'<circle cx="12" cy="6" r="4" fill="#31c0df"/><path d="M5 20v-3a7 7 0 0 1 14 0v3z" fill="#009bc6"/><circle cx="4" cy="10" r="2.5" fill="#23abd1"/><circle cx="20" cy="10" r="2.5" fill="#168dd2"/><path d="M1 19v-2a4 4 0 0 1 5-4M23 19v-2a4 4 0 0 0-5-4" fill="#038fc0"/>',
    properties:'<path d="M4 3h3v18H4zm6 0h3v18h-3zm6 0h3v18h-3z" fill="#149fe4"/><path d="M4 7h3v3H4zm6 5h3v3h-3zm6-7h3v3h-3z" fill="#005bbd"/>',
