  function groupOrganizationalContacts(){ensureExchange();return db.exchange.contacts.filter(c=>!c.userId&&c.kind!=='Utilisateur de courrier');}
  function entraGroupMemberRecords(group,transitive=false){ensureEnterprise();const result=[],seen=new Set(),visited=new Set([group.id]);function add(current){for(const id of effectiveGroupIds(current)){if(seen.has(id)||id===group.id)continue;seen.add(id);const user=db.users.find(x=>x.id===id),nested=groupOf(id),device=(db.devices||[]).find(x=>x.id===id),service=db.servicePrincipals.find(x=>x.id===id),contact=groupOrganizationalContacts().find(x=>x.id===id),entity=user||nested||device||service||contact;if(!entity)continue;result.push({id,name:user?.displayName||nested?.name||device?.name||service?.name||contact?.name||id,type:user?'Utilisateur':nested?'Groupe':device?'Appareil':service?'Principal de service':'Contact',mail:user?.mail||user?.upn||nested?.mail||contact?.email||'',userType:user?(user.userType==='Guest'?'Invité':'Membre'):'',deviceId:device?.deviceId||'',direct:current.id===group.id,removable:current.id===group.id&&(group.members||[]).includes(id)&&group.membership==='Assigned',temporary:current.id===group.id&&!(group.members||[]).includes(id)});if(transitive&&nested&&!visited.has(id)){visited.add(id);add(nested);}}}add(group);return result;}
