  function entraRolesNav(active){const entries=[['Rôles Microsoft Entra ID','entra/roles','roles'],['Rôles unifiés','entra/unified-roles','roles'],['Unités administratives','entra/aus','units'],['Actions protégées','entra/protected-actions','protected'],['Diagnostiquer et résoudre les problèmes','entra/diagnostics','diagnostics'],['Révisions d’accès','entra/reviews','reviews'],['Journaux d’audit','entra/audit','audit'],['Résultats de l’opération en bloc','entra/monitoring-bulk','bulk'],['Support + Résolution des problèmes','entra/support','help']],navIcon=key=>key==='roles'?'<img class="entra-roles-nav-icon" src="assets/m365/entra-roles.svg" alt="">':key==='units'?'<img class="entra-roles-nav-icon" src="assets/m365/entra-administrative-units.svg" alt="">':key==='protected'?'<svg class="entra-roles-nav-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="9" cy="6" r="4" fill="#35c0df"/><path d="M2 19v-2a7 7 0 0 1 14 0v2z" fill="#0798c4"/><rect x="14" y="14" width="8" height="7" rx="1" fill="#ffc328"/><path d="M16 14v-2a2 2 0 0 1 4 0v2" fill="none" stroke="#d99500" stroke-width="1.5"/></svg>':entraGroupsNavIcon(key);return `<nav class="entra-blade-nav entra-roles-nav ${ui.entraRolesNavCollapsed?'is-collapsed':''}" aria-label="Menu Rôles et administrateurs"><button type="button" class="entra-roles-nav-toggle" data-action="entra-roles-nav-toggle" aria-label="${ui.entraRolesNavCollapsed?'Développer':'Masquer'} le menu Rôles et administrateurs" aria-expanded="${ui.entraRolesNavCollapsed?'false':'true'}">${ui.entraRolesNavCollapsed?'»':'«'}</button>${entries.map(([label,route,ico],i)=>`${i===5?'<strong>Activité</strong>':i===8?'<strong>Aide</strong>':''}<button class="entra-blade-link ${active===route?'active':''}" data-route="${route}">${navIcon(ico)}<span>${esc(label)}</span></button>`).join('')}</nav>`;}
  function entraRolesHeadingActions(){return `<div class="entra-home-actions-anchor entra-roles-heading-actions"><button type="button" class="entra-home-actions-toggle" data-action="entra-roles-heading-actions" aria-label="Autres actions de contenu" aria-haspopup="menu" aria-expanded="${!!ui.entraRolesHeadingActions}">···</button>${ui.entraRolesHeadingActions?`<div class="entra-home-actions-menu" role="menu" aria-label="Autres actions de contenu"><button role="menuitem" data-action="entra-roles-heading-copy">Copier le titre dans le Presse-papiers</button><button role="menuitem" data-action="entra-roles-heading-print">Imprimer le contenu</button><button role="menuitem" data-action="entra-roles-heading-fullscreen">Activer/désactiver le mode plein écran</button></div>`:''}</div>`;}
