  function currentUserHasDirectoryAction(permission){const user=db.users.find(u=>u.id==='u01')||db.users[0];if(!user)return false;const ids=[...db.roleAssignments.filter(a=>a.userId===user.id&&(!a.scope||a.scope==='tenant')).map(a=>a.roleId),...(db.groupRoleAssignments||[]).filter(a=>{const g=groupOf(a.groupId);return (!a.scope||a.scope==='tenant')&&g&&effectiveGroupIds(g).includes(user.id);}).map(a=>a.roleId)];return ids.some(id=>{const role=roleOf(id);return (role?.documentedActions||role?.permissions||[]).includes(permission);});}
