  function renderRolesFilterPopup(filters){const stage=ui.entraRolesFilterPanel;if(!stage)return '';if(stage==='field')return `<div class="entra-roles-filter-popup" role="menu" aria-label="Ajouter des filtres">${[['service','Service'],['type','Type'],['unit','Unité administrative'],['privileged','Privilégié']].map(([key,label])=>`<button type="button" role="menuitem" data-action="entra-roles-filter-field" data-arg="${key}">${esc(label)}</button>`).join('')}</div>`;const options=stage==='service'?Object.entries(roleServiceLabels):stage==='type'?[['Intégré','Intégré'],['Personnalisé','Personnalisé']]:stage==='privileged'?[['Oui','Oui'],['Non','Non']]:stage==='unit'?db.aus.map(a=>[a.id,a.name]):[];return `<div class="entra-roles-filter-popup" role="dialog" aria-label="Filtrer par ${attr(({service:'service',type:'type',unit:'unité administrative',privileged:'privilège'})[stage]||'valeur')}"><button type="button" class="entra-roles-filter-back" data-action="entra-roles-filter-field" data-arg="field">‹ Retour</button><form id="form-entra-roles-filter-inline"><fieldset><legend>${esc(({service:'Service',type:'Type',unit:'Unité administrative',privileged:'Privilégié'})[stage]||'Valeur')}</legend>${options.length?options.map(([value,label])=>`<label class="entra-roles-filter-choice"><input type="radio" name="value" value="${attr(value)}" ${filters[stage]===value?'checked':''} required> ${esc(label)}</label>`).join(''):'<p>Aucune valeur disponible.</p>'}</fieldset>${stage==='service'?'<p>La classification locale des rôles par service est partielle.</p>':''}<div class="form-error" id="form-error"></div><button type="submit" class="btn primary" ${options.length?'':'disabled'}>Appliquer</button></form></div>`;}
  function renderRoles(){
    markOnce('roles');const filters=ui.entraRolesFilters||{},sort=ui.entraRolesSort||{key:'name',desc:false},count=r=>db.roleAssignments.filter(a=>a.roleId===r.id).length+(db.groupRoleAssignments||[]).filter(a=>a.roleId===r.id).length+(db.agentRoleAssignments||[]).filter(a=>a.roleId===r.id).length+(db.servicePrincipalRoleAssignments||[]).filter(a=>a.roleId===r.id).length,sortValue=r=>sort.key==='count'?count(r):sort.key==='privileged'?(r.privileged===null?2:Number(r.privileged)):sort.key==='type'?(r.custom?'Personnalisé':'Intégré'):r.french;
    const currentUser=db.users.find(u=>u.id==='u01')||db.users[0],currentRoleIds=currentUser?[...new Set([...roleAssignmentsForUser(currentUser.id).map(a=>a.roleId),...(db.groupRoleAssignments||[]).filter(a=>{const group=groupOf(a.groupId);return group&&effectiveGroupIds(group).includes(currentUser.id);}).map(a=>a.roleId)].filter(id=>roleOf(id)))]:[],primaryRoleId=currentRoleIds.includes('global')?'global':currentRoleIds[0],otherRoleCount=Math.max(0,currentRoleIds.length-1),currentRoleSummary=(roleOf(primaryRoleId)?.french||'Aucun rôle')+(otherRoleCount?' et '+otherRoleCount+' autre'+(otherRoleCount>1?'s rôles':' rôle'):'');
    const roles=roleCatalog().filter(r=>(ui.tableFilter==='All'||(ui.tableFilter==='Privileged'?r.privileged===true:r.privileged===false))&&(!filters.privileged||r.privileged===(filters.privileged==='Oui'))&&(!filters.type||(filters.type==='Personnalisé')===!!r.custom)&&(!filters.category||r.category===filters.category)&&(!filters.service||(roleServiceNames[filters.service]||[]).includes(r.name))&&(!filters.unit||[db.roleAssignments,db.groupRoleAssignments||[],db.agentRoleAssignments||[],db.servicePrincipalRoleAssignments||[]].some(rows=>rows.some(a=>a.roleId===r.id&&a.scope==='au:'+filters.unit)))).sort((a,b)=>{const x=sortValue(a),y=sortValue(b),order=typeof x==='number'?x-y:String(x).localeCompare(String(y),'fr',{sensitivity:'base'});return (order||a.french.localeCompare(b.french,'fr',{sensitivity:'base'}))*(sort.desc?-1:1);});
    const rows=roles.map(r=>`<tr data-filter-row="${attr(normal(r.name+' '+r.french+' '+r.description))}"><td><input type="checkbox" data-row-check="${attr(r.id)}" ${ui.selected.includes(r.id)?'checked':''} aria-label="Sélectionner ${attr(r.french)}"></td><td>${link(r.french,'entra/role/'+r.id)}</td><td title="${attr(r.description)}">${esc(r.description)}</td><td>${r.privileged===true?marked('PRIVILÉGIÉ','info'):r.privileged===null?'<span class="muted">Non renseigné</span>':''}</td><td>${link(String(count(r)),'entra/role/'+r.id)}</td><td>${r.custom?'Personnalisé':'Intégré'}</td></tr>`);
    return `${crumb([{text:'Accueil',route:'entra/home'},{text:db.tenant.name,route:'entra/overview'}])}<div class="entra-blade-heading entra-roles-heading ${ui.entraRolesFullscreen?'is-fullscreen':''}"><img src="assets/m365/entra-roles.svg" alt=""><div><div class="entra-roles-title-line"><h1><strong>Rôles et administrateurs</strong> | Rôles Microsoft Entra ID</h1>${entraRolesHeadingActions()}</div><span>${esc(db.tenant.name)}</span></div><button class="entra-heading-close" data-route="entra/overview" aria-label="Fermer">${icon('close')}</button></div><div class="entra-blade-layout">${entraRolesNav('entra/roles')}<div class="entra-blade-content"><div class="toolbar entra-command"><button class="btn" data-action="entra-custom-role-new" ${(db.customRoles||[]).length>=100?'title="Limite de 100 rôles personnalisés atteinte"':''} ${['p1','p2'].includes(db.premium)&&canManageRoleDefinitions()&&(db.customRoles||[]).length<100?'':'disabled'}>${icon('plus')} Nouveau rôle personnalisé</button><button class="btn" data-action="entra-custom-role-delete" ${!['p1','p2'].includes(db.premium)||!canManageRoleDefinitions()||!ui.selected.length||ui.selected.some(id=>!roleOf(id)?.custom)?'disabled':''}>${icon('trash')} Supprimer le rôle personnalisé</button>${actionBtn(icon('download')+' Télécharger les attributions','export-roles')}<div class="entra-new-wrap entra-roles-more-anchor"><button class="btn" type="button" data-action="entra-roles-more" aria-label="Autres actions" aria-haspopup="menu" aria-expanded="${!!ui.entraRolesMore}">···</button>${ui.entraRolesMore?`<div class="entra-new-menu entra-roles-more-menu" role="menu"><button type="button" role="menuitem" data-action="entra-roles-refresh">${icon('refresh')} Actualiser</button></div>`:''}</div></div>${db.premium==='free'?'<div class="entra-info entra-roles-license"><svg class="entra-roles-license-icon" viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="8" fill="#0067c0"/><path d="M8 7v5M8 4v.5" stroke="#fff" stroke-width="1.6" stroke-linecap="round"/></svg><span>Pour créer des rôles personnalisés, votre organisation a besoin de Microsoft Entra ID Premium P1 ou P2. Démarrez une version d’évaluation gratuite.</span><button type="button" class="entra-roles-license-arrow" data-action="goto" data-arg="entra/licenses" aria-label="Afficher les licences Microsoft Entra">&#8594;</button></div>':''}${['p1','p2'].includes(db.premium)&&!canManageRoleDefinitions()?'<div class="entra-info">Le compte simulé ne peut pas gérer les rôles personnalisés.</div>':''}<p class="entra-roles-current">ⓘ <button type="button" class="entra-roles-current-link" data-action="entra-roles-my-roles" ${currentUser?'':'disabled'}>Votre rôle :</button> ${esc(currentRoleSummary)}</p><h3>Rôles d’administration</h3><p>Les rôles d’administration sont utilisés pour accorder l’accès aux actions privilégiées dans Microsoft Entra ID. Nous vous recommandons d’utiliser ces rôles intégrés pour déléguer l’accès à la gestion des autorisations de configuration d’application étendue sans accorder d’accès pour gérer d’autres parties de Microsoft Entra ID, qui ne sont pas liées à la configuration de l’application. <a href="https://learn.microsoft.com/entra/identity/role-based-access-control/permissions-reference" target="_blank" rel="noopener noreferrer">En savoir plus</a>.</p><p><a href="https://learn.microsoft.com/entra/identity/role-based-access-control/overview" target="_blank" rel="noopener noreferrer">En savoir plus sur le contrôle d’accès en fonction du rôle de Microsoft Entra ID</a></p><div class="toolbar">${listSearch('Rechercher par nom ou description')}<div class="entra-roles-filter-anchor"><button type="button" class="btn" data-action="entra-roles-filter-toggle" data-arg="entra-roles-filter" aria-haspopup="menu" aria-expanded="${!!ui.entraRolesFilterPanel}">${icon('filter')} Ajouter des filtres</button>${renderRolesFilterPopup(filters)}</div>${Object.entries(filters).map(([key,value])=>`<span class="entra-roles-filter-pill">${['service','type','unit','privileged'].includes(key)?`<button type="button" data-action="entra-roles-filter-edit" data-arg="${attr(key)}" aria-label="Modifier ${attr(roleFilterLabel(key,value))}">${esc(roleFilterLabel(key,value))}</button>`:`<span>${esc(roleFilterLabel(key,value))}</span>`}<button type="button" data-action="entra-roles-filter-remove" data-arg="${attr(key)}" aria-label="Supprimer ${attr(roleFilterLabel(key,value))}">×</button></span>`).join('')}${filters.service?'<span class="entra-roles-service-limited">Classement partiel</span>':''}</div><div class="entra-roles-table">${table(['',actionBtn('Rôle '+(sort.key==='name'?(sort.desc?'↓':'↑'):'↕'),'entra-roles-sort','name','btn-link'),'Description',actionBtn('Privilégié '+(sort.key==='privileged'?(sort.desc?'↓':'↑'):'↕'),'entra-roles-sort','privileged','btn-link'),actionBtn('Devoirs '+(sort.key==='count'?(sort.desc?'↓':'↑'):'↕'),'entra-roles-sort','count','btn-link'),actionBtn('Type '+(sort.key==='type'?(sort.desc?'↓':'↑'):'↕'),'entra-roles-sort','type','btn-link')],rows,'Aucun rôle trouvé','680px',false)}</div></div></div>`;
  }
