  function renderSignInDetail(x){const tab=ui.signInDetailTab||'basic',tabs=[['basic','Informations de base'],['location','Emplacement'],['device','Informations sur l’appareil'],['auth','Détails d’authentification'],['conditional','Accès conditionnel'],['report','Rapport uniquement']],kv=(label,value)=>infoKV(label,String(value??'—')),device=x.device||{},steps=Array.isArray(x.authenticationDetails)?x.authenticationDetails:[],policies=Array.isArray(x.conditionalAccessPolicies)?x.conditionalAccessPolicies:[];let body='';if(tab==='basic')body=signInColumns.map(([key,label])=>kv(label,x[key])).join('')+kv('Type de connexion',x.kind||'interactive')+kv('Code d’erreur',x.errorCode)+kv('Raison de l’échec',x.failureReason)+(db.premium==='p2'&&x.riskLevel?kv('Niveau de risque',riskLevelLabels[x.riskLevel]||x.riskLevel)+kv('État du risque',riskStateLabels[x.riskState]||riskStateLabels.atRisk)+kv('Détail du risque',x.riskDetail):'');else if(tab==='location')body=kv('Adresse IP',x.ip)+kv('Emplacement',x.location)+kv('Ville',x.city)+kv('Région',x.region)+kv('Pays ou région',x.country);else if(tab==='device')body=kv('Nom de l’appareil',device.name)+kv('ID de l’appareil',device.id)+kv('Système d’exploitation',device.os)+kv('Navigateur',device.browser)+kv('Conforme',device.compliant===undefined?'—':device.compliant?'Oui':'Non')+kv('Géré',device.managed===undefined?'—':device.managed?'Oui':'Non')+kv('Type de jointure',device.trustType);else if(tab==='auth')body=table(['Date','Méthode d’authentification','Détail','Résultat'],steps.map(step=>`<tr><td>${esc(step.date||'—')}</td><td>${esc(step.method||'—')}</td><td>${esc(step.detail||'—')}</td><td>${esc(step.result||'—')}</td></tr>`),'Aucun détail d’authentification disponible.','700px');else {const filtered=policies.filter(p=>tab==='report'?p.reportOnly===true:p.reportOnly!==true);body=table(['Stratégie','Résultat','Contrôles'],filtered.map(p=>`<tr><td>${esc(p.name||'—')}</td><td>${esc(p.result||'—')}</td><td>${esc(Array.isArray(p.controls)?p.controls.join(', '):(p.controls||'—'))}</td></tr>`),'Aucune stratégie disponible pour cet événement.','700px');}return drawer('Détails de l’activité','Journaux de connexion',`<nav class="sub-tabs">${tabs.map(([key,label])=>`<button class="tab ${tab===key?'active':''}" data-action="signin-detail-tab" data-arg="${key}">${label}</button>`).join('')}</nav>${body}`,actionBtn('Fermer','close-modal'),true);}
  function auditScopedUser(){const parts=ui.route.split('/');return parts[0]==='entra'&&parts[1]==='user'&&ui.detailTab==='Audit'?db.users.find(x=>x.id===parts[2])||null:null;}
  function auditTargetsUser(record,user){if(record.targetId)return record.targetId===user.id;const tokens=String(record.target||'').split(/\s*(?:→|\||;)\s*/).map(normal).filter(Boolean),identifiers=[user.id,user.upn,user.displayName].filter(Boolean).map(normal);return identifiers.some(identifier=>tokens.includes(identifier)&&(db.users||[]).filter(x=>[x.id,x.upn,x.displayName].filter(Boolean).some(v=>normal(v)===identifier)).length===1);}
  function auditUserManagement(record){return record.category==='UserManagement'||/^(?:Create user|Update user|Update user profile|Update user account status|Update user principal name|Update selected users|Update selected user properties|Delete user|Restore user|Permanently delete users|Expire deleted users|Reset user password|Revoke simulated sessions|Bulk create simulated M365 users)$/i.test(String(record.action||''));}
  function auditItems(includeSearch=true){const user=auditScopedUser(),period=ui.auditPeriod||'all',result=ui.auditResult||'all',query=includeSearch?normal(ui.search||''):'',now=Date.now();return (Array.isArray(db.audit)?db.audit:[]).filter(x=>{const date=Date.parse(x.at),matchesUser=!user||auditTargetsUser(x,user);return matchesUser&&(!ui.auditCategory||ui.auditCategory==='all'||auditUserManagement(x))&&(period==='all'||Number.isFinite(date)&&date<=now&&date>=now-Number(period)*86400000)&&(result==='all'||x.outcome===result)&&(!query||normal(auditColumns.map(([k])=>x[k]??'').join(' ')).includes(query))&&(ui.auditFilters||[]).every(f=>normal(String(x[f.field]??'')).includes(normal(f.value)));}).slice(0,250000);}
  function renderUsersAudit(){return `${crumb([{text:'Accueil',route:'entra/home'},{text:db.tenant.name,route:'entra/overview'},{text:'Utilisateurs',route:'entra/users'}])}<div class="entra-blade-heading"><h1>Utilisateurs | Journaux d’audit</h1><span>${esc(db.tenant.name)}</span></div><div class="entra-blade-layout">${entraUserNav('entra/audit')}<div class="entra-blade-content">${renderAudit(null,true)}</div></div>`;}
  function renderAudit(user=null,embedded=false){const items=auditItems(false),period=ui.auditPeriod||'all',result=ui.auditResult||'all',selected=Array.isArray(db.auditColumns)?db.auditColumns:auditColumns.map(([k])=>k),cols=auditColumns.filter(([key])=>selected.includes(key));return `${embedded?'':user?`<h2>Journaux d’audit</h2><p>Utilisateur : ${esc(user.displayName)}</p>`:`${crumb([{text:'Accueil',route:'entra/home'},{text:'Surveillance et intégrité'},{text:'Journaux d’audit'}])}<div class="entra-blade-heading"><h1>Journaux d’audit</h1><span>Microsoft Entra ID</span></div>`}<div class="entra-info">Les événements affichés correspondent aux opérations enregistrées dans le laboratoire local.</div><div class="toolbar entra-command">${actionBtn(icon('refresh')+' Actualiser','refresh')}${actionBtn(icon('download')+' Télécharger','open-modal','audit-download')}${actionBtn('Colonnes','open-modal','audit-columns')}${actionBtn('Ajouter des filtres','open-modal','audit-filter')}</div><div class="toolbar"><label>Date <select data-audit-period>${[['all','Toutes les dates'],['1','24 dernières heures'],['7','7 derniers jours'],['30','30 derniers jours']].map(([key,label])=>`<option value="${key}" ${period===key?'selected':''}>${label}</option>`).join('')}</select></label><label>Catégorie <select data-audit-category><option value="all" ${!ui.auditCategory||ui.auditCategory==='all'?'selected':''}>Tout</option><option value="UserManagement" ${ui.auditCategory==='UserManagement'?'selected':''}>UserManagement</option></select></label><label>Résultat <select data-audit-result>${[['all','Tous'],['Success','Réussite'],['Failure','Échec']].map(([key,label])=>`<option value="${key}" ${result===key?'selected':''}>${label}</option>`).join('')}</select></label>${listSearch('Rechercher')}</div>${(ui.auditFilters||[]).length?`<div class="toolbar">${ui.auditFilters.map((f,i)=>actionBtn(esc(auditColumns.find(([k])=>k===f.field)?.[1]||f.field)+' : '+esc(f.value)+' ×','audit-filter-remove',String(i),'entra-filter-pill')).join('')}${actionBtn('Effacer tous les filtres','audit-filter-clear','','btn-link')}</div>`:''}<p>${items.length} résultat(s)</p>${table(cols.map(([,label])=>label),items.map(x=>`<tr data-filter-row="${attr(normal(auditColumns.map(([k])=>x[k]??'').join(' ')))}">${cols.map(([key],i)=>`<td>${i===0?actionBtn(esc(x[key]??'—'),'audit-detail',String((db.audit||[]).indexOf(x)),'btn-link'):esc(x[key]??'—')}</td>`).join('')}</tr>`),'Aucun événement d’audit disponible.','900px')}`;}
  function renderApps(){const tab=ui.appListTab||'owned',tabs=[['Toutes les applications','all'],['Applications détenues','owned'],['Applications supprimées','deleted'],['Deactivated applications','inactive']];const items=tab==='deleted'?(db.deletedApps||[]):tab==='inactive'?db.apps.filter(a=>a.disabled):tab==='owned'?db.apps.filter(a=>a.ownerId==='u01'):db.apps;const rows=items.map(a=>`<tr data-filter-row="${attr(normal(a.name+' '+a.clientId))}"><td>${tab==='deleted'?esc(a.name):link(a.name,'entra/app/'+a.id)}</td><td>${esc(a.clientId)}</td><td>${esc(a.created||'—')}</td><td>${tab==='deleted'?actionBtn('Restaurer','restore-app',a.id,'small'):'Non simulé'}</td></tr>`);return `${crumb([{text:'Accueil',route:'entra/home'},{text:db.tenant.name,route:'entra/overview'}])}${title('Inscriptions d’applications')}<div class="toolbar entra-command">${actionBtn(icon('plus')+' Nouvelle inscription','open-modal','create-app')}${actionBtn(icon('refresh')+' Actualiser','refresh')}</div><div class="entra-info">Données fictives : les inscriptions et leurs modifications sont simulées localement. Les certificats et secrets ne sont pas simulés. Les applications devraient utiliser Microsoft Authentication Library (MSAL) et Microsoft Graph.</div><div class="sub-tabs">${tabs.map(([label,key])=>`<button class="tab ${tab===key?'active':''}" data-action="entra-app-list-tab" data-arg="${key}">${esc(label)}</button>`).join('')}</div><div class="toolbar">${listSearch('Commencez à taper un nom ou un ID d’application (client) pour filtrer')}</div>${table(['Nom d’affichage','ID d’application (client)','Date de création',tab==='deleted'?'Action':'Certificats & secrets'],rows,'Aucune application trouvée.','850px')}`;}
  function renderApp(appId){const app=db.apps.find(a=>a.id===appId);if(!app)return renderFallback('Application introuvable');const tab=ui.appDetailTab||'Overview',tabs=[['Vue d’ensemble','Overview','info'],['Authentification','Authentication','key'],['Autorisations API','Permissions','shield']];let content='';if(tab==='Overview')content=`<div class="toolbar entra-command">${actionBtn(icon('trash')+' Supprimer','delete-app',app.id)}${actionBtn(icon('refresh')+' Actualiser','refresh')}</div><h3>Éléments essentiels</h3>${infoKV('Nom d’affichage',app.name)}${infoKV('ID d’application (client)',app.clientId)}${infoKV('ID d’objet',app.id)}${infoKV('ID de l’annuaire (locataire)',db.tenant.id)}${infoKV('Types de comptes pris en charge',({single:'Locataire unique',multi:'Plusieurs locataires Entra ID','multi-personal':'Plusieurs locataires et comptes personnels',personal:'Comptes personnels uniquement'})[app.accountType||'single'])}${infoKV('URI de redirection',app.redirect||'Non configuré')}`;else if(tab==='Authentication')content=`<h3>Configurations de plateforme</h3>${infoKV('Plateforme',app.type||'Non configurée')}${infoKV('URI de redirection',app.redirect||'Non configuré')}`;else content=`<div class="toolbar entra-command">${actionBtn(icon('plus')+' Ajouter une autorisation','open-modal','add-app-permission:'+app.id)}</div>${table(['API / autorisation','Type','Statut'],app.permissions.map(p=>`<tr><td>${esc(p)}</td><td>${p==='Directory.Read.All'?'Application':'Déléguée'}</td><td>${app.consent==='Granted'?'Accordé':'Non accordé'}</td></tr>`),'Aucune autorisation.')}`;
    return `${crumb([{text:'Accueil',route:'entra/home'},{text:'Inscriptions d’applications',route:'entra/apps'},{text:app.name}])}<div class="entra-blade-heading"><h1>${esc(app.name)}${tab==='Overview'?'':' | '+esc(tabs.find(t=>t[1]===tab)[0])}</h1><span>Inscription d’application</span></div><div class="entra-blade-layout"><nav class="entra-blade-nav" aria-label="Menu de l’application">${tabs.map(([label,key,ico])=>`<button class="entra-blade-link ${key===tab?'active':''}" data-action="entra-app-detail-tab" data-arg="${key}">${icon(ico)}${esc(label)}</button>`).join('')}</nav><div class="entra-blade-content">${content}</div></div>`;}
