  function validateAuWizard(){const d=ui.auWizard;if(!d.name){errorForm('Le nom est obligatoire.');return false;}if(db.aus.some(a=>normal(a.name)===normal(d.name))){errorForm('Une unité portant ce nom existe déjà.');return false;}if(db.premium==='free'&&Object.values(d.assignments).some(ids=>ids.length)){errorForm('Une attribution de rôle à portée limitée nécessite Entra ID P1 ou P2.');return false;}return true;}
